SELECT 'moj-all-verified-judgments-review-002-chunk-090' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"a36c5342-5df4-5f0d-ae80-1528886da3ea","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد الترويج والتعاطي -تستر -حيازة أدوات عليها آثار احلشيش -سيجارة بها حشيش -قيادة سيارة حتت تأثير املخدر -تعزير بالسجن واجللد.","document_number":"33339772","case_number":"33405805","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف احلمد هلل وحده","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/13","year":"1434","subject":"مخدرات -حيازة حشيش بقصد الترويج والتعاطي -تستر -حيازة أدوات عليها آثار احلشيش -سيجارة بها حشيش -قيادة سيارة حتت تأثير املخدر -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 33339772 :‬تاريخه ‪1433/7/13 :‬هـ‬\n                         ‫رقم الدعوى ‪33405805 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3428035‬تاريخه‪1434/02/03:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬حيــازة حشــيش بقصــد الترويــج والتعاطــي ‪ -‬تســتر‪ -‬حيــازة‬\n       ‫أدوات عليهــا آثــار احلشــيش ‪ -‬ســيجارة بهــا حشــيش ‪ -‬قيــادة ســيارة‬\n                               ‫حتــت تأثيــر املخــدر ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n                                 ‫‪ -1‬قوله تعالى ( وتعاونوا على البر و التقوى )‬\n       ‫‪ -2‬قولــه تعالــى ( إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن آمنــوا‬\n                                                               ‫لهــم عــذاب أليــم )‬\n       ‫‪ -3‬املــادة (‪ )41‬و املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫ا لعقليــة‬\n\n\n\n\n       ‫الئحــة الدعــوى العامــة ضــد ثالثــة أشــخاص بتوجيــه االتهــام إلــى األول‬\n       ‫بحيازة كمية من احلشــيش املخدر ومشــرط و مقص بها آثار احلشــيش‬\n       ‫بقصــد الترويــج والتعاطــي و حيــازة ســيجارة ملفوفــة ثبــت احتوائهــا علــى‬\n       ‫املــادة الفعالــة للحشــيش املخــدر بقصــد التعاطــي و تعاطيــه لهــا و للثانــي‬\n       ‫بحيــازة حشــيش و بيــع ســيجارة ملفوفــة ثبــت احتوائهــا علــى احلشــيش‬\n       ‫املخــدر بقصــد التعاطــي و تعاطيــه لهــا أثنــاء قيــادة املركبــة وإلــى‬\n       ‫الثالــث بالتســتر عليهمــا‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليهــم و‬\n\n‫‪25‬‬\n\f‫احلكــم علــى األول بالســجن و اجللــد و الغرامــة و املنــع مــن الســفر و علــى‬\n‫الثانــي بالســجن و املنــع مــن الســفر و علــى الثالــث بعقوبــة تعزيريــة لقــاء‬\n‫تســتره علــى األول و الثانــي‪ ،‬واثبــات قيــادة الثانــي للســياره حتــت تأثيــر‬\n‫املخــدر وإفهامــه بــأن عقابــه عائــد لولــي األمــر‪ ،‬مت القبــض علــى املدعــى‬\n‫عليهــم بعــد مشــاهدة األول يســتلم مــن الثانــي و الثالــث و تبــن أن مــا‬\n‫اســتلمه حشــيش مخــدر‪ ،‬وقــد مت ســماع الدعــوى يف حــق املدعــي عليــه‬\n‫األول كونــه ســجني أمــا املدعــى عليهمــا الثانــي و الثالــث فلــم يحضــرا‬\n‫ومت إرجــاء احلكــم حلــن حضورهمــا‪ ،‬إقــرار املدعــى عليــه باحليــازة‬\n‫والقصــد منهــا االســتخدام الشــخصي وإنــكاره الترويــج‪ ،‬توجيــه‬\n‫الشــبهة للمدعــى عليــه بالترويــج لوجــود املشــرط واملســطرة معــه وكبــر‬\n‫الكميــة‪ ،‬إثبــات إدانــة املدعــى عليــه بالتعاطــي‪ ،‬إقامــة حــد املســكر‬\n‫علــى املدعــى عليــه‪ ،‬تعزيــر املدعــى عليــه بالســجن واجللــد و املنــع مــن‬\n                       ‫الســفر‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33405805‬‬\n‫وتاريــخ ‪ 1433/06/16‬ه ـ املقيــدة باحملكمــة برقــم ‪331123077‬‬\n‫وتاريــخ ‪ 1433/06/15‬ه ـ ففــي يــوم الثالثــاء املوافــق‪1433/07/01‬‬\n‫ه ـ افتتحــت اجللســة الســاعة ‪ 07 : 30‬وفيهــا حضــر املدعــي العــام‬\n‫بصفتــي مدعيــا عامــا بدائــرة االدعــاء العــام مبحافظــة جــدة أدعــي علــى‬\n‫‪ )21( .......‬عام ـ ًا ســعودي اجلنســية مبوجــب رقــم (‪ )........‬املهنــة موظــف‬\n\n                                                                                      ‫‪26‬‬\n\f     ‫خــاص متعلــم موقــوف بالســجن العــام مبوجــب أمــر متديــد التوقيــف رقــم‬\n     ‫(ه ـ م‪ )28419/5/2‬وتاريــخ ‪1433/4/26‬ه ـ اســتناد ًا للقــرار الــوزاري‬\n     ‫رقــم (‪ )1900‬يف ‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام‬\n     ‫اإلجــراءات اجلزائيــة و‪ )21( ......‬عام ـ ًا ‪ ........‬ســعودي اجلنســية مبوجــب‬\n     ‫الهويــة الوطنيــة رقــم (‪ ، )......‬املهنــة موظــف خــاص متعلــم مفــرج عنــه‬\n     ‫بالكفالــة احلضوريــة بتاريــخ ‪1433/4/26‬ه ـ مبوجــب أمــر اإلفــراج رقــم‬\n     ‫(ه ـ م‪ )28063/5/2‬وتاريــخ ‪1433/4/25‬ه ـ اســتناد ًا للمــادة (‪ )120‬مــن‬\n     ‫نظــام اإلجــراءات اجلزائيــة و‪ )28( ........‬عامـ ًا ســعودي اجلنســية مبوجــب‬\n     ‫الهويــة الوطنيــة رقــم (‪ ).........‬املهنــة موظــف خــاص متعلــم مفــرج عنــه‬\n     ‫بالكفالــة احلضوريــة بتاريــخ ‪1433/4/25‬ه ـ مبوجــب أمــر اإلفــراج‬\n     ‫رقــم (ه ـ م‪ )28063/5/2‬وتاريــخ ‪1433/4/25‬ه ـ اســتناد ًا للمــادة (‪)120‬‬\n     ‫مــن نظــام اإلجــراءات اجلزائيــة املقبــوض عليهــم بتاريــخ ‪1433/4/23‬ه ـ‬\n     ‫وردت إخباريــه مــن أحــد املتعاونــن مفادهــا أن املدعــى عليــه األول يــروج‬\n     ‫احلشــيش املخــدر و يســتخدم لهــذا الغــرض مركبــه مــن نــوع هونــداي‬\n     ‫حتمــل اللوحــة رقــم (‪).... ...‬وأنــه ال يعــرف رقــم هاتفــه وال يســتطيع‬\n     ‫الشــراء منــه ‪ ،‬وعليــه مت رصــد حتركاتــه ويف تلــك األثنــاء حضــرت‬\n     ‫مركبــه مــن نــوع كامــري بقيــادة الثانــي وبرفقــه الثالــث ‪ ،‬وتوقفــت‬\n     ‫بجــوار مركبــة األول الــذي شــوهد بأخــذ شــيء مــن ســيارته ويســتقل‬\n     ‫مركبــة الثانــي برفــق الثالــث ومبتابعتهــم والقبــض عليهــم ضبــط مــع‬\n     ‫الثانــي ‪ :‬ربــع ســيجارة تــزن (‪ )0.2‬عشــري اجلــرام يشــتبه أن تكــون‬\n     ‫مخلوطــة مبــادة حشــيش مخــدر وشــوهد األول ‪ :‬يرمــي ســيجارة حتــت‬\n     ‫قدميــه تــزن (‪ )0.2‬عشــري اجلــرام يشــتبه أن تكــون حشــيش مخــدر‬\n     ‫‪ ،‬ومبناقشــتهم عــن مصــدر احلشــيش املخــدر أفــاد الثانــي بــأن األول‬\n\n\n‫‪27‬‬\n\f‫قــام بإهدائــه ســيجارة احلشــيش املخــدر فأنكــر األول ذلــك وبســؤال‬\n‫األول عــن مقــر ســكنه ومركبتــه أنكــر وجــود مســكن أو مركبــه‬\n‫لــه وباصطحابــه للمركبــه ‪ ........‬التــي كان يســتقلها وبفتحهــا مبفتــاح‬\n‫كان بحوزتــه وتفتيشــها وجــد علــى املقعــدة األماميــة قطعــة بلــغ وزنهــا‬\n‫(‪ )53‬ثالثة وخمســن جرام ًا يشــتبه أن تكون احلشــيش املخدر ومشــرط‬\n‫ومســطرة عليهــا آثــار مــادة احلشــيش املخــدر وأثبــت التقريــر الكيميائــي‬\n‫الشــرعي رقم (‪/1553‬ك ش م) لعام ‪1433‬هـ إيجابية العينات من املواد‬\n‫املضبوطــة واملرســلة للتحليــل ملــادة احلشــيش املخــدر واحتــواء العينــات‬\n‫(أ‪،‬ب‪،‬ج‪،‬د‪،‬هــ) علــى املــادة الفعالــة لــه املدرجــة باجلــدول رقــم (‪ )1‬فئــة‬\n‫(أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة باســتجواب‬\n‫األول ‪ :‬أقــر بحيــازة مــا مت ضبطــه معــه وعائديتهــا لــه بقصــد التعاطــي‬\n‫وأقــر بحيــازة املشــرط لتقطيــع احلشــيش املخــدر للتعاطــي وبتعاطيــه مــن‬\n‫احلشــيش املخــدر املضبــوط ولنوعــه ســابق ًا باســتجواب الثانــي ‪ :‬أقــر‬\n‫بحيــازة ســيجارة تــزن (‪ )0.2‬عشــري اجلــرام مــن احلشــيش املخــدر بقصــد‬\n‫التعاطــي وتعاطيــه منهــا ولنوعهــا ســابق ًا وأســفر التحقيــق بتوجيه االتهام‬\n‫إلــى األول بحيــازة (‪ )53‬ثالثــة وخمســن جرام ـ ًا مــن مــادة احلشــيش‬\n‫املخــدر ومشــرط ومســطرة عليهمــا آثــار ثبــت إيجابيتهــا لــذات املــادة‬\n‫بقصــد الترويــج والتعاطــي وحيازتــه ربــع ســيجارة ملفوفــة تــزن (‪)0.2‬‬\n‫عشــري اجلــرام ثبــت احتوائهــا علــى املــادة الفعالــة للحشــيش املخــدر‬\n‫بقصــد التعاطــي وتعاطيــه منهــا ولنوعهــا ســابق ًا والــى الثانــي بحيــازة ربــع‬\n‫ســيجارة ملفوفــة تــزن (‪ )0.2‬عشــري اجلــرام ثبــت احتوائهــا علــى املــادة‬\n‫الفعالــة للحشــيش املخــدر بقصــد التعاطــي وتعاطيــه منهــا أثنــاء قيادتــه‬\n‫املركبــة وتعاطيــه لنوعهــا ســابق ًا والــى الثالــث بالتســتر عليهمــا وذلــك‬\n\n\n                                                                                       ‫‪28‬‬\n\f     ‫لألدلــة والقرائــن التاليــة مــا ورد يف اعترافــا األول والثانــي املــدون بدفتــر‬\n     ‫التحقيــق املرفــق لفــة (‪ )29‬مــا ورد بشــهادة الشــهود الــواردة يف محضــر‬\n     ‫الضبــط املنــوه عنــه املرفــق لفــة (‪ )1‬مــا ورد يف التقريــر الكيميائــي‬\n     ‫الشــرعي املنــوه عنــه املرفــق لفــة (‪ )37‬كبــر حجــم الكميــة املضبوطــة‬\n     ‫مــع األول واإلخباريــة الــواردة عنــه وضبط أداة املســطرة مبركبته والتي‬\n     ‫عــادة مــا يســتخدمها املروجــن يف عملياتهــم قرائــن علــى أن مــا ضبــط‬\n     ‫كان معــد ًا للترويــج أيضـ ًا وحيــث إن مــا أقــدم عليــه املدعــى عليهــم وهــم‬\n     ‫بكامــل أهليتهــم املعتبــرة شــرع ًا مــن األفعــال احملرمــة شــرع ًا واملجرمــة‬\n     ‫نظام ـ ًا طبق ـ ًا للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n     ‫‪،‬واملعاقــب عليهــا وفق ـ ًا للمادتــن (‪ )41،38‬مــع مراعــاة مــا ورد باملــادة‬\n     ‫(‪ )62‬مــن ذات النظــام لــذا فإننــي أطلــب إثبات ما أســند إليهم ومعاقبتهم‬\n     ‫بالعقوبــات األصليــة والتكميليــة التاليــة بالســجن واجللــد والغرامــة‬\n     ‫لقــاء مــا أســند لــأول اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه بالســجن لقــاء مــا‬\n     ‫أســند للثانــي اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة‬\n     ‫املخــدرات واملؤثــرات العقليــة املشــار إليــه منعهمــا مــن الســفر خلــارج‬\n     ‫اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتهمــا وفقـ ًا للفقــرة (‪ )1‬مــن املــادة‬\n     ‫(‪ )56‬مــن نظــام املخــدرات املشــار إليــه كمــا اطلــب احلكــم علــى الثالــث‬\n     ‫بعقوبــة تعزيريــة لقــاء تســتره علــى األول والثانــي كمــا اطلــب إثبــات‬\n     ‫إدانــة الثانــي بقيــادة املركبــة حتــت تأثيــر املخــدر اســتناد ًا للفقــرة (‪)1‬‬\n     ‫مــن املــادة (‪ )68‬مــن نظــام املــرور الصــادر باملرســوم امللكي رقــم (م‪)85/‬‬\n     ‫وتاريــخ ‪1428/10/26‬ه ـ وإفهامــه بــأن عقابــه عائــد لولــي األمــر مــن قبل‬\n\n\n‫‪29‬‬\n\f‫اجلهــة املختصــة وبعــرض مــاورد بدعــوى املدعــي العــام علــى املدعــى عليــه‬\n‫احلاضــر باملجلــس الشــرعي أجــاب قائــا مــاورد يف دعــوى املدعــي العــام‬\n‫مــن توجيــه االتهــام لــي بحيــازة ثالثــة وخمســن جــرام مــن مــادة احلشــيش‬\n‫املخــدر ومشــرط ومســطرة بهــا أثــار احلشــيش املخــدر فصحيــح ولكــن‬\n‫ليــس بقصــد الترويــج والتعاطــي كمــا ورد يف دعــوى املدعــي العــام بــل‬\n‫بقصــد التعاطــي فقــط ومــاورد مــن حيازتــي ســيجارة تــزن عشــري اجلــرام‬\n‫حتتــوي علــى احلشــيش املخــدر بقصــد التعاطــي وأنــي أتعاطــى احلشــيش‬\n‫املخــدر مــن الســابق فصحيــح هــذا جوابــي علــى الدعــوى وبعــرض ذلــك‬\n‫علــى املدعــي العــام قــال الصحيــح ماذكــرت وبســؤاله هــل لديــه بينــه‬\n‫علــى ماذكــرت قــال نعــم وبينتــي تتمثــل يف اعتــراف املتهمــن األول‬\n‫والثانــي املــدون بدفتــر التحقيــق املرفــق لفــة (‪)29‬شــهادة الشــهود الــواردة‬\n‫يف محضــر الضبــط املنــوه عنــه املرفــق لفــة رقــم (‪)1‬التقريــر الكيميائــي‬\n‫الشــرعي املنــوه عنــه املرفــق لفــة (‪)37‬كبــر حجــم الكميــه املضبوطــة‬\n‫مــع األول واإلخباريــة الــواردة عنــه وضبــط أداه املســطرة بســيارته والتــي‬\n‫عــادة مــا يســتخدمها املروجــن يف عملياتهــم قرائــن علــى أن مــا ضبــط‬\n‫كان معــدا للترويــج أيضــا عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وإقــرار املدعــى عليــه بحيــازة ســيجارة تــزن عشــري اجلــرام مــن‬\n‫احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه للحشــيش املخــدر فبنــاء على‬\n‫جميــع مــا تقــدم ونظــرا لضبــط املســطرة واملشــرط وبهــا أثــار احلشــيش‬\n‫املخــدر مــع املدعــى عليــه وأقراراملدعــى عليــه بعائديتهــا لــه وحيــث‬\n‫أن مثــل تلــك األدوات يســتخدمها مروجــي احلشــيش يف العــادة ونظــرا‬\n‫لكبــر الكميــة املضبوطــة بحوزتــه وحيــث أن مــا قــدم املدعــى العــام‬\n‫مــن أدلــه وقرائــن ال يكفــي إلثبــات قصــد الترويــج وإمنــا يقــوى الشــبهة‬\n\n\n                                                                                     ‫‪30‬‬\n\f     ‫يف ذلــك وجلميــع مــا تقــدم ولقولــه تعالــى (وتعاونــوا علــى البــر والتقــوى‬\n     ‫وال تعاونــوا علــى اإلثــم والعــدوان ) وقولــه تعالــى (إن الذيــن يحبــون أن‬\n     ‫تشــيع الفاحشــة يف الذيــن آمنــوا لهــم عــذاب أليــم ) ولكــون هــذه اآلفــة‬\n     ‫مهلكــه للديــن مضيعــة للمــال والوقــت مدمــرة للعقــل ومفســدة للعــرض‬\n     ‫وجلميــع مــا تقــدم فقــد ثبــت لــدي أدانــه املدعــى عليــه بحيــازة ثالثــة‬\n     ‫وخمســن جــرام مــن احلشــيش املخــدر وســيجارة تــزن عشــري اجلــرام‬\n     ‫جميعهــا مــن احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه لنوعهــا مــن‬\n     ‫الســابق وقــوه الشــبهة يف حيــازة الكميــه املتقدمــة مــن احلشــيش بقصــد‬\n     ‫الترويــج وحكمــت عليــه لقــاء ذلــك مبــا يلــي أوال ســجنه ملــده ســنتني‬\n     ‫اســتناد للمــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n     ‫ثانيــا ســجنه ملــده ســنه ونصــف وجلــدة ثالثمائــة ســوط علــى دفعــات‬\n     ‫كل دفعــة خمســن ســوط ًا وبــن كل دفعــة والتــي تليهــا مــده ال تقــل‬\n     ‫عــن خمســة أيــام ودفعــة غرامــة ماليــه قدرهــا عشــرة األف ريــال نظيــر‬\n     ‫الشــبهة القويــة يف حيازتــه احلشــيش املخــدر بقصــد الترويــج ثالثــا منعــه‬\n     ‫مــن الســفر ملــده ثــاث ســنوات ونصــف وفقــا للمــادة (‪ )56‬مــن النظــام‬\n     ‫املشــار إليهــا رابعــا جلــدة حــد املســكر ثمانــن ســوط ًا دفعــة واحــدة‬\n     ‫نظيــر تعاطيــه للحشــيش املخــدر مــن الســابق وأرجــأت احلكــم علــى‬\n     ‫املدعــى عليــه الثانــي والثالــث إلــى حــن حضورهــم وأمــرت املدعــي العــام‬\n     ‫بإحضارهــم وجــرى عرضــه علــى الطرفــن قــرار جميعــا عــدم القناعــة‬\n     ‫وطلبــا االســتئناف فأجبتهمــا لطلبهمــا وأفهمتهمــا مبقتضــى تعليمــات‬\n     ‫االســتئناف جــرى النطــق باحلكــم يف متــام الســاعة الســابعة وخمســة‬\n     ‫واربعــن دقيقــة صباحــا وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1433/07/01‬ه ـ‬\n\n\n‫‪31‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة ففــي يــوم االربعــاء املوافــق‪ 1433/11/3‬ه ـ افتتحــت‬\n‫اجللســة الســاعة الثامنــة وحيــث وردتنــا املعاملــة مــن محكمة االســتئناف‬\n‫مبكــة املكرمــة برقــم ‪ 331828826‬يف ‪ 1433/10/25‬وبرفقهــا قــرار‬\n‫املالحظــة الصــادر مــن الدائــرة اجلزائيــة الثالثــة برقــم ‪ 33432064‬يف‬\n‫‪1433/10/21‬ه ـ نــص احلاجــة منــه (وبدراســة القــرار وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقــرر اعادتهــا لفضيلــة حاكمهــا ملالحظــة أنــه‬\n‫لــم يــرد اســم املدعــي العــام يف مســتهل الدعــوى وال يف اي جلســة مــن‬\n‫جلســلت القضيــة ولــم يكتــب اســمه يف صــورة الضبــط كمــا هــو‬\n‫الواضــح مــن صــورة الضبــط املدرجــة كمــا انــه لــم يوضــح اســم املدعــى‬\n‫عليــه الــذي حضــر عنــد القاضــي وحكــم عليــه القاضــي وإن كان يفهم‬\n‫مــن اإلجابــة أنــه االول لكــن ذلــك ال يكفــي ألنــه جــاء خلــط يف اجابتــه‬\n‫فينبغــي ذكــر اســم املدعــى عليــه الــذي حضــر عنــد القاضــي وحكــم‬\n‫عليــه ملالحظــة ذلــك واهلل املوفــق) وموقــع ومختــم مــن اصحــاب الفضيلــة‬\n‫اعضــاء الدائــرة اجلزائيــة الثالثــة وهــم كال مــن الشــيخ ‪ .....‬والشــيخ د‪.....‬‬\n‫والشــيخ ‪ .......‬وعليــه فأجيــب اصحــاب الفضيلــة بأنــه نظــرا لوجاهــة‬\n‫ماذكــر فــإن اســم املدعــى عليــه هــو ‪ ....‬ورقــم تكليفــه مــن مرجعــه‬\n‫هــو ‪15832‬يف ‪1433/3/6‬ه ـ وامــا املدعــى عليــه الــذي حضــر وحكــم‬\n‫عليــه هــو ‪ ......‬وامــا املدعــى عليــه الثانــي والثالــث فلــم يحضــرا وأرجئــت‬\n‫احلكــم عليهــم الــى حــن حضورهــم وأمــرت املدعــي العــام بإحضارهــم‬\n‫جــرى قفلهــا يف متــام الســاعة الثامنــة والربــع وصلــى اهلل وســلم علــى نبينــا‬\n                                                  ‫محمــد والــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n\n\n                                                                                       ‫‪32‬‬\n\f     ‫مبحافظــة جــدة ففــي يــوم االحــد املوافق‪ 1434/1/4‬هـ افتتحت اجللســة‬\n     ‫الســاعة التاســعة وحيــث وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n     ‫مبكــة املكرمــة برقــم ‪ 332106911‬يف ‪1433/12/22‬ه ـ وبرفقهــا‬\n     ‫قــرار املالحظــة الصــادر مــن الدائــرة اجلزائيــة الثالثــة برقــم ‪33471121‬‬\n     ‫يف ‪1433/12/1‬ه ـ نــص احلاجــة منــه (وبدراســة القــرار وصــورة ضبطــه‬\n     ‫والئحتــه االعتراضيــة تقــرر اعادتهــا لفضيلــة حاكمهــا ملالحظــة ان‬\n     ‫فضيلتــه ذكــر ان اســم املدعــي عليــه هــو ‪ ......‬حــن انــه ذكــر يف صــورة‬\n     ‫الضبــط ان اســم املدعــي العــام ‪ ......‬فعلــى فضيلتــه حتريــر الصــواب‬\n     ‫ملالحظــة ذلــك واهلل املوفــق) وموقــع ومختــم مــن اصحــاب الفضيلــة‬\n     ‫اعضــاء الدائــرة اجلزائيــة الثالثــة وهــم كال مــن الشــيخ ‪ ....‬والشــيخ‬\n     ‫‪ ....‬والشــيخ د‪ ......‬وعليــه فأجيــب عمــا ذكــره اصحــاب الفضيلــة‬\n     ‫بــأن املدعــي العــام هــو ‪ .....‬ورقــم تكليفــه مــن مرجعــه هــو ‪15832‬يف‬\n     ‫‪1433/3/6‬ه ـ وامــا املدعــى عليــه فهــو ‪ .....‬وقــد جــرى تصحيــح اخلطــأ‬\n     ‫الواقــع يف الســطر احلــادي عشــر مــن الصفحــة الرابعــة مــن القــرار عــن‬\n     ‫طريــق التقويــس عليــه يف اصــل القــرار وقــررت اعــادة كامــل اوراق‬\n     ‫املعاملــة الــى محكمــة االســتئناف التخــاذ مــا يــراه اصحــاب الفضيلــة‬\n     ‫‪ ............‬قفلهــا يف متــام الســاعة التاســعة والربــع وصلــى اهلل وســلم علــى‬\n                                               ‫نبينــا محمــد والــه وصحبــه وســلم‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪:‬‬\n     ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة‬\n     ‫االســتئناف يف منطقــة مكــة املكرمــة جــرى منــا االطــاع علــى‬\n     ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة‬\n     ‫املســاعد رقــم‪ 34/10330‬وتاريخ‪1434/1/20‬ه ـ املرفــق بهــا القــرار‬\n\n\n‫‪33‬‬\n\f‫الصــادر مــن فضيلــة الشــيخ‪ .... /‬القاضــي باحملكمــة اجلزائيــة بجــده‬\n‫برقــم‪ 33339772‬وتاريــخ ‪1433/7/13‬ه ـ ‪ ،‬املتضمــن دعــوى املدعــي‬\n‫دون بباطــن‬‫العــام ضــد‪ .... /‬ورفقــاه املتهــم يف مخــدرات احملكــوم مبــا ّ‬\n‫القــرار وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n‫املوافقــة علــى احلكــم بعــد االيضــاح االخيــر واهلل املوفــق وصلــى اهلل‬\n                          ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                ‫‪34‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":25,"source_page_end":34,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"019c2e9fd3715e4371b4dc157be775d7ee125ea5e811817d4811f52f851267d7","normalized_text_hash":"e0e904a0b14660c37024a782a84500df850f86da2c978436165699c5afe33ca7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p25-33339772"},{"id":"81cb4306-744f-5d64-a937-e1dfd1050b83","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة قطعة من مادة احلشيش املخدر لغرض االستعمال -تعاطي سيجارة وجد حتتوي على احلشيش املخدر- تستر على مصدر املخدرات -إقامة حد املسكر -تعزير املدعى عليه بالسجن واجللد واملنع من السفر -عدم البينة على قيادة السيارة حتت تأثير املسكر -صرف نظر.","document_number":"33445090","case_number":"33410920","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/2","year":"1434","subject":"مخدرات -حيازة قطعة من مادة احلشيش املخدر لغرض االستعمال -تعاطي سيجارة وجد حتتوي على احلشيش املخدر- تستر على مصدر املخدرات -إقامة حد املسكر -تعزير املدعى عليه بالسجن واجللد واملنع من السفر -عدم البينة على قيادة السيارة حتت تأثير املسكر -صرف نظر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪33445090:‬تاريخه ‪1433/11/2:‬هـ‬\n                      ‫رقم الدعوى ‪33410920 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 3432597‬تاريخه‪1434/02/09:‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬حيــازة قطعــة مــن مــادة احلشــيش املخــدر لغــرض‬\n     ‫االســتعمال‪ -‬تعاطــي ســيجارة وجــد حتتــوي علــى احلشــيش املخــدر‪-‬‬\n     ‫تســتر علــى مصــدر املخــدرات ‪ -‬إقامــة حــد املســكر ‪ -‬تعزيــر املدعــى عليــه‬\n     ‫بالســجن واجللــد واملنــع مــن الســفر ‪ -‬عــدم البينــة علــى قيــادة الســيارة‬\n                                              ‫حتــت تأثيــر املســكر ‪ -‬صــرف نظــر‪.‬‬\n\n\n\n\n                       ‫املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n     ‫الئحــة الدعــوى ضــد املدعــى عليــه بحيــازة قطعــة مــن احلشــيش املخــدر‬\n     ‫لغــرض االســتعمال واســتعماله لهــا مــن الســابق وقيــادة الســيارة حتــت‬\n     ‫تأثيــر احلشــيش املخــدر وتســتره علــى مصــدر املخــدرات‪ ،‬وطلــب املدعــي‬\n     ‫العــام إثبــات مــا اســند إليــه بالعقوبــة الــواردة يف املــادة (‪ )41/1‬مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة ومنعــه مــن الســفر والفصــل يف‬\n     ‫قيادتــه للســيارة حتــت تأثيــر تعاطــي احلشــيش املخــدر وبعقوبــة تعزيريــة‬\n     ‫لتســتره علــى مصــدر املخــدرات‪ ،‬مت القبــض علــى املدعــى عليــه بعــد‬\n     ‫االشــتباه بــه واســتيقافه مــن قبــل الدوريــات األمنيــة وبتفتيشــه عثــر معــه‬\n     ‫علــى قطعــة مــن احلشــيش املخــدر‪ ،‬إقــراره باحليــازة للحشــيش املخــدر‬\n\n‫‪35‬‬\n\f‫لغــرض االســتخدام واســتخدامه للحشــيش املخــدر‪ ،‬وإنــكاره قيــادة‬\n‫الســيارة حتــت تأثيــر احلشــيش املخــدر عــدم وجــود بينــة للمدعــى العــام‬\n‫لقيــادة الســيارة حتــت تأثيــر احلشــيش إقامــة حــد املســكر علــى املدعــى‬\n‫عليــه‪ ،‬تعزيــر املدعــى عليــه بالســجن واجللــد واملنــع مــن الســفر‪ ،‬صــرف‬\n‫النظــر عــن إثبــات اإلدانــة بقيادة الســيارة وهو حتت تأثير املســكر لعدم‬\n ‫ثبــوت موجبــه‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف بالريــاض ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا د‪ ....... /‬القاضي يف احملكمة اجلزائية‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33410920‬وتاريــخ ‪ 1433/06/18‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331148189‬وتاريــخ ‪ 1433/06/18‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1433/11/02‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ .....‬وقــدم الئحــة الدعــوى قائــا بصف ــتي‬\n‫مدعيـ ًا عامـ ًا يف دائـرة االدعـاء العـام مبدينة الرياض أدعـي على ‪......../‬‬\n‫‪ 26‬ســنة ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).......‬يقيــم‬\n‫مبدينــة الريــاض مفــرج عنــه بالكفالــة احلضوريــة‪ .‬حيــث انــه بتاريــخ‬\n‫‪1432/12/20‬ه ـ قبــض علــى املذكــور مــن قبــل دوريــات امــن الطــرق‬\n‫بــال‪ ....‬اثــر االشــتباه بــه عندمــا كان يقــود ســيارة وبتفتيشــه عثــر علــى‬\n‫قطعــة بنيــة اللــون بلــغ وزنهــا (‪ )6‬ســتة جرامــات يشــتبه ان تكــون مــن‬\n‫مــادة احلشــيش املخــدر داخــل جيــب البنطــال االيســر‪ .‬واثبــت التقريــر‬\n‫الكيميائــي الشــرعي رقــم (‪ 382‬س ‪ )2‬لعــام ‪1433‬ه ـ احتــواء القطعــة‬\n‫علــى مــادة احلشــيش املخــدر‪ .‬وبالتحقيــق مــع املدعــى عليه اعتــرف بحيازة‬\n\n                                                                                    ‫‪36‬‬\n\f     ‫احلشــيش املخــدر املضبوطــة معــه لغــرض االســتعمال وبانــه يســتخدم‬\n     ‫مــادة احلشــيش املخــدر منــذ ســنة تقريب ـ ًا وانــه تعاطــى ســيجارة واحــدة‬\n     ‫قبــل القبــض عليــه ‪ .‬وقــد اســفر التحقيــق عــن اتهامــه بحيازتــه قطعــة‬\n     ‫بنيــة اللــون بلــغ وزنهــا (‪ )6‬ســتة جرامــات مــن مــادة احلشــيش املخــدر‬\n     ‫لغــرض االســتعمال واســتعماله لهــا مــن الســابق وقيــادة الســيارة حتــت‬\n     ‫تاثيــر تعاطــي احلشــيش املخــدر وتســتره علــى مصــدر املخــدرات وذلــك‬\n                                                          ‫لألدلــة والقرائــن التاليــة ‪:‬‬\n     ‫‪ -1‬اعترافــه واقــراره املــدون علــى الصفحــة رقــم (‪ )5‬من ملف االســتدالل‬\n                                                                           ‫لفــة رقــم (‪. )1‬‬\n                          ‫‪ -2‬ما جاء يف محضر القبض والتفتيش لفة رقم (‪. )4‬‬\n                                ‫‪ -3‬التقرير الكيميائي الشرعي لفة رقم (‪. )19‬‬\n                          ‫وببحث سوابقه تبني عدم وجود سوابق مسجله عليه ‪.‬‬\n     ‫وحيــث ان مــا اقــدم عليــه املذكــور فعــل معاقــب عليــه شــرعا ونظامــا‬\n     ‫مبوجــب املــادة (‪ )2/3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n     ‫الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬يف ‪1426/7/8‬ه ـ ونظــام املــرور‬\n     ‫الصــادر باملرســوم امللكــي رقــم (م‪)85/‬يف ‪1428/10/26‬ه ـ اطلــب‬\n                                    ‫اثبــات مــا اســند اليــه واحلكــم عليــه باالتــي ‪:‬‬\n                         ‫‪ -1‬اجراء املقتضى الشرعي لتعاطيه احلشيش املخدر ‪.‬‬\n     ‫‪ -2‬بالعقوبــة الــواردة يف املــادة (‪ )1/41‬مــن نظــام املخــدرات واملؤثــرات‬\n                                                                   ‫العقليــة املشــار اليــه‬\n     ‫‪ -3‬منعــه مــن الســفر بعــد تنفيــذ عقوبتــه وفقــا للمــادة (‪ )1/56‬مــن ذات‬\n                                                                                  ‫النظــام ‪.‬‬\n     ‫‪ -4‬الفصــل يف قيادتــه للســيارة حتــت تاثيــر تعاطــي احلشــيش املخــدر‬\n\n\n‫‪37‬‬\n\f                                                ‫وفقــا لنظــام املــرور املشــار اليــه ‪.‬‬\n                           ‫‪ -5‬بعقوبة تعزيرية لتستره على مصدر املخدرات ‪.‬‬\n‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه ‪ .....‬أجــاب قائــا مــا‬\n‫ذكــره املدعــي العــام صحيــح فقــد قبــض علــي مــن قبــل دوريــات امــن‬\n‫الطــرق بــ‪ .......‬وقــد وجــدوا معــي قطعــة حشــيش وزنهــا ســتة جرامــات‬\n‫حزتهــا لغــرض االســتعمال فقــط وأنــا أدخــن احلشــيش وأثنــاء القبــض لــم‬\n‫أكــن مســتعمال للحشــيش فآخــر مــرة قبــل القبــض علــي بيــوم وليــس‬\n‫علــي ســوابق وال اعــرف املصــدر الــذي باعنــي احلشــيش هكــذا أجــاب‬\n‫وبســؤال املدعــي البينــة عــن دعــواه بتدخــن املدعــى عليــه احلشــيش أثنــاء‬\n‫القيــادة قــال ال بينــة لــي وقــد جــرى اطالعــي علــى أقوالــه يف املعاملــة‬\n‫فوجدتهــا كمــا جــاء يف جوابــه ولــم أجــد لــه قــوال أو إقــرار ًا أنــه حــال‬\n‫قيادتــه للســيارة كان حتــت تأثيــر احلشــيش املخــدر أو أي مســكر وقــد‬\n‫جــرى اطالعــي علــى التقريــر الكيميائــي الشــرعي رقــم (‪ 382‬س ‪)2‬‬\n‫لعــام ‪1433‬ه ـ املتضمــن ايجابيــة القطعــة للحشــيش املخــدر ولــم أجــد‬\n‫لــه ســوابقا وقــد وجــدت انــه أوقــف يف ‪1432/12/20‬ه ـ وأفــرج عنــه يف‬\n‫‪1432/12/22‬هـ ـ فبنــاء ملــا تقــدم مــن الدعــوى واإلجابــة وحيــث صــادق‬\n‫املدعــى عليــه علــى دعــوى املدعــي العــام واقــر بحيازتــه لســتة جرامــات‬\n‫مــن احلشــيش املخــدر لغــرض التعاطــي واقــر بتدخينــه احلشــيش وأنكــر‬\n‫قيادتــه للســيارة وهــو حتــت تأثيــر احلشــيش ولــم يقــدم املدعــي العــام‬\n‫البينــة علــى ذلــك ولــم أجــد لــه قــوال يف املعاملــة بذلــك فقــد ثبــت لــدي‬\n‫مانســب للمدعــى عليــه مــن حيازتــه للحشــيش املخــدر البالــغ وزنــه ســتة‬\n‫جرامــات مــن احلشــيش املخــدر وتعاطيــه للحشــيش فقــط ونظــرا لقلــة‬\n‫الكميــة ولعــدم ســوابقه فقــد قــررت معاملتــه حســب املــادة الســتون مــن‬\n\n\n                                                                                            ‫‪38‬‬\n\f     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وقــررت مايلــي اوال‪:‬ســجن‬\n     ‫املدعــى عليــه عشــرين يومــا حتســب منها فتــرة ايقافــة ‪.‬ثانيا‪:‬جلده ثمانني‬\n     ‫جلــده حــد املســكر ‪.‬ثالثا‪:‬جلــده أربعــن جلــده تعزيــر لقــاء تســتره علــى‬\n     ‫املصــدر الــذي باعــه احلشــيش ‪.‬رابعا‪:‬منعــه مــن الســفر خــارج اململكــة‬\n     ‫ســنتني اعتبــارا مــن تاريــخ انتهــاء فتــرة ســجنه‪.‬رابعا‪:‬صرف النظــر عــن‬\n     ‫دعــوى املدعــي العــام إثبــات قيادتــه للســيارة وهــو حتــت تأثيــر تعاطــي‬\n     ‫احلشــيش ومبــا قــررت حكمــت وبعــرض احلكــم علــى الطرفــن قــرر‬\n     ‫اجلميــع عــدم القناعــة باحلكــم وطلــب اســتئنافه بــدون الئحــة اعتــراض‬\n     ‫فأجيــب لطلبهمــا ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/02‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n     ‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n     ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n     ‫‪ 331148189‬وتاريــخ ‪1434/1/10‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ....... /‬املســجل برقــم ‪33445090‬‬\n     ‫وتاريــخ ‪1433/11/2‬ه ـ اخلــاص بدعــوى املدعــى العــام ضــد ‪ ....... /‬يف‬\n     ‫قضيــة مخــدرات علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه‬\n     ‫مبــا هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n     ‫املعاملــة لــم يظهــر لألكثريــة مــا يوجــب املالحظــة علــى احلكــم مــع‬\n     ‫تنبيــه فضيلتــه إلــى ايضــاح القصــد مــن احليــازة يف اإلثبــات مالحظــة‬\n     ‫ال ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬  ‫ذلــك مســتقب ً‬\n                                                                     ‫وصحبــه وســلم‪.‬‬\n\n\n\n‫‪39‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":35,"source_page_end":39,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dccfb023b5e7b0ac5fd68bd443578ed7491e08bd47761e3814e8060e03e72591","normalized_text_hash":"7359c210a5759b02bc7a13a593a1a58a79df1eff6a19d9a74c8940b34a2cd6b7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p35-33445090"},{"id":"c1b84e75-4623-53a0-ba04-05d0032507b5","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة الكوكاين املخدر لقصد الترويج -حيازة ميزان الكتروني به آثار مادة مخدرة بقصد الترويج -اشتراك يف تنظيم عصابة منظمة لالجتار باملواد املخدرة -اختاء محرم -مقاومة الفرقة القابضة -تعزير بالسجن واجللد ومصادرة اجلوال والشريحة املستخدمان يف اجلرمية .","document_number":"3458629","case_number":"33420204","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/09","year":"1434","subject":"مخدرات -حيازة الكوكاين املخدر لقصد الترويج -حيازة ميزان الكتروني به آثار مادة مخدرة بقصد الترويج -اشتراك يف تنظيم عصابة منظمة لالجتار باملواد املخدرة -اختاء محرم -مقاومة الفرقة القابضة -تعزير بالسجن واجللد ومصادرة اجلوال والشريحة املستخدمان يف اجلرمية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3458629:‬تاريخه‪1434/03/09:‬هـ‬\n                 ‫رقم الدعوى ‪33420204 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34199739‬تاريخه‪1434/4/28:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة الكوكايــن املخــدر لقصــد الترويــج ‪ -‬حيــازة ميــزان‬\n‫الكترونــي بــه آثــار مــادة مخــدرة بقصــد الترويــج ‪ -‬اشــتراك يف تنظيــم‬\n‫عصابــة منظمــة لالجتــار باملــواد املخــدرة ‪ -‬اختــاء محــرم ‪ -‬مقاومــة‬\n‫الفرقــة القابضــة ‪ -‬تعزيــر بالســجن واجللــد ومصــادرة اجلــوال‬\n                                 ‫والشــريحة املســتخدمان يف اجلرميــة ‪.‬‬\n\n\n\n\n                                                       ‫‪ -1‬األصل البراءة ‪.‬‬\n‫‪ -2‬الفقــرة ‪ 2‬مــن املــادة ‪ 53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                ‫العقليــة ‪.‬‬\n‫‪ -3‬الفقــرة ‪ 2‬مــن املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                 ‫العقليــة‪.‬‬\n                           ‫‪ -4‬املادة ‪ 216‬من نظام اإلجراءات اجلزائية ‪.‬‬\n‫‪ -5‬تعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم ‪ 9798‬يف‬\n                                                          ‫‪1428 /2 /10‬هــ‪.‬‬\n\n\n\n\n‫دعــوى املدعــي العــام ضــد أربعــة أشــخاص أحدهــم امــرأة مقيمــن إقامــة‬\n‫غيــر نظاميــة يحملــون بطاقــات بديلــة بطلــب إثبــات إدانتهــم بحيــازة‬\n\n                                                                               ‫‪40‬‬\n\f     ‫الكوكايــن املخــدر وميــزان إلكترونــي بــه آثــار املــادة املخــدرة‬\n     ‫بقصــد الترويــج واالشــتراك يف عصابــة منظمــة لالجتــار باملــواد املخــدرة‬\n     ‫واتهامهــم باالختــاء احملــرم واتهــام الرابــع مبقاومــة الفرقــة القابضــة‬\n     ‫مقاومــة عنيفــة‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليهــم واحلكــم‬\n     ‫عليهــم بعقوبــة الســجن واجللــد والغرامــة ومصــادرة اجلــواالت املســتخدمة‬\n     ‫يف اجلرميــة وإلغــاء شــرائحها ومصــادرة املبلــغ املالــي املضبــوط مــع اثنــن‬\n     ‫مــن املدعــى عليهــم وإبعادهــم خــارج اململكــة بعــد انتهــاء عقوبتهــم‪ ،‬مت‬\n     ‫القبــض علــى املدعــى عليهــم بعــد إخباريــة مفادهــا أنهــم يروجــون مــادة‬\n     ‫الكــراك فتــم اســتيقاف أحدهــم ومت فتــح مســكنه بإحــدى املفاتيــح‬\n     ‫التــي معــه وعثــر عليهــم باملســكن وعثــر بحوزتهــم علــى املــواد املخــدرة‪،‬‬\n     ‫اعتــراف املدعــى عليــه األول والثالــث و الرابــع‪ ،‬إنــكار املدعــى عليــه‬\n     ‫الثانــي‪ ،‬عــدم وجــود بينــة تديــن املدعــى عليــه الثانــي‪ ،‬تعزيــر املدعــى‬\n     ‫عليــه األول و الثالــث والرابــع بالســجن واجللــد واإلبعــاد مــن البــاد‪،‬‬\n     ‫مصــادرة املبالــغ املاليــة املضبوطــة معهــم‪ ،‬مصــادرة اجلــوال و الشــريحة‬\n     ‫املســتخدمان يف اجلرميــة‪ ،‬صــرف النظــر عــن املدعــى عليــه الثانــي لعــدم‬\n                 ‫كفايــة األدلــة‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة اجلزائيــة يف محافظــة جدة املســاعد برقــم ‪ 33420204‬وتاريخ‬\n     ‫‪1433/06/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331176483‬وتاريــخ‬\n     ‫‪1433/06/22‬ه ـ ففــي يــوم الســبت املوافــق ‪1434/03/07‬ه ـ افتتحــت‬\n\n‫‪41‬‬\n\f‫اجللســة الســاعة ‪ 08 : 45‬صباحــا املتعلقــة بدعــوى املدعــي العــام ‪...‬‬\n‫ســعودي بالســجل املدني رقم ‪ .....‬مبوجب التكليف رقم هـ م‪368/6/2‬‬\n‫وتاريــخ ‪1430/12/29‬ه ـ ضــد املدعــى عليهم‪ )29( .....-1 :‬عام ًا تشــادي‬\n‫اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ ).....‬وتاريــخ ‪1433/1/20‬ه ـ‬\n‫صــادرة مــن مكافحــة املخــدرات يقيــم بطريقــة غيــر نظاميــة عاطــل‬\n‫أمــي ‪ ،‬موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر متديــد‬\n‫التوقيــف رقم(ه ـ م‪ )7052/5/2‬يف‪1433/1/30‬ه ـ اســتناد ًا للقــرار‬\n‫الــوزاري (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪ )27( ....-2‬عام ـ ًا تشــادي‬\n‫اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ ، )....‬وتاريــخ ‪1433/1/20‬هــ‪،‬‬\n‫صــادرة مــن مكافحــة املخــدرات ‪،‬عاطــل ‪ ،‬يقيــم بطريقــة غيــر نظاميــة‬\n‫أمــي موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر متديــد‬\n‫التوقيــف رقــم (ه ـ م‪ )7050/5/2‬يف‪1433/1/30‬هــ‪ ،‬اســتناد ًا للقــرار‬\n‫الــوزاري (‪ ، )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪-3‬املــرأة‪ )38( ..../‬عام ـ ًا‬\n‫نيجيريــة اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ )....‬وتاريــخ‬\n‫‪1433/1/20‬هــ‪ ،‬صــادرة مــن مكافحة املخــدرات عاطلة تقيم بطريقة‬\n‫غيــر نظاميــة أميــة موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب‬\n‫أمــر متديــد التوقيــف رقم(ه ـ م‪)7053/5/2‬يف‪1433/1/30‬ه ـ اســتناد ًا‬\n‫للقــرار الــوزاري(‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪ )31( ، .....-4‬عام ـاً‪،‬‬\n‫تشــادي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ )....‬وتاريــخ‬\n‫‪1433/1/20‬هــ‪ ،‬صــادرة مــن مكافحــة املخــدرات عاطــل يقيــم بطريقة‬\n‫غيــر نظاميــة أمــي موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر‬\n‫متديــد التوقيــف رقم(ه ـ م‪ )7051/5/2‬يف‪1433/1/30‬هــ‪ ،‬اســتناد ًا‬\n‫ا يف دعــواه إنــه‬ ‫للقــرار الــوزاري (‪ ، )1900‬وتاريــخ ‪1428/7/9‬ه ـ قائ ـ ً‬\n\n\n                                                                              ‫‪42‬‬\n\f     ‫بتاريــخ ‪1433/1/20‬ه ـ مت القبــض علــى املدعــى عليهــم مــن قبــل أفــراد‬\n     ‫ـاء علــى إخباريــة متعاونــان عــن‬\n                                       ‫مكافحــة املخــدرات مبحافظــة جــدة بنـ ً‬\n     ‫وجــود ثالثــة أشــخاص مــن اجلنســية التشــادية يروجــون مــادة الكــراك‬\n     ‫بأحــد املســاكن ومبراقبتــه خــرج األول منــه فتــم اســتيقافه وبســؤاله‬\n     ‫عــن مســكنه أنكــر وجــود مســكن لــه فتــم فتــح املســكن بأحــد‬\n     ‫املفاتيــح التــي ضبطــت معــه وعنــد دخــول املســكن ضبــط بأحــد الغــرف‬\n     ‫الثانــي وضبطــت الثالثــة يف غرفــة أخــرى عثــر بهــا علــى تســع أكيــاس‬\n     ‫بهــا مــادة تــزن(‪ )10‬عشــرة جرامــات وعثــر بأحــد الغــرف علــى ثالثــة‬\n     ‫عشــر كيسـ ًا بهــا مــادة تــزن(‪ )14,8‬أربعــة عشــر جرامـ ًا وثمانيــة أعشــار‬\n     ‫اجلــرام ومــادة أخــرى تــزن (‪)5,8‬خمســة جرامــات وثمانيــة أعشــار اجلــرام‬\n     ‫كمــا عثــر علــى ميــزان الكترونــي وأثنــاء القبــض حضــر الرابــع وفتــح‬\n     ‫بــاب العزبــة بواســطة مفتــاح معــه وعنــد مشــاهدته للفرقــة هــرب فتمــت‬\n     ‫مالحقتــه والقبــض عليــه بعــد مقاومتــه مقاومــة عنيفــة ‪ ،‬فــورد اتصــال‬\n     ‫علــى جوالــه مــن شــخص يطلــب شــراء مــادة الكــراك املخــدر لقــاء ألــف‬\n     ‫ريــال‪ .‬فتــم القبــض عليهــم وأثبــت التقريــر الكيميائــي الشــرعي رقــم‬\n     ‫(‪/275‬ك ش م) لعــام ‪1433‬ه ـ احتــواء العينــات ( أ ‪،‬ب‪،‬ج) املضبوطــة‬\n     ‫واملرســلة للتحليــل ملــادة الكوكايــن املخــدر كمــا ثبــت احتــواء اآلثــار‬\n     ‫التــي علــى امليــزان اإللكترونــي املرســل بالعينة(د)لــذات املــادة‬\n     ‫املخدرة‪،‬املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة‬\n     ‫املخــدرات واملؤثــرات العقليــة وباســتجواب املدعــى عليهــا الثالثة‪/‬أقــرت‬\n     ‫أن مــا ضبــط لديهــا بالغرفــة مــن الكــراك املخــدر يعــود للمدعــى عليــه‬\n     ‫الرابــع وضعــه عندهــا علــى ســبيل األمانــة وأســفر التحقيــق عــن توجيــه‬\n     ‫اإلتهــام إلــى كل مــن األول والثانــي والثالثــة والرابــع بحيــازة (‪)30,6‬‬\n\n\n‫‪43‬‬\n\f‫ثالثــون جرام ـ ًا وســتة أعشــار اجلــرام مــن مــادة الكوكائــن املخــدر‬\n‫وميــزان الكترونــي بــه اثــار ثبــت انهــا لنفــس املــادة املخــدرة وذلك بقصد‬\n‫الترويــج واشــتراكهم يف عصابــة منظمــة لالجتــار باملــواد املخــدرة‬\n‫واتهامهــم جميعــا باالختــاء احملــرم شــرعا واتهــام الرابــع مبقاومــة‬\n‫الفرقــة مقاومــة عنيفــة اســتنادا للفقــرة (‪ )2‬مــن املــادة الثالثــة مــن نظــام‬\n‫مكافحــة املخــدرات وحيــث إن مــا أقــدم عليــه املدعــى عليهــم وهــم‬\n‫بكامــل أهليتهــم املعتبــرة شــرع ًا مــن األفعــال احملرمــة شــرع ًا واملجرمــة‬\n‫نظام ـ ًا طبق ـ ًا للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫لــذا أطلــب إثبــات مــا أســند إليهــم ومعاقبتهــم بالعقوبــات األصليــة‬\n‫والتكميليــة التاليــة‪-1 :‬احلكــم عليهــم بالســجن واجللــد والغرامــة لقــاء‬\n‫مــا اســند إليهــم اســتناد ًا للفقــرة (‪ )1‬وتشــديد العقوبــة عليهــم اســتناد ًا‬\n‫للحالتــن (أ) و(ج) مــن الفقــرة (‪ )2‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة ‪- 2‬مصــادرة أجهــزة اجلــوال مــن نــوع (‪)...‬‬\n‫ذي الرقــم املصنعــي رقــم (‪ ، )............‬بشــريحته الســتخدامه يف‬\n‫ارتــكاب اجلرميــة ‪،‬وجــوال مــن نــوع (‪ )...‬ذي الرقــم املصنعــي(‪)............‬‬\n‫وجــوال مــن نــوع(‪ )...‬ذي الرقــم املصنعــي(‪ )............‬وجــوال مــن نــوع (‪)...‬‬\n‫ذي الرقــم املصنعــي(‪ )............‬وجــوال مــن نــوع(‪ )...‬ذي الرقــم‬\n‫املصنعــي(‪ )............‬وجــوال مــن نــوع (‪ )...‬ذي الرقــم املصنعــي(‪)............‬‬\n‫وجــوال مــن نــوع (‪ )...‬ذي الرقــم املصنعــي(‪ )............‬اســتناد ًا للفقــرة رقــم‬\n‫(‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات املشــار إليــه‪ ،‬وإلغــاء‬\n‫اخلدمــة مــن الشــرائح املضبوطــة ‪ ،‬وعــدم صرفهــا لهــم مــرة أخــرى‪،‬‬\n‫اســتناد ًا إلــى تعميــم صاحــب الســمو امللكــي وزيــر الداخليــة (‪، )9798‬‬\n\n\n                                                                                         ‫‪44‬‬\n\f     ‫وتاريــخ ‪9‬ـ‪1428/2/10‬هـ‪.‬وذلــك لكونهــا تســتخدم يف التشــكيل‬\n     ‫العصابي‪-3‬مصــادرة املبلــغ املالــي املضبــوط مــع املدعــى عليــه األول‬\n     ‫وقدرة(‪)300‬ثالثمائــة ريــال ســعودي ‪،‬وكذلــك املبلــغ املالــي املضبــوط‬\n     ‫مــع املدعــى عليــه الرابــع وقدرة(‪)4900‬أربعــة آالف وتســعمائة ريــال‬\n     ‫ســعودي ‪ ،‬اســتنادا للفقــرة (‪)2‬مــن املــادة(‪ )53‬مــن نظــام مكافحــة‬\n     ‫املخــدرات املشــار إليــه ‪-4‬إبعادهــم عــن اململكــة بعــد االنتهــاء مــن تنفيــذ‬\n     ‫عقوبتهــم وعــدم الســماح لهــم بالعــودة إليهــا ‪ ،‬اســتناد ًا للفقــرة (‪ )2‬مــن‬\n     ‫املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات املشــار إليــه كمــا أطلــب‬\n     ‫احلكــم عليهــم جميعــا بعقوبــة تعزيريــة لقــاء االختــاء احملــرم شــرعا‬\n     ‫وتعزيــر املدعــى عليــه الرابــع شــرع ًا لقــاء مقاومتــه العنيفــة للفرقــة‬\n     ‫القابضــة حملاولــة الهــرب هكــذا ادعــى املدعــي العــام ا‪ .‬ه ـ وبســؤال‬\n     ‫املدعــى عليهــم عــن الدعــوى وهــم يعرفــون العربيــة أجــاب املدعــى عليــه‬\n     ‫األول ‪ ....‬صحيــح حــزت ثالثــن جرام ـ ًا وســتة أعشــار اجلــرام مــن مــادة‬\n     ‫الكوكايــن املخــدر وميــزان الكترونــي بــه آثــار الكوكايــن بقصــد‬\n     ‫الترويــج وأن احليــازة تخصنــي ومعــي املــرأة ‪ ...‬واملدعــى عليــه ‪ .....‬ســوى ‪....‬‬\n     ‫فــا عالقــة لــه باحليــازة واختليــت باملدعــى عليهــا املــرأة حجــة وال تربطني‬\n     ‫بهــا صلــة قرابــة شــرعية وأجــاب املدعــى عليــه الثانــي ‪ ....‬مــا ذكــره‬\n     ‫املدعــي العــام غيــر صحيــح جملــة وتفصيــا وأجابــت املدعــى عليهــا‬\n     ‫الثالثــة املــرأة‪ ... /‬صحيــح حــزت ثالثــن جرامــا وســتة أعشــار اجلــرام مــن‬\n     ‫مــادة الكوكايــن املخــدر وميــزان الكترونــي بــه آثــار الكوكايــن‬\n     ‫بقصــد الترويــج واختليــت باملدعــى عليهمــا األول والرابــع وال تربطنــي‬\n     ‫بهمــا صلــة قرابــة شــرعية ومــا ذكــره املدعــي العــام صحيــح جملــة‬\n     ‫ا وأجــاب املدعــى عليــه الرابــع ‪ ....‬صحيــح حــزت ثالثــن جرامــا‬      ‫وتفصيـ ً‬\n\n\n‫‪45‬‬\n\f‫وســتة أعشــار اجلــرام مــن مــادة الكوكايــن املخــدر وميــزان الكتروني‬\n‫بــه آثــار الكوكايــن بقصــد الترويــج واختليــت باملدعــى عليهــا املــرأة‬\n‫حجــة وال تربطنــي بهــا صلــة قرابــة شــرعية ومــا ذكــره املدعــي العــام‬\n‫صحيــح جملــة وتفصيــا ا‪ .‬ه ـ وبطلــب البينــة مــن املدعــي العام قــال بينتي‬\n‫مــا جــاء يف أوراق املعاملــة ـ وبعــد اإلطــاع علــى أوراق املعاملــة ومــن‬\n‫ضمنهــا محضــر القبــض املتوافــق مــع مــا ذكــره املدعــي العــام ضــد‬\n‫األول والثالثــة والرابــع أمــا الثانــي فقــد أشــار محضــر القبــض بأنــه قُ بض‬\n‫علــى الثانــي يف غرفــة لــم يوجــد فيهــا شــيء مــن املمنوعــات كمــا أنــه‬\n‫ُف ّتــش حينهــا ولــم يوجــد معــه شــيء مــن املمنوعــات أيضـ ًا كمــا أن األول‬\n‫نفــى عالقــة الثانــي بالتهــم وحيــث إن املدعــي العــام بينتــه هــم شــهود‬\n‫محضــر القبــض الــذي لــم يــرد فيــه شــيء يديــن الثانــي واألصــل البــراءة‬\n‫وألن هــؤالء اجلاليــات جــرت عادتهــم أن يتقاســموا البيــت غرفــة غرفــة‬\n‫وحيــث إن املبلــغ املالــي وقــدره أربعــة آالف وتســعمائة ريــال يخص املدعى‬\n‫عليــه الثانــي حســب وصــف املضبوطــات مبلــف إجــراءات االســتدالل لفــة‬\n‫رقــم (‪ )1‬ص (‪ )7‬وليــس كمــا ذكــر املدعــي العــام وألن التعازيــر‬\n‫تتداخــل وملــا ظهــر مــن نــدم املدعــى عليهــم وتوبتهــم ولعــدم الســوابق لــذا‬\n‫فقــد حكمــت مبــا يلــي ‪ :‬أو ًال ‪ :‬إدانــة املدعــى عليهــم األول والثالثــة‬\n‫والرابــع مبــا أســند إليهــم يف دعــوى املدعــي العــام وحكمــت عليهــم مبــا‬\n‫يلــي ‪ -1‬ســجن كل واحــد منهــم مــدة ســنتني حتتســب منها مــدة اإليقاف‬\n‫التــي أمضاهــا علــى ذمــة هــذه القضيــة وجلــد كل واحــد منهــم خمســن‬\n‫جلــدة مكــررة ســت مــرات بــن كل مــرة واألخــرى مــا ال يقــل عــن‬\n‫أســبوع وغرامــة ماليــة قدرهــا ألفــا ريــال علــى كل واحــد منهــم اســتناد ًا‬\n‫(‪ )60-38‬مــن نظــام مكافحــة املخــدرات ‪ -2‬مصــادرة أجهــزة اجلــوال‬\n\n\n                                                                                      ‫‪46‬‬\n\f     ‫من نوع (‪ ).......‬ذي الرقم املصنعي رقم (‪ )............‬بشريحته الستخدامه‬\n     ‫يف ارتكاب اجلرمية ‪ ،‬وجوال من نوع (‪ ).......‬ذي الرقم املصنعي(‪)............‬‬\n     ‫وجــوال مــن نــوع(‪ )...‬ذي الرقــم املصنعــي(‪ )............‬وجــوال مــن نــوع(‪)...‬‬\n     ‫ذي الرقــم املصنعــي(‪ )............‬وجــوال مــن نــوع (‪ )...‬ذي الرقــم‬\n     ‫املصنعــي(‪ )............‬وجــوال مــن نــوع (‪ )...‬ذي الرقــم املصنعــي(‪)............‬‬\n     ‫اســتناد ًا للفقــرة رقــم (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n     ‫املشــار إليــه ‪ ،‬وإلغــاء اخلدمــة مــن الشــرائح املضبوطــة ‪ ،‬وعــدم صرفهــا‬\n     ‫لهــم مــرة أخــرى ‪ ،‬اســتناد ًا إلــى تعميــم صاحــب الســمو امللكــي وزيــر‬\n     ‫الداخليــة (‪ )9798‬وتاريــخ ‪9‬ـ‪1428/2/10‬هـ‪.‬وذلــك لكونها تســتخدم يف‬\n     ‫التشــكيل العصابي‪-3‬مصــادرة املبلــغ املالــي املضبــوط مــع املدعــى‬\n     ‫عليــه األول وقدرة(‪)300‬ثالثمائــة ريــال ســعودي اســتنادا للفقــرة (‪)2‬مــن‬\n     ‫املــادة(‪ )53‬مــن نظــام مكافحــة املخــدرات املشــار إليــه ‪-4‬إبعادهــم عــن‬\n     ‫اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتهــم وعــدم الســماح لهــم بالعــودة‬\n     ‫إليها اســتناد ًا للفقرة (‪ )2‬من املادة (‪ )56‬من نظام مكافحة املخدرات‬\n     ‫املشــار إليــه ثانيـ ًا ‪ :‬صــرف النظــر عــن دعــوى املدعــي العــام ضــد املدعــى‬\n     ‫عليــه الثانــي لعــدم كفايــة األدلــة وإعــادة جميــع املضبوطــات التــي‬\n     ‫تخصــه وأمــرت باإلفــراج عنــه فــور ًا إذا لــم يكــن إيقافــه متعلقـ ًا بقضيــة‬\n     ‫أخــرى أو كان مقيم ـ ًا إقامــة غيــر نظاميــة اســتناد َا للمــادة ‪ 216‬مــن‬\n     ‫نظــام اإلجــراءات اجلزائيــة وبجميــع ذلــك حكمــت وبعرضــه عليهــم‬\n     ‫قــرروا جميع ـ ًا القناعــة باحلكــم وقــرر املدعــي العــام عــدم القناعــة‬\n     ‫باحلكــم وطلــب رفعــه حملكمــة االســتئناف بالئحــة تقــدم خــال ثالثــن‬\n     ‫يومـ ًا مــن تاريــخ تســجيل القــرار وإال رفعــت املعاملــة بــدون الئحــة وصلــى‬\n     ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n\n\n‫‪47‬‬\n\f                                                           ‫‪1434/03/07‬هـ ‪.‬‬\n          ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف‬\n‫مبكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه‬\n‫احملكمــة بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بجــده املســاعد‬\n‫رقــم(‪ )331176483‬وتاريخ(‪1434/4/20‬هــ) املرفــق بهــا القــرار‬\n‫رقم(‪)3458629‬وتاريخ(‪1434/3/9‬هـ)الصــادر مــن فضيلة الشــيخ‪....../‬‬\n‫القاضــي باحملكمــة اجلزائيــة بجده‪،‬املتضمــن دعــوى املدعــي العــام‬\n‫ضد‪29......./‬عــام تشــادي اجلنســية ورفقــاه ‪ ،‬املتهمــن يف مخــدرات‬\n‫واإلختــاء احملــرم شــرع ًا ‪ ،‬احملكــوم فيــه مبــادون باطنــه ‪ ،‬وبدراســة‬\n‫القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى‬\n‫احلكــم ‪ ،‬واهلل املوفق‪،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه‬\n                                                                       ‫وســلم‪.‬‬\n\n\n\n\n                                                                                 ‫‪48‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":40,"source_page_end":48,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7c51c06c967f290508d4ffa8c25030c51468365c9bc31cfcab5a5b6488bd61a4","normalized_text_hash":"004ecee5aa3e663f548942e0cdcce556cfd9c6cbd78e6167d1306d4e551b8de7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p40-3458629"},{"id":"d0467a00-d020-58a6-abb1-c7fea19795f9","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلبوب احملظورة بقصد الترويج والتعاطي - اإلقرار -تستر -تعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال وإلغاء الشريحة .","document_number":"33341688","case_number":"33422254","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/14","year":"1434","subject":"مخدرات -حيازة احلبوب احملظورة بقصد الترويج والتعاطي - اإلقرار -تستر -تعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال وإلغاء الشريحة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33341688:‬تاريخه ‪1433/7/14:‬هـ‬\n                      ‫رقم الدعوى ‪33422254:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 3428035‬تاريخه‪1434/02/03:‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬حيــازة احلبــوب احملظــورة بقصــد الترويــج والتعاطــي ‪-‬‬\n     ‫اإلقــرار ‪ -‬تســتر‪ -‬تعزيــر بالســجن واجللــد والغرامــة واملنــع مــن الســفر‬\n                                           ‫ومصــادرة اجلــوال وإلغــاء الشــريحة ‪.‬‬\n\n\n\n\n     ‫املادة ‪ -62 -53 -56 -38‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n     ‫ادعــى املدعــى العــام ضــد املدعــى عليــه بحيازتــه احلبــوب احملظــورة‬\n     ‫بقصــد الترويــج ‪ ،‬وتعاطيــه للحبــوب احملظــورة‪ ،‬وطلــب املدعــي العــام‬\n     ‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة‬\n     ‫ومنعــه مــن الســفر ومصــادرة الهاتــف اجلــوال وإلغــاء شــريحته املســتخدم‬\n     ‫يف اجلرميــة وعقوبــة تعزيريــة لقــاء تســتره علــى مصــدر مــا ضبــط ‪ ،‬حيــث‬\n     ‫إنــه مت القبــض علــى املدعــى عليــه بعــد إخباريــة مفادهــا أن املدعــى‬\n     ‫عليــه يقــوم بترويــج احلبــوب احملظــورة‪ ،‬فتــم التنســيق معــه مــن قبــل أحــد‬\n     ‫املصــادر الســرية ومت تزويــد املصــدر باملبلــغ املرقــم ومت تفتيــش املصــدر‬\n     ‫ثــم قابــل املصــدر املدعــى عليــه وعــاد املصــدر ومعــه حبــوب ذكــر أنــه‬\n     ‫اشــتراها مــن املدعــى عليــه ثــم ذهــب أحــد أفــراد الفرقــة القابضــة مــع‬\n     ‫املصــدر وكلــم املتهــم وطلــب إرجــاع احلبــوب للمتهــم فرفــض املتهــم ثــم‬\n\n‫‪49‬‬\n\f‫بعــد ذلــك مت القبــض علــى املتهــم أمــام منــزل والــده وعثــر معــه علــى‬\n‫اجلــوال املســتخدم يف اجلرميــة وصــادق املدعــى عليــه علــى الدعــوى‪ ،‬بنــاء‬\n‫علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه باجللد والســجن‬\n‫والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال وإلغــاء الشــريحة ‪ ،‬صــدق‬\n                                        ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬قاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33422254‬وتاريــخ ‪ 1433/06/23‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331184146‬وتاريــخ ‪ 1433/06/23‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1433/07/01‬ه ـ افتتحــت اجللســة الســاعة ‪12 : 15‬‬\n‫وفيهــا قــدم املدعــي العــام ‪ .......‬دعــواه علــى ‪ ،................/‬البالــغ مــن‬\n‫العمر (‪ )38‬عام ًا ـ ســعودي اجلنســية مبوجب الســجل املدني رقم ‪...........‬‬\n‫متســبب ‪ ،‬اعــزب ‪ ،‬متعلــم ـ يقيــم يف مدينــة الريــاض ‪ ،‬أوقــف بتاريــخ‬\n‫‪1433/4/24‬ه ـ وأحيــل إلــى شــعبة ســجن امللــز مبوجــب أمــر اإلحالــة‬\n‫والتمديــد رقــم (ه ـ ر‪ )51488/5/1‬وتاريــخ ‪1433/5/3‬ه ـ اســتناد ًا‬\n‫للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة‬\n‫(‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪ .‬حيــث إنــه بتاريــخ ‪1433/4/24‬ه ـ‬\n‫قبــض علــى املذكــور مــن قبــل إحــدى فــرق شــعبة املكافحــة والبحــث‬\n‫والتحــري التابعــة لــإدارة العامــة ملكافحــة املخــدرات مبنطقــة الريــاض‬\n‫بناء على املعلومات املتوفرة من احد املصادر الســرية عن قيام املذكور‬               ‫ً‬\n‫بترويــج احلبــوب احملظــورة وأبــدى املصــدر اســتعداده بالتعــاون لإلطاحــة‬\n\n                                                                                        ‫‪50‬‬\n\f     ‫بــه ‪ ،‬فتــم اإليعــاز لــه باألتصــال علــى جوالــه رقــم‪ .....‬وطلــب كميــة مــن‬\n     ‫احلبــوب احملظــورة مبلــغ وقــدره (‪ )100‬مائــة ريــال وكان ذالــك علــى‬\n     ‫مســمع مــن احــد افــراد الفرقــة ‪ ،‬فوافــق علــى ذالــك ‪ ،‬وطلــب املذكــور‬\n     ‫مــن املصــدر احلظــور لوحــده ومقابلتــه يف شــارع أبــو حنيفــة ‪ ،‬وعليــه مت‬\n     ‫تفتيــش املصــدر تفتيشــا دقيقــا وتزويــده باملبلــغ املرقــم قــدره(‪ )100‬مائــة‬\n     ‫ومت تأمــن ســيارة للمصــدر وتوجــه للمذكــور يف مكانــه الــذي حــدده‬\n     ‫ثــم عــاد املصــدر بعــد مايقــارب (‪ )10‬عشــر دقائــق ومعــه (حبتــان يشــتبه‬\n     ‫أن تكونــا مــن حبــوب الكبتاجــون احملظــورة وأفــاد بأنهــا احلبــوب‬\n     ‫املشــتراة مــن املذكــور علــى ذالــك جــرى اإليعــاز للمصــدر باإلتصــال‬\n     ‫علــى املذكــور ومقابلتــه يف نفــس املوقــع ومت تكليــف أحــد افــراد‬\n     ‫الفرقــة مبرافقــة املصــدر ليشــهد علــى ذالــك وبالفعــل توجــه املصــدر‬\n     ‫والفــرد املكلــف إلــى املذكــور ومبقابلــة املذكــور طلــب املصــدر منــه‬\n     ‫إرجــاع احلبــوب احملظــورة املشــتراة فرفــض املذكــور ذالــك وقــال بــأن‬\n     ‫نــوع احلبــوب جيــدة وكان ذالــك علــى مســمع مــن الفــرد املكلــف ثــم‬\n     ‫تــوارى املذكــور عــن األنظــار وعــاد املصــدر والفــرد املكلــف للفرقــة‬\n     ‫بــدون القبــض عليــه ‪ ،‬بعدهــا مت التحــري والبحــث عنــه ‪ ،‬ويف عصــر‬\n     ‫يــوم الســبت املوافــق ‪1433/4/24‬ه ـ وردت معلومــات مفادهــا وجــود‬\n     ‫املذكــور يف الشــارع أمــام منــزل والــده فتــم االنتقــال للموقــع احملــدد‬\n     ‫وبالوصــل إليــه شــوهد املذكــور ومت التعــرف عليــه مــن قبــل الفرقــة‬\n     ‫عندهــا متــت مداهمتــه وضبطــه وبتفتيشــه لــم يعثــر معــه علــى أي مــن‬\n     ‫املمنوعــات ولــم يعثــر معــه علــى املبلــغ املرقــم ‪ ،‬وعثــر معــه الهاتــف‬\n     ‫اجلــوال املســتخدم يف اجلرميــة ويحمــل الرقــم املصنعــي (‪( )............‬مت‬\n     ‫طلــب حجــزه مــع شــريحته مبوجــب اخلطــاب رقــم (ه ـ ر ا ‪)63387/5/‬‬\n\n\n‫‪51‬‬\n\f‫وتاريــخ ‪1433/6/8‬هــ) ‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي‬\n‫الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية‬\n‫املرفــق رقــم (‪/4477‬س) لعام‪1433‬ه ـ احتــواء عينــة احلبتــن املبيعتــن‬\n‫ملــادة االمفيتامــن وهــو مــن املــواد املنبهــة واملدرجــة باجلــدول رقــم (‪ )2‬فئــة‬\n‫(ب) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وبســماع‬\n‫أقوالــه األوليــة و اســتجوابه اعتــرف بتعاطيــه احلبــوب احملظــورة‪ .‬وقــد‬\n‫أســفرت إجــراءات التحقيــق عــن اتهــام ‪ ........ /‬ببيــع (‪ )2‬حبتــن مــن‬\n‫حبــوب األمفيتامــن املنبهــة احملظــورة بقصــد االجتــار الترويــج والتعاطــي‬\n‫وتعاطيــه احلبــوب احملظــورة املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n‫رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر مــا مت بيعــه‬\n‫املعاقــب علــى ذالــك شــرعا‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪-1 :‬مــا‬\n‫تضمنــه اعترافــه حتقيقــا مبحضــر اســتجوابه املنــوه عنــه املــدون علــى‬\n    ‫الصفحتــن رقــم (‪ )2-1‬مــن دفتــر التحقيــق املرفــق علــى اللفــة ( )‪.‬‬\n‫‪ -2‬مــا تضمنــه اعترافــه بالتعاطــي مبحضــر ســماع أقوالــه األوليــة املنــوه‬\n                                                ‫عنــه املرفــق علــى اللفتــن (‪.)4-3‬‬\n‫‪ -3‬مــا جــاء يف محضــر ي البــاغ املنــوه عنهمــا املدونــان علــى الصفحــات‬\n     ‫رقــم (‪ )13-12-2‬يف ملــف إجــراءات االســتدالل املرفــق لفــه رقــم (‪)1‬‬\n‫‪-4‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة رقــم‬\n                                                                              ‫(‪.)........‬‬\n‫وبالبحــث عــن ســوابقه عثــر علــى ســابقة (حيــازة املخــدرات) مســجله‬\n                                                                ‫عليــه حتــى تاريخــه‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n\n\n                                                                                            ‫‪52‬‬\n\f           ‫ونظام ـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم باآلتــي‪:‬‬\n     ‫‪-1‬بعقوبــة الســجن واجللــد والغرامــة املاليــة بحقــه وفقـ ًا للفقــرة (األولــى)‬\n     ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء‬\n     ‫مــا أســند إليــه وإعمــال الفقــرة (األولــى) مــن املــادة (‪ )62‬من نفــس النظام‬\n     ‫بحقــه وتشــديد العقوبــة عليــه وفقــا للفقــرة (ج) مــن البنــد ثانيــا مــن نفــس‬\n                                                                       ‫املــادة املشــار إليهــا‪.‬‬\n     ‫‪ -2‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبتــه‬\n            ‫وفق ـ ًا للفقــرة (األولــى) مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه ‪.‬‬\n     ‫‪ -3‬مصــادرة الهاتــف اجلــوال نــوع (سامســوجن) ذو الرقــم املصنعــي‬\n     ‫(‪ )............‬املســتخدم يف اجلرميــة اســتناد ًا للفقــرة (األولــى) مــن املــادة‬\n                                                      ‫(‪ )53‬مــن النظــام املشــار إليــه‪.‬‬\n     ‫‪ -4‬إلغــاء الشــريحة الهاتفيــة ذات الرقــم (‪ )........‬املســتخدمة يف اجلرميــة‬\n     ‫وعــدم صرفهــا لنفــس املشــترك يف حالــة صــدور احلكــم باإللغــاء وإبــاغ‬\n     ‫الشــركة مصــدرة الشــريحة بذلــك اســتناد ًا لتعميــم صاحــب الســمو‬\n           ‫امللكــي وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ‪.‬‬\n                        ‫‪ -5‬بعقوبة تعزيرية بحقه لقاء تستره على مصدر ما باعه‪.‬‬\n     ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائــا مــا جــاء‬\n     ‫بدعــوى املدعــي العــام غيــر صحيــح هكــذا أجــاب‪ .‬بعــد ذلــك قــررت‬\n     ‫رفــع اجللســة لإلطــاع علــى أوراق املعاملــة والبينــات التــي قدمهــا املدعــي‬\n     ‫العــام وففــي هــذا اليــوم الثالثــاء ‪ 1433/7/8‬افتتحــت اجللســة الســاعة‬\n     ‫الواحــدة وفيهــا حضــر املدعــى عليــه وقــد جــرى ســؤاله مــرة اخــرى عــن‬\n     ‫الدعــوى فأجــاب قائــا ماذكرتــه بجوابــي يف اجللســة املاضيــة غيــر‬\n     ‫صحيــح والصحيــح هــو صحــة ماجــاء يف دعــوى املدعــي العــام وانــا تائــب‬\n\n\n‫‪53‬‬\n\f‫إلــى اهلل عــز وجــل ماعــدا التســتر فلــم اتســتر على املصدر وقد اشــتريتها‬\n‫مــن شــخص ال اعرفــه هكــذا اجــاب بعــد ذلــك جــرى منــا االطــاع علــى‬\n‫اوراق املعاملــة فوجــدت التقريــر الكيميائــي رقمــم‪ /244/4477‬ك‬\n‫وتاريــخ ‪ 1433/5/5‬واملتوافــق مــع ماجــاء يف الئحــة الدعــوى فبنــاء علــى‬\n‫ماتقــدم والقــرار املدعــى عليــه مبــا نســب اليــه مــن قيامــه ببيــع حبتــن‬\n‫مــن حبــوب االمفيتامــن بقصــد االجتــار والتعاطــي وملاجــاء بالتقريــر‬\n‫الكيميائــي املرفــق ومبــا ان ترويــج املخــدرات مــن اكبــر املنكــرات‬\n‫واعظــم اجلرائــم النــه يــؤدي الــى محاربــة الضروريــات اخلمــس التــي‬\n‫حفظهــا االســام وهــي الديــن والنفــس والعقــل والعــرض واملــال ويقضــي‬\n‫علــى املجتمعــات واالفــراد وملاجــاء باملــادة الثامنــة والثالثــن والسادســة‬\n‫واخلمســن والثالثــة واخلمســن والثانيــة والســتني يف فقراتهــا االولــى مــن‬\n‫نظــام مكافحــة املخــدرات ومبــا انــه يتوجــه تعزيــر املدعــى عليــه علــى‬\n‫التســتر اذ انــه يف الغالــب ان مــن يــروج يعــرف املصــدر الــذي اخــذه منــه‬\n‫لذلــك كلــه فقــد صــدر منــا مايلي‪-‬اوال‪:‬ثبــت لــدي ادانــة املدعــى عليــه‬\n‫ببيــع حبتــن مــن حبــوب االمفيتامــن املنبهــة احملظــورة بقصــد الترويــج‬\n‫وتعاطيــه اياهــا وحكمــت بســجنه علــى ذلــك ملــدة خمــس ســنوات تبــدا‬\n‫مــن تاريــخ ايقافــه ثانيــا‪ :‬حكمــت علــى املدعــى عليــه بدفــع غرامــة‬\n                                                             ‫قدرهــا الــف ريــال‬\n‫ثالثــا ‪:‬حكمــت بجلــد املدعــى عليــه مائــة وعشــرين جلــدة مفرقــة علــى‬\n‫ثــاث دفعــات كل دفعــة اربعــون جلــدة بــن كل دفعــة واالخــرى مااليقل‬\n‫عــن عشــرة ايــام رابعــا‪ :‬حكمــت مبنــع املدعــى عليــه مــن الســفر خــارج‬\n‫اململكــة ملــدة خمــس ســنوات بعــد تنفيــذ عقوبــة الســجن عليــه خامســا‪:‬‬\n‫حكمت مبصادرة اجلوال املستخدم يف اجلرمية والغاء الشريحة الهاتفية‬\n\n\n                                                                                    ‫‪54‬‬\n\f     ‫املســتخدمة يف اجلرميــة وعــدم صرفهــا لنفــس املشــترك املشــار اليــه اعــاه‬\n     ‫سادســا‪ :‬حكمــت بتعزيــر املدعــى عليــه علــى التســتر علــى مصــدر مــامت‬\n     ‫بيعــه لتوجــه ذلــك وذلــك بجلــده ثالثــن جلــدة دفعــة واحــدة وبعــرض‬\n     ‫احلكــم علــى املدعــى عليــه قــرر اعتراضــه علــى احلكــم مســتعدا بتقــدمي‬\n     ‫الئحــة اعتراضيــة علــى احلكــم فأفهمتــه مبهلــة االعتــراض وانــه ســوف‬\n     ‫يتــم احضــاره مــن الســجن وتســليمه نســخة مــن احلكــم لتقــدمي اعتراضــه‬\n     ‫ولــه بعــد ذلــك مهلــة شــهر اذا مضــى ولــم يقــدم اعتراضــه ســقط حقــه‬\n     ‫يف تقــدمي االعتــراض ورفــع احلكــم حملكمــة االســتئناف امــا املدعــي‬\n     ‫العــام فقــرر القناعــة باحلكــم واختتمــت اجللســة الســاعة الثانيــة وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                          ‫حــرر يف ‪ 1433/07/08‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق‪ 1433/08/26‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 09: 00‬وفيهــا حضــر املدعــى عليــه وقــدم‬\n     ‫الئحتــه االعتراضيــه املكونــة مــن ورقــة واحــدة وبــاهلل التوفيــق ‪،‬‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                       ‫‪1433/08/26‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األحــد املوافــق ‪1434/1/11‬ه ـ‬\n     ‫فتحــت اجللســة الســاعة الواحــدة وقــد عــادت املعاملــة مــن محكمــة‬\n     ‫االســتئناف بخطــاب فضيلــة رئيســها رقــم ‪ 331885433‬وتاريــخ‬\n     ‫‪1433/11/28‬ه ـ مرفقـ ًا بــه القــرار الصــادر مــن الدائــرة اجلزائيــة األولــى‬\n     ‫برقــم ‪ 33455687‬وتاريــخ ‪1433/11/15‬ه ـ ونصــه ‪ [ :‬وبدراســة القــرار‬\n     ‫وصــورة ضبطــه وأوراق املعاملــة لوحــظ توافــر عــدة موجبــات لتخفيــف‬\n     ‫احلكــم علــى املدعــى عليــه منهــا قلــة الكميــة املضبوطــة ومــا قــرره مــن‬\n\n\n‫‪55‬‬\n\f‫توبــة وعلــى فضيلتــه التأمــل وتقريــر مــا يظهــر لــه حســب املــادة (‪)60‬‬\n‫وبــاهلل التوفيــق ] ‪ .‬أ‪.‬هــ‪ .‬وعليــه أجيــب أصحــاب الفضيلــة حفظهــم اهلل أن‬\n‫املدعــى عليــه قــد ثبــت قيامــه بالترويــج وقــد حكــم عليــه باحلــد األدنــى‬\n‫لعقوبــة الترويــج وكــون الكميــة قليلــة ال يؤثــر يف وصــف الترويــج إذ‬\n‫ال يخفــى أن املــروج يقــوم بالترويــج حســب الكميــة املطلوبــة منــه ومــن‬\n‫روج القليــل روج الكثيــر وجميعــه داخــل يف وصــف الترويــج كمــا‬\n‫أن التوبــة هــي مجــرد دعــوى وجميــع املدعــى عليهــم يدعونهــا ومجــرد‬\n‫دعواهــا غيــر مؤثــر ولــم يظهــر لــي انطبــاق املــادة الســتني علــى املدعــى‬\n‫عليــه واهلل املوفــق واختتمــت اجللســة يف متــام الســاعة الواحــدة والنصــف‪،‬‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                               ‫‪1434/1/11‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫األولــى لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n‫‪ 332218652‬وتاريــخ ‪1434/1/26‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ .......‬املســجل برقــم ‪33341688‬‬\n‫وتاريــخ ‪1433/7/14‬ه ـ اخلــاص بدعــوى املدعــي العــام ض ــد‪ ...........‬يف‬\n‫قضيــة مخــدرات علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل بــه وحيــث ســبق دراســة القــرار وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه‬\n‫فضيلــة القاضــي وإحلاقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا رقــم‬\n‫‪ 33455687‬وتاريــخ ‪1433 /11/15‬ه ـ لــم يظهــر لألكثريــه مــا يوجــب‬\n                            ‫املالحظــة بعــد اإلجــراء األخيــر وبــاهلل التوفيــق‪.‬‬\n\n\n                                                                                      ‫‪56‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":49,"source_page_end":56,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"858c2a6b4db10a7d6ad09b7555c7485d6df0c84a952c58d26aec8fe769009596","normalized_text_hash":"8ebe9ebc3d4132c0f0dd6f40d11ad0cfcd3fbec96c80a17cd224e2c792ab2033","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p49-33341688"},{"id":"2fee1666-18d3-5b24-83fa-4ee894a8b9e3","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إقرار- إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واجللد واملنع من السفر .","document_number":"33321801","case_number":"33422610","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/06/30","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إقرار- إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واجللد واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33321801:‬تاريخه‪1433/06/30 :‬هـ‬\n                         ‫رقم الدعوى‪33422610 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3455396‬تاريخه‪1434/03/04:‬هـ‬\n\n\n       ‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتعاطيهــا‪ -‬إقــرار‪-‬‬\n       ‫إدانــة‪ -‬نــزول عــن احلــد األدنــى للعقوبــة‪ -‬التعزيــر بالســجن واجللــد‬\n                                                            ‫واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n       ‫املــواد (‪ )41‬و (‪ )56‬و (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                  ‫العقليــة‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة حبــة مــن احلبــوب‬\n       ‫احملظــورة احملتويــة علــى اإلمفيتامــن بقصــد التعاطــي وتعاطيــه مــن‬\n       ‫نوعهــا‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام‬\n       ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬حيــث إنــه مت تفتيــش ســيارته‬\n       ‫بعــد اســتيقافها فعثــر حتــت أقدامــه علــى حبــة واحــدة يشــتبه أن تكــون‬\n       ‫مــن احلبــوب احملظــورة‪ ،‬وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة‬\n       ‫العينــة املرســلة ملــادة اإلمفيتامــن‪ ،‬كمــا أقــر املدعــى عليــه أمــام‬\n       ‫احملكمــة مبــا أســنده إليــه املدعــي العــام‪ ،‬بنــاء علــى مــا تقــدم حكمــت‬\n       ‫احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب إليــه وقــررت ســجنه‬\n       ‫ملــدة أربعــة أشــهر وجلــده خمســة وســبعني جلــدة دفعــة واحــدة ومنعــه‬\n\n‫‪57‬‬\n\f‫مــن الســفر خــارج اململكــة مــدة ســنتني‪ ،‬وعــارض واملدعــي العــام علــى‬\n                 ‫احلكــم‪ -‬وصدقــت محكمــة االســتئناف علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعنيــزة برقــم ‪ 33422610‬وتاريــخ ‪1433/06/23‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331183129‬وتاريــخ ‪1433/06/23‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق ‪1433/06/28‬ه ـ افتتحــت اجللســة الســاعة ‪09 :15‬‬\n‫وفيهــا حضــر املدعــي العــام وحضــر حلضــوره ‪ ........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ........‬وادعــى املدعــي العــام قائــا‪ :‬بصفتــي‬\n‫مدعيـ ًا عامـ ًا يف دائــرة التحقيــق واالدعــاء العــام مبحافظــة عنيــزة أدعــي‬\n‫علــى‪ ،.....:‬البالــغ مــن العمــر (‪ )32‬عامـاً‪ ،‬هويــة وطنية رقــم (‪،)...............‬‬\n‫أعــزب ‪ ،‬متعلــم ‪ ،‬متســبب ‪ ،‬يقيــم مبحافظــة عنيــزة ‪ ،‬وأوقــف بتاريــخ‬\n‫ـاء علــى املــادة‬\n                 ‫‪1433/5/11‬ه ـ وأفــرج عنــه بتاريــخ ‪1433/5/15‬ه ـ بنـ ً‬\n‫(‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‪ .‬إنــه بتاريــخ ‪1433/5/11‬ه ـ وأثناء‬\n‫عمــل دوريــات امــن الطــرق علــى طريــق املدينــة ‪ -‬القصيــم الســريع مت‬\n‫اســتيقاف ســيارة مــن نــوع (‪ )......‬بقيــادة املدعــى عليــه ولوحــظ عليــه‬\n‫االرتبــاك‪ ،‬وبتفتيــش الســيارة عثــر حتــت أقدامــه علــى (‪ )1‬حبــة واحــدة‬\n‫حتمــل عالمــة الكبتاجــون يشــتبه أن تكــون محظورة‪.‬وقــد أثبــت‬\n‫التقريــر الكيميائــي الشــرعي املرفــق الصــادر مــن املركــز اإلقليمــي‬\n‫ملراقبــة الســموم بالقصيــم رقــم (‪ )641‬لعــام ‪1433‬ه ـ إيجابيــة مــا أرســل‬\n‫للتحليــل لإلمفيتامــن املنبــه احملظــور املــدرج بجــدول املؤثــرات العقليــة‬\n\n                                                                                        ‫‪58‬‬\n\f     ‫رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة‪ .‬وبســماع أقوالــه أقــر بحيــازة احلبــة املضبوطة بقصد االســتعمال‪.‬‬\n     ‫وباســتجوابه أقــر بحيــازة (‪ )1‬حبــة محظــورة بقصــد االســتعمال وانــه‬\n     ‫يســتعمل احلبــوب احملظــورة منــذ حوالــي ســنة‪.‬وانتهى التحقيــق معــه إلــى‬\n     ‫اتهامــه بحيــازة (‪ )1‬حبــة إمفيتامــن محظــورة وذلــك بقصــد التعاطــي‬\n     ‫وتعاطيــه لنوعها‪.‬وذلــك لألدلــة والقرائــن التالية‪1:‬ـ ـ إقــراره املــدون علــى‬\n     ‫الصفحــة رقــم (‪ )1‬مــن دفتــر التحقيــق املرفــق لفــه (‪ )11‬ومــا جــاء بســماع‬\n     ‫أقوالــه املدونــة علــى الصفحــة رقــم (‪ )7‬مــن اللفــة رقــم (‪2.)1‬ـ محضــر‬\n     ‫القبــض املرفــق لفــة رقــم (‪3.)2‬ـ ـ التقريــر الكيميائــي الشــرعي لفــة‬\n     ‫رقــم (‪ .)13‬وباالطــاع علــى ســوابقه تبــن خلــوه مــن الســوابق‪ .‬وحيــث‬\n     ‫إن مــا أقــدم عليــه املذكــور عليــه فعــل محــرم شــرع ًا ومجــرم نظام ـ ًا‬\n     ‫مبوجــب املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n     ‫الصــادر باملرســوم امللكــي رقــم (م‪ ) 39/‬وتاريــخ ‪1426/7/8‬ه ـ ومعاقب‬\n     ‫عليــه شــرع ًا ونظامـ ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n     ‫بالعقوبــات التاليــة‪ :‬أوالً‪ :‬الســجن وفق ـ ًا للفقــرة األولــى مــن املــادة (‪)41‬‬\n     ‫احلاديــة واألربعــن مــن النظــام املشــار إليــه‪ .‬ثاني ـاً‪ :‬باملنــع مــن الســفر‬\n     ‫خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة الســجن وفق ـ ًا للفقــرة األولــى‬\n     ‫مــن املــادة (‪ )56‬السادســة واخلمســن مــن النظــام املشــار إليــه‪ .‬وبعــرض‬\n     ‫دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n     ‫العــام يف دعــواه صحيــح حيــث قبــض علــي ومعــي احلبــة وقصــدي منهــا‬\n     ‫التعاطــي وأنــا أتعاطــى احلبــوب احملظــورة منــذ ســنة هكــذا أجــاب فبنــاء‬\n     ‫علــى مــا تقــدم وحيــث طلــب املدعــي العــام إثبــات إدانــة املدعــى عليــه‬\n     ‫مبــا أســند إليــه وحيــث أقــر املدعــى عليــه بدعــوى املدعــي العــام لــذا‬\n\n\n‫‪59‬‬\n\f‫فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة حبــة واحــدة مــن احلبــوب‬\n‫احملظــورة وثبــت لــدي إدانتــه بتعاطــي احلبــوب احملظــورة وحكمــت‬\n‫بســجنه ملــدة ســتة أشــهر ويحســب منهــا مــدة إيقافــه الســابقة وذلــك بنــاء‬\n‫علــى املــادة رقــم (‪ )41‬مــن نظــام املخــدرات وجلــده خمســة وســبعني جلــدة‬\n‫دفعــة واحــدة لقــاء تعاطيــه احلبــوب احملظــورة ومنعــه مــن الســفر مــدة‬\n‫ســنتني بنــاء علــى املــادة رقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات هــذا‬\n‫مــا ظهــر لــي وبعرضــه عليهمــا قــرر املدعــي العــام عــدم قناعتــه باحلكــم‬\n‫وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة وقــرر املدعــى عليــه عــدم‬\n‫قناعتــه باحلكــم وطلــب رفعهــا حملكمــة االســتئناف بالئحــة اعتراضيــة‬\n‫وافهــم ان لــه ثالثــون يومــا مــن تاريــخ صــدور الصــك يف يــوم األحــد‬\n‫املوافــق ‪1433/06/29‬ه ـ فــاذا قــدم الئحــة خــال املــدة واال اكتســب‬\n‫احلكــم القطعيــة ففهــم ذلــك وعليــه جــرى التوقيــع وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/06/28‬ه ـ ويف يــوم‬\n‫األحــد املوافــق ‪1433/08/04‬ه ـ افتتحــت اجللســة الســاعة ‪ 30:10‬وفيهــا‬\n‫لــم يقــدم املدعــي عليــه الئحــة اعتراضيــة وقــد تســلم صــورة مــن صــك‬\n‫احلكــم الصــادر برقــم ‪ 33321801‬يف ‪1433/6/30‬ه ـ وقــد مضــت املدة‬\n‫النظاميــة ولــم يقــدم الئحــة اعتراضيــة لــذا اكتســب احلكــم القطعيــة‬\n‫بحــق املدعــي عليــه وســوف ترفــع كامــل املعاملــة إلــى االســتئناف حيــث‬\n‫أن املدعــي العــام لــم يقــرر القناعــة باحلكــم وبــاهلل التوفيــق ‪ ،‬وصلى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1433/08/04‬ه ـ‬\n‫ويف يــوم الثالثــاء املوافــق ‪1433/11/16‬ه ـ ويف متــام الســاعة التاســعة‬\n‫صباحــا عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم‬\n‫‪ 33393945‬وتاريــخ ‪1433/08/26‬ه ـ الصــادر مــن الدائــرة اجلزائيــة‬\n\n\n                                                                                    ‫‪60‬‬\n\f     ‫األولــى مبنطقــة القصيــم واملتضمــن املالحظــة علــى حكمــي مبــا يلــي‪:‬‬\n     ‫(لوحــظ أن ماحكــم بــه فضيلتــه مــن ســجن كثيــر ولعــدم وجــود ســوابق‬\n     ‫فعلــى فضيلتــه إعــادة النظــر والتأمــل) وعليــه فقــد حضــر املدعــي العــام‬\n     ‫وحضــر حلضــوره املدعــى عليــه وملــا ذكــره أصحــاب الفضيلــة مــن‬\n     ‫ـاء علــى املــادة‬\n                    ‫مالحظــة وهــي عــدم وجــود ســوابق علــى املدعــى عليــه وبنـ ً‬\n     ‫الســتني مــن نظــام مكافحــة املخــدرات فقــد رجعــت عــن حكمــي‬\n     ‫الســابق بالنســبة للســجن وحكمــت بســجن املدعــى عليــه ملــدة أربعــة‬\n     ‫أشــهر يحســب منهــا مــدة إيقافــه وأمــا اجللــد واملنــع مــن الســفر فإننــي مــا‬\n     ‫زلــت علــى حكمــي الســابق فيهــا هــذا مــا ظهــر لــي وبعرضــه عليهمــا‬\n     ‫قــرر املدعــى عليــه عــدم قناعتــه باحلكــم وطلــب رفعهــا حملكمــة‬\n     ‫االســتئناف بالئحــة اعتراضيــة وأفهــم بــأن لــه ثالثــون يومــا مــن تاريــخ‬\n     ‫صــدور اإلحلــاق علــى القــرار وافهــم ان يحضــر يــوم غــد األربعــاء املوافــق‬\n     ‫‪1433/11/17‬ه ـ الســتالم صــورة مــن القــرار وبعرضــه علــى املدعــي‬\n     ‫العــام قــرر عــدم قناعتــه باحلكــم مكتفيــا بالئحــة الدعــوى املقدمــة‬\n     ‫معتبــرا إياهــا الئحــة اعتراضيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n     ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/11/16‬ه ـ ويف يــوم‬\n     ‫االثنــن املوافــق ‪ 1434/02/04‬ه ـ افتتحــت اجللســة الســاعة ‪ 10.15‬ولــم‬\n     ‫يحضــر املدعــى عليــه لتقــدمي الئحتــه االعتراضيــة لــذا ســقط حقــه يف‬\n     ‫االعتــراض علــى احلكــم وســوف ترفــع كامــل أوراق املعاملــة حملكمــة‬\n     ‫االســتئناف بالقصيــم لتدقيــق احلكــم لكــون املدعــي العــام معتــرض‬\n     ‫علــى احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n     ‫حــرر يف ‪1434/02/04‬ه ـ ويف يــوم األحــد املوافــق ‪1434/03/15‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 09.45‬وفيهــا عــادت املعاملــة إلينــا مــن‬\n\n\n‫‪61‬‬\n\f‫محكمــة االســتئناف بالقصيــم وبرفقهــا القــرار رقــم ‪ 3455396‬وتاريــخ‬\n‫‪1434/03/04‬ه ـ الصــادر مــن الدائــرة اجلزائيــة األولــى وقــد صــدق‬\n‫احلكــم قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه قاضــي اســتئناف ‪........‬‬\n‫ختمــه وتوقيعــه رئيــس الدائــرة ‪ ........‬ختمــه وتوقيعــه وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/03/15‬هــ‪.‬‬\n\n\n\n\n                                                                                ‫‪62‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":57,"source_page_end":62,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cdcf2c5f655ceae38515834f4fcac2bb8549c1f946ff0b2388501f025782066b","normalized_text_hash":"752ff305f7658474cd40699e1c4f7a70ffef604f9e35cc9d7613bf017d43efab","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p57-33321801"},{"id":"571e77b9-bfcc-5838-b58c-1653abf9fc35","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلبوب احملظورة بقصد التعاطي -تعاطي احلبوب احملظورة -التعزير بالسجن واجللد واملنع من السفر.","document_number":"33447648","case_number":"33423920","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/8","year":"1434","subject":"مخدرات -حيازة احلبوب احملظورة بقصد التعاطي -تعاطي احلبوب احملظورة -التعزير بالسجن واجللد واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33447648:‬تاريخه ‪1433/11/8:‬هـ‬\n                      ‫رقم الدعوى ‪33423920:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 347567‬تاريخه‪1434/01/10:‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬حيــازة احلبــوب احملظــورة بقصــد التعاطــي ‪ -‬تعاطــي‬\n     ‫احلبــوب احملظــورة ‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر‪.‬‬\n\n\n\n\n                 ‫‪ -1‬قوله تعالى (وال تقتلوا النفس التي حرم اهلل إال باحلق)‬\n                      ‫‪ -2‬قوله تعالى ( وال تفسدوا يف األرض بعد إصالحها)‬\n                  ‫‪ -3‬واملادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n                   ‫‪ -4‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n     ‫الئحــة الدعــوى ضــد املدعــى عليــه بحيــازة احلبــوب احملظــورة بقصــد‬\n     ‫التعاطــي (تعاطــي احلبــوب احملظــورة) وطلــب املدعــي العــام إثبــات مــا‬\n     ‫أســند إليــه واحلكــم عليــه بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة‬\n     ‫(‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ومنعــه مــن‬\n     ‫الســفر خــارج البــاد‪ ،‬مت القبــض علــى املدعــى عليــه بعــد اســتيقافه‬\n     ‫واالشــتباه بــه وبتفتيشــه ضبــط معــه علــى كميــة مــن احلبــوب احملظــورة‪،‬‬\n     ‫إقــرار املدعــى عليــه بالدعــوى‪ ،‬تعزيــر املدعــى عليــه بالســجن واجللــد‬\n              ‫واملنــع مــن الســفر‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n‫‪63‬‬\n\f‫ـدي أنــا‬\n      ‫احلمــدهلل وحــده والصــاة والســام علــى َمــنْ النبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى املعاملــة الــواردة‬\n                           ‫‪ ......‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء برقــم هـ ف‬\n‫‪ ......‬وتاريخ‪......‬واملقيــدة بهــذه احملكمــة برقم‪.......‬وتاريخ‪........‬واحملالــة‬\n‫إلينــا مــن فضيلــة الرئيــس برقم‪......‬وتاريخ‪......‬فتحــت اجللســة األولــى يــوم‬\n‫االثنــن ‪......‬الســاعة الثانيــة عشــرة والنصــف وفيهــا حضــر املدعــي العــام‬\n‫‪ .....‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب ســعادة‬\n‫رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء ذي الرقــم ه ـ‬\n‫ال ‪ :‬بصفتي مدعي ًا‬   ‫وقرر دعواه قائ ً‬‫ق‪ 137/2/2‬والتاريخ ‪1431/1/5‬هـ ّ‬\n‫عامـ ًا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى ‪،.....:‬البالــغ‬\n‫مــن العمــر (‪ )25‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪).....‬موظــف حكومي‪،‬محصــن‪ ،‬قبــض عليــه بتاريــخ‪ ......‬وأفــرج‬\n‫عنــه بالكفالــة بتاريــخ ‪.......‬يســكن محافظــه اإلحســاء‪ .‬انــه بتاريــخ‬\n‫‪........‬قبــض عليــه مــن قبــل أمــن الطــرق أثنــاء مــروره بنقطــة التفتيــش‬\n‫وبقيادتــه ســيارة مــن نــوع ( فــورد ) صنــع عــام (‪ )2000‬حتمــل لوحــة رقــم‬\n‫(‪ )......‬وباســتيقافه وتفتيشــه عثــر بداخــل علبــة مشــروب( بايســن) علــى‬\n‫حبــة بيضــاء مرســوم عليهــا العالمــة املميــزة للكبتاجون‪،‬كمــا عثــر‬\n‫علــى كيــس نايلــون يحتــوي علــى عشــر حبــات بيضــاء اللــون مرســوم‬\n‫عليهــا العالمــة املميــزة للكبتاجــون ‪،‬وقــد أثبــت التقريــر الكيمــاوي‬\n‫الشــرعي رقــم (‪2092‬ك ش) لعــام ‪1433‬ه ـ إيجابيــة العينــة املرســلة‬\n‫ملــادة األمفيتامــن واملدرجــة يف اجلــدول رقــم (‪ )2‬فئــة (ب) مــن نظــام‬\n\n                                                                                      ‫‪64‬‬\n\f     ‫مكافحــة املخــدرات واملؤثــرات العقليــة املوافــق عليــه باملرســوم امللكــي‬\n     ‫رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هـ‪.‬وبضبــط أقوالة‪/‬اعتــرف بحيــازة‬\n     ‫(‪ )11‬إحــدى عشــرة حبــة مــن احلبــوب املنبهــة احملظــورة بقصــد التعاطــي‬\n     ‫‪ ،‬كمــا اعتــرف بتعاطيــه لنوعهــا علــى مــدى خمــس ســنوات ‪.‬وقــد أســفر‬\n     ‫التحقيــق عــن توجيــه االتهــام لــه بحيــازة (‪ )11‬إحــدى عشــرة حبــة مــن‬\n     ‫احلبــوب املنبهــة احملظــورة بقصــد التعاطــي وتعاطيــه لنوعهــا يف ضــوء مــا‬\n     ‫جــاء يف الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة الصــادر باملرســوم امللكــي الكــرمي رقــم (م‪)39/‬‬\n                          ‫وتاريــخ ‪1426/7/8‬ه ـ وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n     ‫‪ -1‬اعترافــه املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )2‬مــن دفتــر ســماع‬\n                                               ‫األقــوال املرفــق علــى اللفــة رقــم (‪. )12‬‬\n                                      ‫‪ -2‬محضر القبض املرفق على اللفة رقم (‪. )4‬‬\n                               ‫‪ -3‬التقرير الكيماوي املرفق على اللفة رقم (‪. )31‬‬\n     ‫وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق مســجلة‬\n     ‫‪.‬وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n     ‫فعــل محــرم ومجــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا اطلــب إثبــات مــا‬\n                                                ‫أســند إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n     ‫‪ -1‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء مــا اســند إليــه اتهــام‪.‬‬\n     ‫‪ -3‬منعــة مــن الســفر خــارج البــاد وفق ـ ًا للفقــرة األولــى مــن املــادة (‪)56‬‬\n     ‫مــن النظــام املشــار إليــه ‪ .‬عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد‬\n     ‫مــن هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب قائ ـاً‪:‬‬\n     ‫صحيــح مــا نســبه لــي املدعــي العــام مــن واقعــة القبــض ومــن حيازتــي‬\n\n‫‪65‬‬\n\f‫لعــدد إحــدى عشــرة مــن حبــوب االمفيتامــن املخــدر بقصــد التعاطــي‬\n‫‪.‬ومــن اســتعمالي للحب ــوب احملظــورة وصحيــح اعتــرايف هكــذا أجــاب‬\n‫هــذا وقــد جــرى االطــاع علــى التقريــر الكيمــاوي الشــرعي الصــادر‬\n‫مــن قســم الكيميــاء الشــرعيـ ــة باملركـ ــز اإلقليمـ ــي ملراقبــة السمـ ــوم‬\n‫التــابـ ــع للمـ ــديرية العامـ ــة للش ــؤون الصحية باملنطق ـ ــة الشــرقيـ ــة برقـ ــم‬\n‫(‪ 2092‬ك ش) لعــام ‪1433‬ه ـ املتضمــن إيجابيــة عي ــنة مــا ضبــط‬\n‫للحبــوب احملظــورة كمــا جــرى االطــاع علــى كــرت ســوابق املدعــى‬\n‫عليــه املتضمــن خلــوه مــن الســوابق فبنــاء علــى مــا ورد مــن الدعــوى‬\n‫واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن أهليتــه وملــا‬\n‫ورد يف محضــر القبــض واعتــراف املدعــي عليــه ومبــا أنــه صــادق علــى‬\n‫صحــة مــا نســب إليــه مــن حيــازة احلبــوب احملظــورة علــى صفــة مــا ورد‬\n‫يف الدعــوى ومبــا أن مــا صــدر منــه حــرام يف الشــريعة ملــا يف احلبــوب‬\n‫احملظــورة مــن اخلطــر و الضــرر علــى البــاد والعبــاد وعلــى مــن صــدر‬\n‫منــه ذلــك قــال تعالــى (وال تقتلــوا النفــس التــي حــرم اهلل إال باحلــق) وقــال‬\n‫(وال تفســدوا يف األرض بعــد إصالحهــا) ممــا يســتوجب معاقبــة املدعــى‬\n‫عليــه و تعزيــزه بالعقوبــة الــواردة يف املــادة الواحــدة واألربعــن مــن نظــام‬\n‫مكافحــة املخــدرات ويتوجــه أن يكــون أقــل عقوبــة ملــا ظهــر مــن حالــه‬\n‫مــن النــدم وألنــه ال ســوابق لــه ولصغــر ســنه كمــا يتوجــه تخفيــف تلــك‬\n‫العقوبــة أيضــا حســب مقتضــى املــادة الســتني مــن النظــام نفســه ملــا‬\n‫ظهــر مــن حالــه مــن النــدم ولصغــر ســنه ولظروفــه االجتماعيــة التــي‬\n‫اقتنعــت بهــا احملكمــة وألنــه ال ســوابق لــه كمــا يتوجــه اســتحقاقه‬\n‫للعقوبــة الــواردة يف املــادة السادســة واخلمســن الفقــرة األولــى منهــا‬\n‫ومبــا أ َّنــه أقــر باســتعمال احلبــوب احملظــورة واســتعمالها ال يأخــذ‬\n\n\n                                                                                             ‫‪66‬‬\n\f     ‫حكــم املســكر لعــدم التوافــق بينهمــا يف منــاط احلكــم ممــا يتوجــه‬\n     ‫معــه تعزيــر املدعــى عليــه باجللــد دون حــد املســكر لــذا كلــه وألجــل‬\n     ‫ـدي إدانــة‬\n               ‫احلــق العــام حكمــت علــى املدعــى عليــه باآلتــي‪ :‬أوالً‪ /‬ثبــت لـ َّ‬\n     ‫املدعــى عليــه باســتعمال احلبــوب احملظــورة ويجلــد تعزيــز ًا لقــاء ذلــك‬\n     ‫بجلــده خمســة وســبعون جلــد ًة دفعــة واحــدة علنـ ًا ثانيــا‪ /‬ثبــت لــدي إدانــة‬\n     ‫املدعــى عليــه بحيــازة احلبــوب احملظــورة املوصوفــة يف الدعــوى البالــغ‬\n     ‫عددهــا إحــدى عشــرة حبــة بقصــد التعاطــي وأن يعــزر بســجنه أربعــة‬\n     ‫أشــهر حتتســب منهــا املــدة التــي أوقــف فيهــا علــي ذمــة القضيــة وذلــك‬\n     ‫مبوجــب املــادة الواحــدة و األربعــن مــن نظــام مكافحــة املخــدرات‬\n     ‫واملــادة الســتني‪ .‬ثالثــا‪ /‬وأن مينــع مــن الســفر مــدة عامــن حســب مقتضــى‬\n     ‫مــا ورد يف املــادة السادســة واخلمســن مــن النظــام نفســه علــى أن يكــون‬\n     ‫املنــع ابتــداء مــن انتهــاء محكومتيــه وبتــاوة احلكــم علــى الطرفــن‬\n     ‫وإفهــام املدعــى عليــه بحقــه يف التمييــز قــرر قناعتــه باحلكــم وطلــب‬\n     ‫املدعــي العــام رفــع احلكــم للتمييــز وأن الئحتــه االعتراضيــة هــي الئحــة‬\n     ‫الدعــوى هــذا وجــرى توجيــه املدعــى عليــه مبــا يلــزم ومــن ذلــك حرمــة‬\n     ‫اســتعمال احلبــوب احملظــورة وأثــره الســيئ علــى العقــل واملــال وأقفلــت‬\n     ‫اجللســة الســاعة الواحــدة وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                            ‫وصحبــه أجمعــن حــرر احلكــم يف ‪.......‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء برقــم ‪.......‬‬\n     ‫وتاريــخ ‪.......‬املقيــدة لــدى احملكمــة برقــم ‪ ........‬وتاريــخ ‪......‬املرفــق بهــا‬\n     ‫القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ .........‬املســجل‬\n\n\n‫‪67‬‬\n\f‫برقــم ‪ ..........‬وتاريــخ ‪......‬اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ......../‬يف‬\n‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                            ‫وصحبــه وســلم حــرر يف ‪............‬‬\n\n\n\n\n                                                                                   ‫‪68‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":63,"source_page_end":68,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9badecfc4c93996ff55250e8674248f7b0c6f683f312bf79908cb28b11d43e23","normalized_text_hash":"99901d62b48e68b1bb05473ee1b704b78167a7dffc7b66d982f5302d34a47f9b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p63-33447648"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"a36c5342-5df4-5f0d-ae80-1528886da3ea","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد الترويج والتعاطي -تستر -حيازة أدوات عليها آثار احلشيش -سيجارة بها حشيش -قيادة سيارة حتت تأثير املخدر -تعزير بالسجن واجللد.","document_number":"33339772","case_number":"33405805","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف احلمد هلل وحده","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/13","year":"1434","subject":"مخدرات -حيازة حشيش بقصد الترويج والتعاطي -تستر -حيازة أدوات عليها آثار احلشيش -سيجارة بها حشيش -قيادة سيارة حتت تأثير املخدر -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 33339772 :‬تاريخه ‪1433/7/13 :‬هـ‬\n                         ‫رقم الدعوى ‪33405805 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3428035‬تاريخه‪1434/02/03:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬حيــازة حشــيش بقصــد الترويــج والتعاطــي ‪ -‬تســتر‪ -‬حيــازة‬\n       ‫أدوات عليهــا آثــار احلشــيش ‪ -‬ســيجارة بهــا حشــيش ‪ -‬قيــادة ســيارة‬\n                               ‫حتــت تأثيــر املخــدر ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n                                 ‫‪ -1‬قوله تعالى ( وتعاونوا على البر و التقوى )‬\n       ‫‪ -2‬قولــه تعالــى ( إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن آمنــوا‬\n                                                               ‫لهــم عــذاب أليــم )‬\n       ‫‪ -3‬املــادة (‪ )41‬و املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫ا لعقليــة‬\n\n\n\n\n       ‫الئحــة الدعــوى العامــة ضــد ثالثــة أشــخاص بتوجيــه االتهــام إلــى األول‬\n       ‫بحيازة كمية من احلشــيش املخدر ومشــرط و مقص بها آثار احلشــيش‬\n       ‫بقصــد الترويــج والتعاطــي و حيــازة ســيجارة ملفوفــة ثبــت احتوائهــا علــى‬\n       ‫املــادة الفعالــة للحشــيش املخــدر بقصــد التعاطــي و تعاطيــه لهــا و للثانــي‬\n       ‫بحيــازة حشــيش و بيــع ســيجارة ملفوفــة ثبــت احتوائهــا علــى احلشــيش‬\n       ‫املخــدر بقصــد التعاطــي و تعاطيــه لهــا أثنــاء قيــادة املركبــة وإلــى‬\n       ‫الثالــث بالتســتر عليهمــا‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليهــم و‬\n\n‫‪25‬‬\n\f‫احلكــم علــى األول بالســجن و اجللــد و الغرامــة و املنــع مــن الســفر و علــى‬\n‫الثانــي بالســجن و املنــع مــن الســفر و علــى الثالــث بعقوبــة تعزيريــة لقــاء‬\n‫تســتره علــى األول و الثانــي‪ ،‬واثبــات قيــادة الثانــي للســياره حتــت تأثيــر‬\n‫املخــدر وإفهامــه بــأن عقابــه عائــد لولــي األمــر‪ ،‬مت القبــض علــى املدعــى‬\n‫عليهــم بعــد مشــاهدة األول يســتلم مــن الثانــي و الثالــث و تبــن أن مــا‬\n‫اســتلمه حشــيش مخــدر‪ ،‬وقــد مت ســماع الدعــوى يف حــق املدعــي عليــه‬\n‫األول كونــه ســجني أمــا املدعــى عليهمــا الثانــي و الثالــث فلــم يحضــرا‬\n‫ومت إرجــاء احلكــم حلــن حضورهمــا‪ ،‬إقــرار املدعــى عليــه باحليــازة‬\n‫والقصــد منهــا االســتخدام الشــخصي وإنــكاره الترويــج‪ ،‬توجيــه‬\n‫الشــبهة للمدعــى عليــه بالترويــج لوجــود املشــرط واملســطرة معــه وكبــر‬\n‫الكميــة‪ ،‬إثبــات إدانــة املدعــى عليــه بالتعاطــي‪ ،‬إقامــة حــد املســكر‬\n‫علــى املدعــى عليــه‪ ،‬تعزيــر املدعــى عليــه بالســجن واجللــد و املنــع مــن‬\n                       ‫الســفر‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33405805‬‬\n‫وتاريــخ ‪ 1433/06/16‬ه ـ املقيــدة باحملكمــة برقــم ‪331123077‬‬\n‫وتاريــخ ‪ 1433/06/15‬ه ـ ففــي يــوم الثالثــاء املوافــق‪1433/07/01‬‬\n‫ه ـ افتتحــت اجللســة الســاعة ‪ 07 : 30‬وفيهــا حضــر املدعــي العــام‬\n‫بصفتــي مدعيــا عامــا بدائــرة االدعــاء العــام مبحافظــة جــدة أدعــي علــى‬\n‫‪ )21( .......‬عام ـ ًا ســعودي اجلنســية مبوجــب رقــم (‪ )........‬املهنــة موظــف‬\n\n                                                                                      ‫‪26‬‬\n\f     ‫خــاص متعلــم موقــوف بالســجن العــام مبوجــب أمــر متديــد التوقيــف رقــم‬\n     ‫(ه ـ م‪ )28419/5/2‬وتاريــخ ‪1433/4/26‬ه ـ اســتناد ًا للقــرار الــوزاري‬\n     ‫رقــم (‪ )1900‬يف ‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام‬\n     ‫اإلجــراءات اجلزائيــة و‪ )21( ......‬عام ـ ًا ‪ ........‬ســعودي اجلنســية مبوجــب‬\n     ‫الهويــة الوطنيــة رقــم (‪ ، )......‬املهنــة موظــف خــاص متعلــم مفــرج عنــه‬\n     ‫بالكفالــة احلضوريــة بتاريــخ ‪1433/4/26‬ه ـ مبوجــب أمــر اإلفــراج رقــم‬\n     ‫(ه ـ م‪ )28063/5/2‬وتاريــخ ‪1433/4/25‬ه ـ اســتناد ًا للمــادة (‪ )120‬مــن‬\n     ‫نظــام اإلجــراءات اجلزائيــة و‪ )28( ........‬عامـ ًا ســعودي اجلنســية مبوجــب‬\n     ‫الهويــة الوطنيــة رقــم (‪ ).........‬املهنــة موظــف خــاص متعلــم مفــرج عنــه‬\n     ‫بالكفالــة احلضوريــة بتاريــخ ‪1433/4/25‬ه ـ مبوجــب أمــر اإلفــراج‬\n     ‫رقــم (ه ـ م‪ )28063/5/2‬وتاريــخ ‪1433/4/25‬ه ـ اســتناد ًا للمــادة (‪)120‬‬\n     ‫مــن نظــام اإلجــراءات اجلزائيــة املقبــوض عليهــم بتاريــخ ‪1433/4/23‬ه ـ‬\n     ‫وردت إخباريــه مــن أحــد املتعاونــن مفادهــا أن املدعــى عليــه األول يــروج‬\n     ‫احلشــيش املخــدر و يســتخدم لهــذا الغــرض مركبــه مــن نــوع هونــداي‬\n     ‫حتمــل اللوحــة رقــم (‪).... ...‬وأنــه ال يعــرف رقــم هاتفــه وال يســتطيع‬\n     ‫الشــراء منــه ‪ ،‬وعليــه مت رصــد حتركاتــه ويف تلــك األثنــاء حضــرت‬\n     ‫مركبــه مــن نــوع كامــري بقيــادة الثانــي وبرفقــه الثالــث ‪ ،‬وتوقفــت‬\n     ‫بجــوار مركبــة األول الــذي شــوهد بأخــذ شــيء مــن ســيارته ويســتقل‬\n     ‫مركبــة الثانــي برفــق الثالــث ومبتابعتهــم والقبــض عليهــم ضبــط مــع‬\n     ‫الثانــي ‪ :‬ربــع ســيجارة تــزن (‪ )0.2‬عشــري اجلــرام يشــتبه أن تكــون‬\n     ‫مخلوطــة مبــادة حشــيش مخــدر وشــوهد األول ‪ :‬يرمــي ســيجارة حتــت‬\n     ‫قدميــه تــزن (‪ )0.2‬عشــري اجلــرام يشــتبه أن تكــون حشــيش مخــدر‬\n     ‫‪ ،‬ومبناقشــتهم عــن مصــدر احلشــيش املخــدر أفــاد الثانــي بــأن األول‬\n\n\n‫‪27‬‬\n\f‫قــام بإهدائــه ســيجارة احلشــيش املخــدر فأنكــر األول ذلــك وبســؤال‬\n‫األول عــن مقــر ســكنه ومركبتــه أنكــر وجــود مســكن أو مركبــه‬\n‫لــه وباصطحابــه للمركبــه ‪ ........‬التــي كان يســتقلها وبفتحهــا مبفتــاح‬\n‫كان بحوزتــه وتفتيشــها وجــد علــى املقعــدة األماميــة قطعــة بلــغ وزنهــا‬\n‫(‪ )53‬ثالثة وخمســن جرام ًا يشــتبه أن تكون احلشــيش املخدر ومشــرط‬\n‫ومســطرة عليهــا آثــار مــادة احلشــيش املخــدر وأثبــت التقريــر الكيميائــي‬\n‫الشــرعي رقم (‪/1553‬ك ش م) لعام ‪1433‬هـ إيجابية العينات من املواد‬\n‫املضبوطــة واملرســلة للتحليــل ملــادة احلشــيش املخــدر واحتــواء العينــات‬\n‫(أ‪،‬ب‪،‬ج‪،‬د‪،‬هــ) علــى املــادة الفعالــة لــه املدرجــة باجلــدول رقــم (‪ )1‬فئــة‬\n‫(أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة باســتجواب‬\n‫األول ‪ :‬أقــر بحيــازة مــا مت ضبطــه معــه وعائديتهــا لــه بقصــد التعاطــي‬\n‫وأقــر بحيــازة املشــرط لتقطيــع احلشــيش املخــدر للتعاطــي وبتعاطيــه مــن‬\n‫احلشــيش املخــدر املضبــوط ولنوعــه ســابق ًا باســتجواب الثانــي ‪ :‬أقــر‬\n‫بحيــازة ســيجارة تــزن (‪ )0.2‬عشــري اجلــرام مــن احلشــيش املخــدر بقصــد‬\n‫التعاطــي وتعاطيــه منهــا ولنوعهــا ســابق ًا وأســفر التحقيــق بتوجيه االتهام‬\n‫إلــى األول بحيــازة (‪ )53‬ثالثــة وخمســن جرام ـ ًا مــن مــادة احلشــيش‬\n‫املخــدر ومشــرط ومســطرة عليهمــا آثــار ثبــت إيجابيتهــا لــذات املــادة‬\n‫بقصــد الترويــج والتعاطــي وحيازتــه ربــع ســيجارة ملفوفــة تــزن (‪)0.2‬‬\n‫عشــري اجلــرام ثبــت احتوائهــا علــى املــادة الفعالــة للحشــيش املخــدر‬\n‫بقصــد التعاطــي وتعاطيــه منهــا ولنوعهــا ســابق ًا والــى الثانــي بحيــازة ربــع‬\n‫ســيجارة ملفوفــة تــزن (‪ )0.2‬عشــري اجلــرام ثبــت احتوائهــا علــى املــادة‬\n‫الفعالــة للحشــيش املخــدر بقصــد التعاطــي وتعاطيــه منهــا أثنــاء قيادتــه‬\n‫املركبــة وتعاطيــه لنوعهــا ســابق ًا والــى الثالــث بالتســتر عليهمــا وذلــك‬\n\n\n                                                                                       ‫‪28‬‬\n\f     ‫لألدلــة والقرائــن التاليــة مــا ورد يف اعترافــا األول والثانــي املــدون بدفتــر‬\n     ‫التحقيــق املرفــق لفــة (‪ )29‬مــا ورد بشــهادة الشــهود الــواردة يف محضــر‬\n     ‫الضبــط املنــوه عنــه املرفــق لفــة (‪ )1‬مــا ورد يف التقريــر الكيميائــي‬\n     ‫الشــرعي املنــوه عنــه املرفــق لفــة (‪ )37‬كبــر حجــم الكميــة املضبوطــة‬\n     ‫مــع األول واإلخباريــة الــواردة عنــه وضبط أداة املســطرة مبركبته والتي‬\n     ‫عــادة مــا يســتخدمها املروجــن يف عملياتهــم قرائــن علــى أن مــا ضبــط‬\n     ‫كان معــد ًا للترويــج أيضـ ًا وحيــث إن مــا أقــدم عليــه املدعــى عليهــم وهــم‬\n     ‫بكامــل أهليتهــم املعتبــرة شــرع ًا مــن األفعــال احملرمــة شــرع ًا واملجرمــة‬\n     ‫نظام ـ ًا طبق ـ ًا للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n     ‫‪،‬واملعاقــب عليهــا وفق ـ ًا للمادتــن (‪ )41،38‬مــع مراعــاة مــا ورد باملــادة‬\n     ‫(‪ )62‬مــن ذات النظــام لــذا فإننــي أطلــب إثبات ما أســند إليهم ومعاقبتهم‬\n     ‫بالعقوبــات األصليــة والتكميليــة التاليــة بالســجن واجللــد والغرامــة‬\n     ‫لقــاء مــا أســند لــأول اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه بالســجن لقــاء مــا‬\n     ‫أســند للثانــي اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة‬\n     ‫املخــدرات واملؤثــرات العقليــة املشــار إليــه منعهمــا مــن الســفر خلــارج‬\n     ‫اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتهمــا وفقـ ًا للفقــرة (‪ )1‬مــن املــادة‬\n     ‫(‪ )56‬مــن نظــام املخــدرات املشــار إليــه كمــا اطلــب احلكــم علــى الثالــث‬\n     ‫بعقوبــة تعزيريــة لقــاء تســتره علــى األول والثانــي كمــا اطلــب إثبــات‬\n     ‫إدانــة الثانــي بقيــادة املركبــة حتــت تأثيــر املخــدر اســتناد ًا للفقــرة (‪)1‬‬\n     ‫مــن املــادة (‪ )68‬مــن نظــام املــرور الصــادر باملرســوم امللكي رقــم (م‪)85/‬‬\n     ‫وتاريــخ ‪1428/10/26‬ه ـ وإفهامــه بــأن عقابــه عائــد لولــي األمــر مــن قبل‬\n\n\n‫‪29‬‬\n\f‫اجلهــة املختصــة وبعــرض مــاورد بدعــوى املدعــي العــام علــى املدعــى عليــه‬\n‫احلاضــر باملجلــس الشــرعي أجــاب قائــا مــاورد يف دعــوى املدعــي العــام‬\n‫مــن توجيــه االتهــام لــي بحيــازة ثالثــة وخمســن جــرام مــن مــادة احلشــيش‬\n‫املخــدر ومشــرط ومســطرة بهــا أثــار احلشــيش املخــدر فصحيــح ولكــن‬\n‫ليــس بقصــد الترويــج والتعاطــي كمــا ورد يف دعــوى املدعــي العــام بــل‬\n‫بقصــد التعاطــي فقــط ومــاورد مــن حيازتــي ســيجارة تــزن عشــري اجلــرام‬\n‫حتتــوي علــى احلشــيش املخــدر بقصــد التعاطــي وأنــي أتعاطــى احلشــيش‬\n‫املخــدر مــن الســابق فصحيــح هــذا جوابــي علــى الدعــوى وبعــرض ذلــك‬\n‫علــى املدعــي العــام قــال الصحيــح ماذكــرت وبســؤاله هــل لديــه بينــه‬\n‫علــى ماذكــرت قــال نعــم وبينتــي تتمثــل يف اعتــراف املتهمــن األول‬\n‫والثانــي املــدون بدفتــر التحقيــق املرفــق لفــة (‪)29‬شــهادة الشــهود الــواردة‬\n‫يف محضــر الضبــط املنــوه عنــه املرفــق لفــة رقــم (‪)1‬التقريــر الكيميائــي‬\n‫الشــرعي املنــوه عنــه املرفــق لفــة (‪)37‬كبــر حجــم الكميــه املضبوطــة‬\n‫مــع األول واإلخباريــة الــواردة عنــه وضبــط أداه املســطرة بســيارته والتــي‬\n‫عــادة مــا يســتخدمها املروجــن يف عملياتهــم قرائــن علــى أن مــا ضبــط‬\n‫كان معــدا للترويــج أيضــا عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وإقــرار املدعــى عليــه بحيــازة ســيجارة تــزن عشــري اجلــرام مــن‬\n‫احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه للحشــيش املخــدر فبنــاء على‬\n‫جميــع مــا تقــدم ونظــرا لضبــط املســطرة واملشــرط وبهــا أثــار احلشــيش‬\n‫املخــدر مــع املدعــى عليــه وأقراراملدعــى عليــه بعائديتهــا لــه وحيــث‬\n‫أن مثــل تلــك األدوات يســتخدمها مروجــي احلشــيش يف العــادة ونظــرا‬\n‫لكبــر الكميــة املضبوطــة بحوزتــه وحيــث أن مــا قــدم املدعــى العــام‬\n‫مــن أدلــه وقرائــن ال يكفــي إلثبــات قصــد الترويــج وإمنــا يقــوى الشــبهة‬\n\n\n                                                                                     ‫‪30‬‬\n\f     ‫يف ذلــك وجلميــع مــا تقــدم ولقولــه تعالــى (وتعاونــوا علــى البــر والتقــوى‬\n     ‫وال تعاونــوا علــى اإلثــم والعــدوان ) وقولــه تعالــى (إن الذيــن يحبــون أن‬\n     ‫تشــيع الفاحشــة يف الذيــن آمنــوا لهــم عــذاب أليــم ) ولكــون هــذه اآلفــة‬\n     ‫مهلكــه للديــن مضيعــة للمــال والوقــت مدمــرة للعقــل ومفســدة للعــرض‬\n     ‫وجلميــع مــا تقــدم فقــد ثبــت لــدي أدانــه املدعــى عليــه بحيــازة ثالثــة‬\n     ‫وخمســن جــرام مــن احلشــيش املخــدر وســيجارة تــزن عشــري اجلــرام‬\n     ‫جميعهــا مــن احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه لنوعهــا مــن‬\n     ‫الســابق وقــوه الشــبهة يف حيــازة الكميــه املتقدمــة مــن احلشــيش بقصــد‬\n     ‫الترويــج وحكمــت عليــه لقــاء ذلــك مبــا يلــي أوال ســجنه ملــده ســنتني‬\n     ‫اســتناد للمــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n     ‫ثانيــا ســجنه ملــده ســنه ونصــف وجلــدة ثالثمائــة ســوط علــى دفعــات‬\n     ‫كل دفعــة خمســن ســوط ًا وبــن كل دفعــة والتــي تليهــا مــده ال تقــل‬\n     ‫عــن خمســة أيــام ودفعــة غرامــة ماليــه قدرهــا عشــرة األف ريــال نظيــر‬\n     ‫الشــبهة القويــة يف حيازتــه احلشــيش املخــدر بقصــد الترويــج ثالثــا منعــه‬\n     ‫مــن الســفر ملــده ثــاث ســنوات ونصــف وفقــا للمــادة (‪ )56‬مــن النظــام‬\n     ‫املشــار إليهــا رابعــا جلــدة حــد املســكر ثمانــن ســوط ًا دفعــة واحــدة‬\n     ‫نظيــر تعاطيــه للحشــيش املخــدر مــن الســابق وأرجــأت احلكــم علــى‬\n     ‫املدعــى عليــه الثانــي والثالــث إلــى حــن حضورهــم وأمــرت املدعــي العــام‬\n     ‫بإحضارهــم وجــرى عرضــه علــى الطرفــن قــرار جميعــا عــدم القناعــة‬\n     ‫وطلبــا االســتئناف فأجبتهمــا لطلبهمــا وأفهمتهمــا مبقتضــى تعليمــات‬\n     ‫االســتئناف جــرى النطــق باحلكــم يف متــام الســاعة الســابعة وخمســة‬\n     ‫واربعــن دقيقــة صباحــا وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1433/07/01‬ه ـ‬\n\n\n‫‪31‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة ففــي يــوم االربعــاء املوافــق‪ 1433/11/3‬ه ـ افتتحــت‬\n‫اجللســة الســاعة الثامنــة وحيــث وردتنــا املعاملــة مــن محكمة االســتئناف‬\n‫مبكــة املكرمــة برقــم ‪ 331828826‬يف ‪ 1433/10/25‬وبرفقهــا قــرار‬\n‫املالحظــة الصــادر مــن الدائــرة اجلزائيــة الثالثــة برقــم ‪ 33432064‬يف‬\n‫‪1433/10/21‬ه ـ نــص احلاجــة منــه (وبدراســة القــرار وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقــرر اعادتهــا لفضيلــة حاكمهــا ملالحظــة أنــه‬\n‫لــم يــرد اســم املدعــي العــام يف مســتهل الدعــوى وال يف اي جلســة مــن‬\n‫جلســلت القضيــة ولــم يكتــب اســمه يف صــورة الضبــط كمــا هــو‬\n‫الواضــح مــن صــورة الضبــط املدرجــة كمــا انــه لــم يوضــح اســم املدعــى‬\n‫عليــه الــذي حضــر عنــد القاضــي وحكــم عليــه القاضــي وإن كان يفهم‬\n‫مــن اإلجابــة أنــه االول لكــن ذلــك ال يكفــي ألنــه جــاء خلــط يف اجابتــه‬\n‫فينبغــي ذكــر اســم املدعــى عليــه الــذي حضــر عنــد القاضــي وحكــم‬\n‫عليــه ملالحظــة ذلــك واهلل املوفــق) وموقــع ومختــم مــن اصحــاب الفضيلــة‬\n‫اعضــاء الدائــرة اجلزائيــة الثالثــة وهــم كال مــن الشــيخ ‪ .....‬والشــيخ د‪.....‬‬\n‫والشــيخ ‪ .......‬وعليــه فأجيــب اصحــاب الفضيلــة بأنــه نظــرا لوجاهــة‬\n‫ماذكــر فــإن اســم املدعــى عليــه هــو ‪ ....‬ورقــم تكليفــه مــن مرجعــه‬\n‫هــو ‪15832‬يف ‪1433/3/6‬ه ـ وامــا املدعــى عليــه الــذي حضــر وحكــم‬\n‫عليــه هــو ‪ ......‬وامــا املدعــى عليــه الثانــي والثالــث فلــم يحضــرا وأرجئــت‬\n‫احلكــم عليهــم الــى حــن حضورهــم وأمــرت املدعــي العــام بإحضارهــم‬\n‫جــرى قفلهــا يف متــام الســاعة الثامنــة والربــع وصلــى اهلل وســلم علــى نبينــا‬\n                                                  ‫محمــد والــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n\n\n                                                                                       ‫‪32‬‬\n\f     ‫مبحافظــة جــدة ففــي يــوم االحــد املوافق‪ 1434/1/4‬هـ افتتحت اجللســة‬\n     ‫الســاعة التاســعة وحيــث وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n     ‫مبكــة املكرمــة برقــم ‪ 332106911‬يف ‪1433/12/22‬ه ـ وبرفقهــا‬\n     ‫قــرار املالحظــة الصــادر مــن الدائــرة اجلزائيــة الثالثــة برقــم ‪33471121‬‬\n     ‫يف ‪1433/12/1‬ه ـ نــص احلاجــة منــه (وبدراســة القــرار وصــورة ضبطــه‬\n     ‫والئحتــه االعتراضيــة تقــرر اعادتهــا لفضيلــة حاكمهــا ملالحظــة ان‬\n     ‫فضيلتــه ذكــر ان اســم املدعــي عليــه هــو ‪ ......‬حــن انــه ذكــر يف صــورة‬\n     ‫الضبــط ان اســم املدعــي العــام ‪ ......‬فعلــى فضيلتــه حتريــر الصــواب‬\n     ‫ملالحظــة ذلــك واهلل املوفــق) وموقــع ومختــم مــن اصحــاب الفضيلــة‬\n     ‫اعضــاء الدائــرة اجلزائيــة الثالثــة وهــم كال مــن الشــيخ ‪ ....‬والشــيخ‬\n     ‫‪ ....‬والشــيخ د‪ ......‬وعليــه فأجيــب عمــا ذكــره اصحــاب الفضيلــة‬\n     ‫بــأن املدعــي العــام هــو ‪ .....‬ورقــم تكليفــه مــن مرجعــه هــو ‪15832‬يف‬\n     ‫‪1433/3/6‬ه ـ وامــا املدعــى عليــه فهــو ‪ .....‬وقــد جــرى تصحيــح اخلطــأ‬\n     ‫الواقــع يف الســطر احلــادي عشــر مــن الصفحــة الرابعــة مــن القــرار عــن‬\n     ‫طريــق التقويــس عليــه يف اصــل القــرار وقــررت اعــادة كامــل اوراق‬\n     ‫املعاملــة الــى محكمــة االســتئناف التخــاذ مــا يــراه اصحــاب الفضيلــة‬\n     ‫‪ ............‬قفلهــا يف متــام الســاعة التاســعة والربــع وصلــى اهلل وســلم علــى‬\n                                               ‫نبينــا محمــد والــه وصحبــه وســلم‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪:‬‬\n     ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة‬\n     ‫االســتئناف يف منطقــة مكــة املكرمــة جــرى منــا االطــاع علــى‬\n     ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة‬\n     ‫املســاعد رقــم‪ 34/10330‬وتاريخ‪1434/1/20‬ه ـ املرفــق بهــا القــرار‬\n\n\n‫‪33‬‬\n\f‫الصــادر مــن فضيلــة الشــيخ‪ .... /‬القاضــي باحملكمــة اجلزائيــة بجــده‬\n‫برقــم‪ 33339772‬وتاريــخ ‪1433/7/13‬ه ـ ‪ ،‬املتضمــن دعــوى املدعــي‬\n‫دون بباطــن‬‫العــام ضــد‪ .... /‬ورفقــاه املتهــم يف مخــدرات احملكــوم مبــا ّ‬\n‫القــرار وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n‫املوافقــة علــى احلكــم بعــد االيضــاح االخيــر واهلل املوفــق وصلــى اهلل‬\n                          ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                ‫‪34‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":25,"source_page_end":34,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"019c2e9fd3715e4371b4dc157be775d7ee125ea5e811817d4811f52f851267d7","normalized_text_hash":"e0e904a0b14660c37024a782a84500df850f86da2c978436165699c5afe33ca7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p25-33339772"},{"id":"81cb4306-744f-5d64-a937-e1dfd1050b83","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة قطعة من مادة احلشيش املخدر لغرض االستعمال -تعاطي سيجارة وجد حتتوي على احلشيش املخدر- تستر على مصدر املخدرات -إقامة حد املسكر -تعزير املدعى عليه بالسجن واجللد واملنع من السفر -عدم البينة على قيادة السيارة حتت تأثير املسكر -صرف نظر.","document_number":"33445090","case_number":"33410920","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/2","year":"1434","subject":"مخدرات -حيازة قطعة من مادة احلشيش املخدر لغرض االستعمال -تعاطي سيجارة وجد حتتوي على احلشيش املخدر- تستر على مصدر املخدرات -إقامة حد املسكر -تعزير املدعى عليه بالسجن واجللد واملنع من السفر -عدم البينة على قيادة السيارة حتت تأثير املسكر -صرف نظر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪33445090:‬تاريخه ‪1433/11/2:‬هـ‬\n                      ‫رقم الدعوى ‪33410920 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 3432597‬تاريخه‪1434/02/09:‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬حيــازة قطعــة مــن مــادة احلشــيش املخــدر لغــرض‬\n     ‫االســتعمال‪ -‬تعاطــي ســيجارة وجــد حتتــوي علــى احلشــيش املخــدر‪-‬‬\n     ‫تســتر علــى مصــدر املخــدرات ‪ -‬إقامــة حــد املســكر ‪ -‬تعزيــر املدعــى عليــه‬\n     ‫بالســجن واجللــد واملنــع مــن الســفر ‪ -‬عــدم البينــة علــى قيــادة الســيارة‬\n                                              ‫حتــت تأثيــر املســكر ‪ -‬صــرف نظــر‪.‬‬\n\n\n\n\n                       ‫املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n     ‫الئحــة الدعــوى ضــد املدعــى عليــه بحيــازة قطعــة مــن احلشــيش املخــدر‬\n     ‫لغــرض االســتعمال واســتعماله لهــا مــن الســابق وقيــادة الســيارة حتــت‬\n     ‫تأثيــر احلشــيش املخــدر وتســتره علــى مصــدر املخــدرات‪ ،‬وطلــب املدعــي‬\n     ‫العــام إثبــات مــا اســند إليــه بالعقوبــة الــواردة يف املــادة (‪ )41/1‬مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة ومنعــه مــن الســفر والفصــل يف‬\n     ‫قيادتــه للســيارة حتــت تأثيــر تعاطــي احلشــيش املخــدر وبعقوبــة تعزيريــة‬\n     ‫لتســتره علــى مصــدر املخــدرات‪ ،‬مت القبــض علــى املدعــى عليــه بعــد‬\n     ‫االشــتباه بــه واســتيقافه مــن قبــل الدوريــات األمنيــة وبتفتيشــه عثــر معــه‬\n     ‫علــى قطعــة مــن احلشــيش املخــدر‪ ،‬إقــراره باحليــازة للحشــيش املخــدر‬\n\n‫‪35‬‬\n\f‫لغــرض االســتخدام واســتخدامه للحشــيش املخــدر‪ ،‬وإنــكاره قيــادة‬\n‫الســيارة حتــت تأثيــر احلشــيش املخــدر عــدم وجــود بينــة للمدعــى العــام‬\n‫لقيــادة الســيارة حتــت تأثيــر احلشــيش إقامــة حــد املســكر علــى املدعــى‬\n‫عليــه‪ ،‬تعزيــر املدعــى عليــه بالســجن واجللــد واملنــع مــن الســفر‪ ،‬صــرف‬\n‫النظــر عــن إثبــات اإلدانــة بقيادة الســيارة وهو حتت تأثير املســكر لعدم‬\n ‫ثبــوت موجبــه‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف بالريــاض ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا د‪ ....... /‬القاضي يف احملكمة اجلزائية‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33410920‬وتاريــخ ‪ 1433/06/18‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331148189‬وتاريــخ ‪ 1433/06/18‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1433/11/02‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ .....‬وقــدم الئحــة الدعــوى قائــا بصف ــتي‬\n‫مدعيـ ًا عامـ ًا يف دائـرة االدعـاء العـام مبدينة الرياض أدعـي على ‪......../‬‬\n‫‪ 26‬ســنة ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).......‬يقيــم‬\n‫مبدينــة الريــاض مفــرج عنــه بالكفالــة احلضوريــة‪ .‬حيــث انــه بتاريــخ‬\n‫‪1432/12/20‬ه ـ قبــض علــى املذكــور مــن قبــل دوريــات امــن الطــرق‬\n‫بــال‪ ....‬اثــر االشــتباه بــه عندمــا كان يقــود ســيارة وبتفتيشــه عثــر علــى‬\n‫قطعــة بنيــة اللــون بلــغ وزنهــا (‪ )6‬ســتة جرامــات يشــتبه ان تكــون مــن‬\n‫مــادة احلشــيش املخــدر داخــل جيــب البنطــال االيســر‪ .‬واثبــت التقريــر‬\n‫الكيميائــي الشــرعي رقــم (‪ 382‬س ‪ )2‬لعــام ‪1433‬ه ـ احتــواء القطعــة‬\n‫علــى مــادة احلشــيش املخــدر‪ .‬وبالتحقيــق مــع املدعــى عليه اعتــرف بحيازة‬\n\n                                                                                    ‫‪36‬‬\n\f     ‫احلشــيش املخــدر املضبوطــة معــه لغــرض االســتعمال وبانــه يســتخدم‬\n     ‫مــادة احلشــيش املخــدر منــذ ســنة تقريب ـ ًا وانــه تعاطــى ســيجارة واحــدة‬\n     ‫قبــل القبــض عليــه ‪ .‬وقــد اســفر التحقيــق عــن اتهامــه بحيازتــه قطعــة‬\n     ‫بنيــة اللــون بلــغ وزنهــا (‪ )6‬ســتة جرامــات مــن مــادة احلشــيش املخــدر‬\n     ‫لغــرض االســتعمال واســتعماله لهــا مــن الســابق وقيــادة الســيارة حتــت‬\n     ‫تاثيــر تعاطــي احلشــيش املخــدر وتســتره علــى مصــدر املخــدرات وذلــك‬\n                                                          ‫لألدلــة والقرائــن التاليــة ‪:‬‬\n     ‫‪ -1‬اعترافــه واقــراره املــدون علــى الصفحــة رقــم (‪ )5‬من ملف االســتدالل‬\n                                                                           ‫لفــة رقــم (‪. )1‬‬\n                          ‫‪ -2‬ما جاء يف محضر القبض والتفتيش لفة رقم (‪. )4‬‬\n                                ‫‪ -3‬التقرير الكيميائي الشرعي لفة رقم (‪. )19‬‬\n                          ‫وببحث سوابقه تبني عدم وجود سوابق مسجله عليه ‪.‬‬\n     ‫وحيــث ان مــا اقــدم عليــه املذكــور فعــل معاقــب عليــه شــرعا ونظامــا‬\n     ‫مبوجــب املــادة (‪ )2/3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n     ‫الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬يف ‪1426/7/8‬ه ـ ونظــام املــرور‬\n     ‫الصــادر باملرســوم امللكــي رقــم (م‪)85/‬يف ‪1428/10/26‬ه ـ اطلــب‬\n                                    ‫اثبــات مــا اســند اليــه واحلكــم عليــه باالتــي ‪:‬‬\n                         ‫‪ -1‬اجراء املقتضى الشرعي لتعاطيه احلشيش املخدر ‪.‬‬\n     ‫‪ -2‬بالعقوبــة الــواردة يف املــادة (‪ )1/41‬مــن نظــام املخــدرات واملؤثــرات‬\n                                                                   ‫العقليــة املشــار اليــه‬\n     ‫‪ -3‬منعــه مــن الســفر بعــد تنفيــذ عقوبتــه وفقــا للمــادة (‪ )1/56‬مــن ذات‬\n                                                                                  ‫النظــام ‪.‬‬\n     ‫‪ -4‬الفصــل يف قيادتــه للســيارة حتــت تاثيــر تعاطــي احلشــيش املخــدر‬\n\n\n‫‪37‬‬\n\f                                                ‫وفقــا لنظــام املــرور املشــار اليــه ‪.‬‬\n                           ‫‪ -5‬بعقوبة تعزيرية لتستره على مصدر املخدرات ‪.‬‬\n‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه ‪ .....‬أجــاب قائــا مــا‬\n‫ذكــره املدعــي العــام صحيــح فقــد قبــض علــي مــن قبــل دوريــات امــن‬\n‫الطــرق بــ‪ .......‬وقــد وجــدوا معــي قطعــة حشــيش وزنهــا ســتة جرامــات‬\n‫حزتهــا لغــرض االســتعمال فقــط وأنــا أدخــن احلشــيش وأثنــاء القبــض لــم‬\n‫أكــن مســتعمال للحشــيش فآخــر مــرة قبــل القبــض علــي بيــوم وليــس‬\n‫علــي ســوابق وال اعــرف املصــدر الــذي باعنــي احلشــيش هكــذا أجــاب‬\n‫وبســؤال املدعــي البينــة عــن دعــواه بتدخــن املدعــى عليــه احلشــيش أثنــاء‬\n‫القيــادة قــال ال بينــة لــي وقــد جــرى اطالعــي علــى أقوالــه يف املعاملــة‬\n‫فوجدتهــا كمــا جــاء يف جوابــه ولــم أجــد لــه قــوال أو إقــرار ًا أنــه حــال‬\n‫قيادتــه للســيارة كان حتــت تأثيــر احلشــيش املخــدر أو أي مســكر وقــد‬\n‫جــرى اطالعــي علــى التقريــر الكيميائــي الشــرعي رقــم (‪ 382‬س ‪)2‬‬\n‫لعــام ‪1433‬ه ـ املتضمــن ايجابيــة القطعــة للحشــيش املخــدر ولــم أجــد‬\n‫لــه ســوابقا وقــد وجــدت انــه أوقــف يف ‪1432/12/20‬ه ـ وأفــرج عنــه يف‬\n‫‪1432/12/22‬هـ ـ فبنــاء ملــا تقــدم مــن الدعــوى واإلجابــة وحيــث صــادق‬\n‫املدعــى عليــه علــى دعــوى املدعــي العــام واقــر بحيازتــه لســتة جرامــات‬\n‫مــن احلشــيش املخــدر لغــرض التعاطــي واقــر بتدخينــه احلشــيش وأنكــر‬\n‫قيادتــه للســيارة وهــو حتــت تأثيــر احلشــيش ولــم يقــدم املدعــي العــام‬\n‫البينــة علــى ذلــك ولــم أجــد لــه قــوال يف املعاملــة بذلــك فقــد ثبــت لــدي‬\n‫مانســب للمدعــى عليــه مــن حيازتــه للحشــيش املخــدر البالــغ وزنــه ســتة‬\n‫جرامــات مــن احلشــيش املخــدر وتعاطيــه للحشــيش فقــط ونظــرا لقلــة‬\n‫الكميــة ولعــدم ســوابقه فقــد قــررت معاملتــه حســب املــادة الســتون مــن‬\n\n\n                                                                                            ‫‪38‬‬\n\f     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وقــررت مايلــي اوال‪:‬ســجن‬\n     ‫املدعــى عليــه عشــرين يومــا حتســب منها فتــرة ايقافــة ‪.‬ثانيا‪:‬جلده ثمانني‬\n     ‫جلــده حــد املســكر ‪.‬ثالثا‪:‬جلــده أربعــن جلــده تعزيــر لقــاء تســتره علــى‬\n     ‫املصــدر الــذي باعــه احلشــيش ‪.‬رابعا‪:‬منعــه مــن الســفر خــارج اململكــة‬\n     ‫ســنتني اعتبــارا مــن تاريــخ انتهــاء فتــرة ســجنه‪.‬رابعا‪:‬صرف النظــر عــن‬\n     ‫دعــوى املدعــي العــام إثبــات قيادتــه للســيارة وهــو حتــت تأثيــر تعاطــي‬\n     ‫احلشــيش ومبــا قــررت حكمــت وبعــرض احلكــم علــى الطرفــن قــرر‬\n     ‫اجلميــع عــدم القناعــة باحلكــم وطلــب اســتئنافه بــدون الئحــة اعتــراض‬\n     ‫فأجيــب لطلبهمــا ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/02‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n     ‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n     ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n     ‫‪ 331148189‬وتاريــخ ‪1434/1/10‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ....... /‬املســجل برقــم ‪33445090‬‬\n     ‫وتاريــخ ‪1433/11/2‬ه ـ اخلــاص بدعــوى املدعــى العــام ضــد ‪ ....... /‬يف‬\n     ‫قضيــة مخــدرات علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه‬\n     ‫مبــا هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n     ‫املعاملــة لــم يظهــر لألكثريــة مــا يوجــب املالحظــة علــى احلكــم مــع‬\n     ‫تنبيــه فضيلتــه إلــى ايضــاح القصــد مــن احليــازة يف اإلثبــات مالحظــة‬\n     ‫ال ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬  ‫ذلــك مســتقب ً‬\n                                                                     ‫وصحبــه وســلم‪.‬‬\n\n\n\n‫‪39‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":35,"source_page_end":39,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dccfb023b5e7b0ac5fd68bd443578ed7491e08bd47761e3814e8060e03e72591","normalized_text_hash":"7359c210a5759b02bc7a13a593a1a58a79df1eff6a19d9a74c8940b34a2cd6b7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p35-33445090"},{"id":"c1b84e75-4623-53a0-ba04-05d0032507b5","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة الكوكاين املخدر لقصد الترويج -حيازة ميزان الكتروني به آثار مادة مخدرة بقصد الترويج -اشتراك يف تنظيم عصابة منظمة لالجتار باملواد املخدرة -اختاء محرم -مقاومة الفرقة القابضة -تعزير بالسجن واجللد ومصادرة اجلوال والشريحة املستخدمان يف اجلرمية .","document_number":"3458629","case_number":"33420204","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/09","year":"1434","subject":"مخدرات -حيازة الكوكاين املخدر لقصد الترويج -حيازة ميزان الكتروني به آثار مادة مخدرة بقصد الترويج -اشتراك يف تنظيم عصابة منظمة لالجتار باملواد املخدرة -اختاء محرم -مقاومة الفرقة القابضة -تعزير بالسجن واجللد ومصادرة اجلوال والشريحة املستخدمان يف اجلرمية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3458629:‬تاريخه‪1434/03/09:‬هـ‬\n                 ‫رقم الدعوى ‪33420204 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34199739‬تاريخه‪1434/4/28:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة الكوكايــن املخــدر لقصــد الترويــج ‪ -‬حيــازة ميــزان‬\n‫الكترونــي بــه آثــار مــادة مخــدرة بقصــد الترويــج ‪ -‬اشــتراك يف تنظيــم‬\n‫عصابــة منظمــة لالجتــار باملــواد املخــدرة ‪ -‬اختــاء محــرم ‪ -‬مقاومــة‬\n‫الفرقــة القابضــة ‪ -‬تعزيــر بالســجن واجللــد ومصــادرة اجلــوال‬\n                                 ‫والشــريحة املســتخدمان يف اجلرميــة ‪.‬‬\n\n\n\n\n                                                       ‫‪ -1‬األصل البراءة ‪.‬‬\n‫‪ -2‬الفقــرة ‪ 2‬مــن املــادة ‪ 53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                ‫العقليــة ‪.‬‬\n‫‪ -3‬الفقــرة ‪ 2‬مــن املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                 ‫العقليــة‪.‬‬\n                           ‫‪ -4‬املادة ‪ 216‬من نظام اإلجراءات اجلزائية ‪.‬‬\n‫‪ -5‬تعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم ‪ 9798‬يف‬\n                                                          ‫‪1428 /2 /10‬هــ‪.‬‬\n\n\n\n\n‫دعــوى املدعــي العــام ضــد أربعــة أشــخاص أحدهــم امــرأة مقيمــن إقامــة‬\n‫غيــر نظاميــة يحملــون بطاقــات بديلــة بطلــب إثبــات إدانتهــم بحيــازة‬\n\n                                                                               ‫‪40‬‬\n\f     ‫الكوكايــن املخــدر وميــزان إلكترونــي بــه آثــار املــادة املخــدرة‬\n     ‫بقصــد الترويــج واالشــتراك يف عصابــة منظمــة لالجتــار باملــواد املخــدرة‬\n     ‫واتهامهــم باالختــاء احملــرم واتهــام الرابــع مبقاومــة الفرقــة القابضــة‬\n     ‫مقاومــة عنيفــة‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليهــم واحلكــم‬\n     ‫عليهــم بعقوبــة الســجن واجللــد والغرامــة ومصــادرة اجلــواالت املســتخدمة‬\n     ‫يف اجلرميــة وإلغــاء شــرائحها ومصــادرة املبلــغ املالــي املضبــوط مــع اثنــن‬\n     ‫مــن املدعــى عليهــم وإبعادهــم خــارج اململكــة بعــد انتهــاء عقوبتهــم‪ ،‬مت‬\n     ‫القبــض علــى املدعــى عليهــم بعــد إخباريــة مفادهــا أنهــم يروجــون مــادة‬\n     ‫الكــراك فتــم اســتيقاف أحدهــم ومت فتــح مســكنه بإحــدى املفاتيــح‬\n     ‫التــي معــه وعثــر عليهــم باملســكن وعثــر بحوزتهــم علــى املــواد املخــدرة‪،‬‬\n     ‫اعتــراف املدعــى عليــه األول والثالــث و الرابــع‪ ،‬إنــكار املدعــى عليــه‬\n     ‫الثانــي‪ ،‬عــدم وجــود بينــة تديــن املدعــى عليــه الثانــي‪ ،‬تعزيــر املدعــى‬\n     ‫عليــه األول و الثالــث والرابــع بالســجن واجللــد واإلبعــاد مــن البــاد‪،‬‬\n     ‫مصــادرة املبالــغ املاليــة املضبوطــة معهــم‪ ،‬مصــادرة اجلــوال و الشــريحة‬\n     ‫املســتخدمان يف اجلرميــة‪ ،‬صــرف النظــر عــن املدعــى عليــه الثانــي لعــدم‬\n                 ‫كفايــة األدلــة‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة اجلزائيــة يف محافظــة جدة املســاعد برقــم ‪ 33420204‬وتاريخ‬\n     ‫‪1433/06/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331176483‬وتاريــخ‬\n     ‫‪1433/06/22‬ه ـ ففــي يــوم الســبت املوافــق ‪1434/03/07‬ه ـ افتتحــت‬\n\n‫‪41‬‬\n\f‫اجللســة الســاعة ‪ 08 : 45‬صباحــا املتعلقــة بدعــوى املدعــي العــام ‪...‬‬\n‫ســعودي بالســجل املدني رقم ‪ .....‬مبوجب التكليف رقم هـ م‪368/6/2‬‬\n‫وتاريــخ ‪1430/12/29‬ه ـ ضــد املدعــى عليهم‪ )29( .....-1 :‬عام ًا تشــادي‬\n‫اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ ).....‬وتاريــخ ‪1433/1/20‬ه ـ‬\n‫صــادرة مــن مكافحــة املخــدرات يقيــم بطريقــة غيــر نظاميــة عاطــل‬\n‫أمــي ‪ ،‬موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر متديــد‬\n‫التوقيــف رقم(ه ـ م‪ )7052/5/2‬يف‪1433/1/30‬ه ـ اســتناد ًا للقــرار‬\n‫الــوزاري (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪ )27( ....-2‬عام ـ ًا تشــادي‬\n‫اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ ، )....‬وتاريــخ ‪1433/1/20‬هــ‪،‬‬\n‫صــادرة مــن مكافحــة املخــدرات ‪،‬عاطــل ‪ ،‬يقيــم بطريقــة غيــر نظاميــة‬\n‫أمــي موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر متديــد‬\n‫التوقيــف رقــم (ه ـ م‪ )7050/5/2‬يف‪1433/1/30‬هــ‪ ،‬اســتناد ًا للقــرار‬\n‫الــوزاري (‪ ، )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪-3‬املــرأة‪ )38( ..../‬عام ـ ًا‬\n‫نيجيريــة اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ )....‬وتاريــخ‬\n‫‪1433/1/20‬هــ‪ ،‬صــادرة مــن مكافحة املخــدرات عاطلة تقيم بطريقة‬\n‫غيــر نظاميــة أميــة موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب‬\n‫أمــر متديــد التوقيــف رقم(ه ـ م‪)7053/5/2‬يف‪1433/1/30‬ه ـ اســتناد ًا‬\n‫للقــرار الــوزاري(‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪ )31( ، .....-4‬عام ـاً‪،‬‬\n‫تشــادي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ )....‬وتاريــخ‬\n‫‪1433/1/20‬هــ‪ ،‬صــادرة مــن مكافحــة املخــدرات عاطــل يقيــم بطريقة‬\n‫غيــر نظاميــة أمــي موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر‬\n‫متديــد التوقيــف رقم(ه ـ م‪ )7051/5/2‬يف‪1433/1/30‬هــ‪ ،‬اســتناد ًا‬\n‫ا يف دعــواه إنــه‬ ‫للقــرار الــوزاري (‪ ، )1900‬وتاريــخ ‪1428/7/9‬ه ـ قائ ـ ً‬\n\n\n                                                                              ‫‪42‬‬\n\f     ‫بتاريــخ ‪1433/1/20‬ه ـ مت القبــض علــى املدعــى عليهــم مــن قبــل أفــراد‬\n     ‫ـاء علــى إخباريــة متعاونــان عــن‬\n                                       ‫مكافحــة املخــدرات مبحافظــة جــدة بنـ ً‬\n     ‫وجــود ثالثــة أشــخاص مــن اجلنســية التشــادية يروجــون مــادة الكــراك‬\n     ‫بأحــد املســاكن ومبراقبتــه خــرج األول منــه فتــم اســتيقافه وبســؤاله‬\n     ‫عــن مســكنه أنكــر وجــود مســكن لــه فتــم فتــح املســكن بأحــد‬\n     ‫املفاتيــح التــي ضبطــت معــه وعنــد دخــول املســكن ضبــط بأحــد الغــرف‬\n     ‫الثانــي وضبطــت الثالثــة يف غرفــة أخــرى عثــر بهــا علــى تســع أكيــاس‬\n     ‫بهــا مــادة تــزن(‪ )10‬عشــرة جرامــات وعثــر بأحــد الغــرف علــى ثالثــة‬\n     ‫عشــر كيسـ ًا بهــا مــادة تــزن(‪ )14,8‬أربعــة عشــر جرامـ ًا وثمانيــة أعشــار‬\n     ‫اجلــرام ومــادة أخــرى تــزن (‪)5,8‬خمســة جرامــات وثمانيــة أعشــار اجلــرام‬\n     ‫كمــا عثــر علــى ميــزان الكترونــي وأثنــاء القبــض حضــر الرابــع وفتــح‬\n     ‫بــاب العزبــة بواســطة مفتــاح معــه وعنــد مشــاهدته للفرقــة هــرب فتمــت‬\n     ‫مالحقتــه والقبــض عليــه بعــد مقاومتــه مقاومــة عنيفــة ‪ ،‬فــورد اتصــال‬\n     ‫علــى جوالــه مــن شــخص يطلــب شــراء مــادة الكــراك املخــدر لقــاء ألــف‬\n     ‫ريــال‪ .‬فتــم القبــض عليهــم وأثبــت التقريــر الكيميائــي الشــرعي رقــم‬\n     ‫(‪/275‬ك ش م) لعــام ‪1433‬ه ـ احتــواء العينــات ( أ ‪،‬ب‪،‬ج) املضبوطــة‬\n     ‫واملرســلة للتحليــل ملــادة الكوكايــن املخــدر كمــا ثبــت احتــواء اآلثــار‬\n     ‫التــي علــى امليــزان اإللكترونــي املرســل بالعينة(د)لــذات املــادة‬\n     ‫املخدرة‪،‬املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة‬\n     ‫املخــدرات واملؤثــرات العقليــة وباســتجواب املدعــى عليهــا الثالثة‪/‬أقــرت‬\n     ‫أن مــا ضبــط لديهــا بالغرفــة مــن الكــراك املخــدر يعــود للمدعــى عليــه‬\n     ‫الرابــع وضعــه عندهــا علــى ســبيل األمانــة وأســفر التحقيــق عــن توجيــه‬\n     ‫اإلتهــام إلــى كل مــن األول والثانــي والثالثــة والرابــع بحيــازة (‪)30,6‬‬\n\n\n‫‪43‬‬\n\f‫ثالثــون جرام ـ ًا وســتة أعشــار اجلــرام مــن مــادة الكوكائــن املخــدر‬\n‫وميــزان الكترونــي بــه اثــار ثبــت انهــا لنفــس املــادة املخــدرة وذلك بقصد‬\n‫الترويــج واشــتراكهم يف عصابــة منظمــة لالجتــار باملــواد املخــدرة‬\n‫واتهامهــم جميعــا باالختــاء احملــرم شــرعا واتهــام الرابــع مبقاومــة‬\n‫الفرقــة مقاومــة عنيفــة اســتنادا للفقــرة (‪ )2‬مــن املــادة الثالثــة مــن نظــام‬\n‫مكافحــة املخــدرات وحيــث إن مــا أقــدم عليــه املدعــى عليهــم وهــم‬\n‫بكامــل أهليتهــم املعتبــرة شــرع ًا مــن األفعــال احملرمــة شــرع ًا واملجرمــة‬\n‫نظام ـ ًا طبق ـ ًا للمــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫لــذا أطلــب إثبــات مــا أســند إليهــم ومعاقبتهــم بالعقوبــات األصليــة‬\n‫والتكميليــة التاليــة‪-1 :‬احلكــم عليهــم بالســجن واجللــد والغرامــة لقــاء‬\n‫مــا اســند إليهــم اســتناد ًا للفقــرة (‪ )1‬وتشــديد العقوبــة عليهــم اســتناد ًا‬\n‫للحالتــن (أ) و(ج) مــن الفقــرة (‪ )2‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة ‪- 2‬مصــادرة أجهــزة اجلــوال مــن نــوع (‪)...‬‬\n‫ذي الرقــم املصنعــي رقــم (‪ ، )............‬بشــريحته الســتخدامه يف‬\n‫ارتــكاب اجلرميــة ‪،‬وجــوال مــن نــوع (‪ )...‬ذي الرقــم املصنعــي(‪)............‬‬\n‫وجــوال مــن نــوع(‪ )...‬ذي الرقــم املصنعــي(‪ )............‬وجــوال مــن نــوع (‪)...‬‬\n‫ذي الرقــم املصنعــي(‪ )............‬وجــوال مــن نــوع(‪ )...‬ذي الرقــم‬\n‫املصنعــي(‪ )............‬وجــوال مــن نــوع (‪ )...‬ذي الرقــم املصنعــي(‪)............‬‬\n‫وجــوال مــن نــوع (‪ )...‬ذي الرقــم املصنعــي(‪ )............‬اســتناد ًا للفقــرة رقــم‬\n‫(‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات املشــار إليــه‪ ،‬وإلغــاء‬\n‫اخلدمــة مــن الشــرائح املضبوطــة ‪ ،‬وعــدم صرفهــا لهــم مــرة أخــرى‪،‬‬\n‫اســتناد ًا إلــى تعميــم صاحــب الســمو امللكــي وزيــر الداخليــة (‪، )9798‬‬\n\n\n                                                                                         ‫‪44‬‬\n\f     ‫وتاريــخ ‪9‬ـ‪1428/2/10‬هـ‪.‬وذلــك لكونهــا تســتخدم يف التشــكيل‬\n     ‫العصابي‪-3‬مصــادرة املبلــغ املالــي املضبــوط مــع املدعــى عليــه األول‬\n     ‫وقدرة(‪)300‬ثالثمائــة ريــال ســعودي ‪،‬وكذلــك املبلــغ املالــي املضبــوط‬\n     ‫مــع املدعــى عليــه الرابــع وقدرة(‪)4900‬أربعــة آالف وتســعمائة ريــال‬\n     ‫ســعودي ‪ ،‬اســتنادا للفقــرة (‪)2‬مــن املــادة(‪ )53‬مــن نظــام مكافحــة‬\n     ‫املخــدرات املشــار إليــه ‪-4‬إبعادهــم عــن اململكــة بعــد االنتهــاء مــن تنفيــذ‬\n     ‫عقوبتهــم وعــدم الســماح لهــم بالعــودة إليهــا ‪ ،‬اســتناد ًا للفقــرة (‪ )2‬مــن‬\n     ‫املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات املشــار إليــه كمــا أطلــب‬\n     ‫احلكــم عليهــم جميعــا بعقوبــة تعزيريــة لقــاء االختــاء احملــرم شــرعا‬\n     ‫وتعزيــر املدعــى عليــه الرابــع شــرع ًا لقــاء مقاومتــه العنيفــة للفرقــة‬\n     ‫القابضــة حملاولــة الهــرب هكــذا ادعــى املدعــي العــام ا‪ .‬ه ـ وبســؤال‬\n     ‫املدعــى عليهــم عــن الدعــوى وهــم يعرفــون العربيــة أجــاب املدعــى عليــه‬\n     ‫األول ‪ ....‬صحيــح حــزت ثالثــن جرام ـ ًا وســتة أعشــار اجلــرام مــن مــادة‬\n     ‫الكوكايــن املخــدر وميــزان الكترونــي بــه آثــار الكوكايــن بقصــد‬\n     ‫الترويــج وأن احليــازة تخصنــي ومعــي املــرأة ‪ ...‬واملدعــى عليــه ‪ .....‬ســوى ‪....‬‬\n     ‫فــا عالقــة لــه باحليــازة واختليــت باملدعــى عليهــا املــرأة حجــة وال تربطني‬\n     ‫بهــا صلــة قرابــة شــرعية وأجــاب املدعــى عليــه الثانــي ‪ ....‬مــا ذكــره‬\n     ‫املدعــي العــام غيــر صحيــح جملــة وتفصيــا وأجابــت املدعــى عليهــا‬\n     ‫الثالثــة املــرأة‪ ... /‬صحيــح حــزت ثالثــن جرامــا وســتة أعشــار اجلــرام مــن‬\n     ‫مــادة الكوكايــن املخــدر وميــزان الكترونــي بــه آثــار الكوكايــن‬\n     ‫بقصــد الترويــج واختليــت باملدعــى عليهمــا األول والرابــع وال تربطنــي‬\n     ‫بهمــا صلــة قرابــة شــرعية ومــا ذكــره املدعــي العــام صحيــح جملــة‬\n     ‫ا وأجــاب املدعــى عليــه الرابــع ‪ ....‬صحيــح حــزت ثالثــن جرامــا‬      ‫وتفصيـ ً‬\n\n\n‫‪45‬‬\n\f‫وســتة أعشــار اجلــرام مــن مــادة الكوكايــن املخــدر وميــزان الكتروني‬\n‫بــه آثــار الكوكايــن بقصــد الترويــج واختليــت باملدعــى عليهــا املــرأة‬\n‫حجــة وال تربطنــي بهــا صلــة قرابــة شــرعية ومــا ذكــره املدعــي العــام‬\n‫صحيــح جملــة وتفصيــا ا‪ .‬ه ـ وبطلــب البينــة مــن املدعــي العام قــال بينتي‬\n‫مــا جــاء يف أوراق املعاملــة ـ وبعــد اإلطــاع علــى أوراق املعاملــة ومــن‬\n‫ضمنهــا محضــر القبــض املتوافــق مــع مــا ذكــره املدعــي العــام ضــد‬\n‫األول والثالثــة والرابــع أمــا الثانــي فقــد أشــار محضــر القبــض بأنــه قُ بض‬\n‫علــى الثانــي يف غرفــة لــم يوجــد فيهــا شــيء مــن املمنوعــات كمــا أنــه‬\n‫ُف ّتــش حينهــا ولــم يوجــد معــه شــيء مــن املمنوعــات أيضـ ًا كمــا أن األول‬\n‫نفــى عالقــة الثانــي بالتهــم وحيــث إن املدعــي العــام بينتــه هــم شــهود‬\n‫محضــر القبــض الــذي لــم يــرد فيــه شــيء يديــن الثانــي واألصــل البــراءة‬\n‫وألن هــؤالء اجلاليــات جــرت عادتهــم أن يتقاســموا البيــت غرفــة غرفــة‬\n‫وحيــث إن املبلــغ املالــي وقــدره أربعــة آالف وتســعمائة ريــال يخص املدعى‬\n‫عليــه الثانــي حســب وصــف املضبوطــات مبلــف إجــراءات االســتدالل لفــة‬\n‫رقــم (‪ )1‬ص (‪ )7‬وليــس كمــا ذكــر املدعــي العــام وألن التعازيــر‬\n‫تتداخــل وملــا ظهــر مــن نــدم املدعــى عليهــم وتوبتهــم ولعــدم الســوابق لــذا‬\n‫فقــد حكمــت مبــا يلــي ‪ :‬أو ًال ‪ :‬إدانــة املدعــى عليهــم األول والثالثــة‬\n‫والرابــع مبــا أســند إليهــم يف دعــوى املدعــي العــام وحكمــت عليهــم مبــا‬\n‫يلــي ‪ -1‬ســجن كل واحــد منهــم مــدة ســنتني حتتســب منها مــدة اإليقاف‬\n‫التــي أمضاهــا علــى ذمــة هــذه القضيــة وجلــد كل واحــد منهــم خمســن‬\n‫جلــدة مكــررة ســت مــرات بــن كل مــرة واألخــرى مــا ال يقــل عــن‬\n‫أســبوع وغرامــة ماليــة قدرهــا ألفــا ريــال علــى كل واحــد منهــم اســتناد ًا‬\n‫(‪ )60-38‬مــن نظــام مكافحــة املخــدرات ‪ -2‬مصــادرة أجهــزة اجلــوال‬\n\n\n                                                                                      ‫‪46‬‬\n\f     ‫من نوع (‪ ).......‬ذي الرقم املصنعي رقم (‪ )............‬بشريحته الستخدامه‬\n     ‫يف ارتكاب اجلرمية ‪ ،‬وجوال من نوع (‪ ).......‬ذي الرقم املصنعي(‪)............‬‬\n     ‫وجــوال مــن نــوع(‪ )...‬ذي الرقــم املصنعــي(‪ )............‬وجــوال مــن نــوع(‪)...‬‬\n     ‫ذي الرقــم املصنعــي(‪ )............‬وجــوال مــن نــوع (‪ )...‬ذي الرقــم‬\n     ‫املصنعــي(‪ )............‬وجــوال مــن نــوع (‪ )...‬ذي الرقــم املصنعــي(‪)............‬‬\n     ‫اســتناد ًا للفقــرة رقــم (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n     ‫املشــار إليــه ‪ ،‬وإلغــاء اخلدمــة مــن الشــرائح املضبوطــة ‪ ،‬وعــدم صرفهــا‬\n     ‫لهــم مــرة أخــرى ‪ ،‬اســتناد ًا إلــى تعميــم صاحــب الســمو امللكــي وزيــر‬\n     ‫الداخليــة (‪ )9798‬وتاريــخ ‪9‬ـ‪1428/2/10‬هـ‪.‬وذلــك لكونها تســتخدم يف‬\n     ‫التشــكيل العصابي‪-3‬مصــادرة املبلــغ املالــي املضبــوط مــع املدعــى‬\n     ‫عليــه األول وقدرة(‪)300‬ثالثمائــة ريــال ســعودي اســتنادا للفقــرة (‪)2‬مــن‬\n     ‫املــادة(‪ )53‬مــن نظــام مكافحــة املخــدرات املشــار إليــه ‪-4‬إبعادهــم عــن‬\n     ‫اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتهــم وعــدم الســماح لهــم بالعــودة‬\n     ‫إليها اســتناد ًا للفقرة (‪ )2‬من املادة (‪ )56‬من نظام مكافحة املخدرات‬\n     ‫املشــار إليــه ثانيـ ًا ‪ :‬صــرف النظــر عــن دعــوى املدعــي العــام ضــد املدعــى‬\n     ‫عليــه الثانــي لعــدم كفايــة األدلــة وإعــادة جميــع املضبوطــات التــي‬\n     ‫تخصــه وأمــرت باإلفــراج عنــه فــور ًا إذا لــم يكــن إيقافــه متعلقـ ًا بقضيــة‬\n     ‫أخــرى أو كان مقيم ـ ًا إقامــة غيــر نظاميــة اســتناد َا للمــادة ‪ 216‬مــن‬\n     ‫نظــام اإلجــراءات اجلزائيــة وبجميــع ذلــك حكمــت وبعرضــه عليهــم‬\n     ‫قــرروا جميع ـ ًا القناعــة باحلكــم وقــرر املدعــي العــام عــدم القناعــة‬\n     ‫باحلكــم وطلــب رفعــه حملكمــة االســتئناف بالئحــة تقــدم خــال ثالثــن‬\n     ‫يومـ ًا مــن تاريــخ تســجيل القــرار وإال رفعــت املعاملــة بــدون الئحــة وصلــى‬\n     ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n\n\n‫‪47‬‬\n\f                                                           ‫‪1434/03/07‬هـ ‪.‬‬\n          ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف‬\n‫مبكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه‬\n‫احملكمــة بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بجــده املســاعد‬\n‫رقــم(‪ )331176483‬وتاريخ(‪1434/4/20‬هــ) املرفــق بهــا القــرار‬\n‫رقم(‪)3458629‬وتاريخ(‪1434/3/9‬هـ)الصــادر مــن فضيلة الشــيخ‪....../‬‬\n‫القاضــي باحملكمــة اجلزائيــة بجده‪،‬املتضمــن دعــوى املدعــي العــام‬\n‫ضد‪29......./‬عــام تشــادي اجلنســية ورفقــاه ‪ ،‬املتهمــن يف مخــدرات‬\n‫واإلختــاء احملــرم شــرع ًا ‪ ،‬احملكــوم فيــه مبــادون باطنــه ‪ ،‬وبدراســة‬\n‫القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى‬\n‫احلكــم ‪ ،‬واهلل املوفق‪،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه‬\n                                                                       ‫وســلم‪.‬‬\n\n\n\n\n                                                                                 ‫‪48‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":40,"source_page_end":48,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7c51c06c967f290508d4ffa8c25030c51468365c9bc31cfcab5a5b6488bd61a4","normalized_text_hash":"004ecee5aa3e663f548942e0cdcce556cfd9c6cbd78e6167d1306d4e551b8de7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p40-3458629"},{"id":"d0467a00-d020-58a6-abb1-c7fea19795f9","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلبوب احملظورة بقصد الترويج والتعاطي - اإلقرار -تستر -تعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال وإلغاء الشريحة .","document_number":"33341688","case_number":"33422254","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/14","year":"1434","subject":"مخدرات -حيازة احلبوب احملظورة بقصد الترويج والتعاطي - اإلقرار -تستر -تعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال وإلغاء الشريحة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33341688:‬تاريخه ‪1433/7/14:‬هـ‬\n                      ‫رقم الدعوى ‪33422254:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 3428035‬تاريخه‪1434/02/03:‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬حيــازة احلبــوب احملظــورة بقصــد الترويــج والتعاطــي ‪-‬‬\n     ‫اإلقــرار ‪ -‬تســتر‪ -‬تعزيــر بالســجن واجللــد والغرامــة واملنــع مــن الســفر‬\n                                           ‫ومصــادرة اجلــوال وإلغــاء الشــريحة ‪.‬‬\n\n\n\n\n     ‫املادة ‪ -62 -53 -56 -38‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n     ‫ادعــى املدعــى العــام ضــد املدعــى عليــه بحيازتــه احلبــوب احملظــورة‬\n     ‫بقصــد الترويــج ‪ ،‬وتعاطيــه للحبــوب احملظــورة‪ ،‬وطلــب املدعــي العــام‬\n     ‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة‬\n     ‫ومنعــه مــن الســفر ومصــادرة الهاتــف اجلــوال وإلغــاء شــريحته املســتخدم‬\n     ‫يف اجلرميــة وعقوبــة تعزيريــة لقــاء تســتره علــى مصــدر مــا ضبــط ‪ ،‬حيــث‬\n     ‫إنــه مت القبــض علــى املدعــى عليــه بعــد إخباريــة مفادهــا أن املدعــى‬\n     ‫عليــه يقــوم بترويــج احلبــوب احملظــورة‪ ،‬فتــم التنســيق معــه مــن قبــل أحــد‬\n     ‫املصــادر الســرية ومت تزويــد املصــدر باملبلــغ املرقــم ومت تفتيــش املصــدر‬\n     ‫ثــم قابــل املصــدر املدعــى عليــه وعــاد املصــدر ومعــه حبــوب ذكــر أنــه‬\n     ‫اشــتراها مــن املدعــى عليــه ثــم ذهــب أحــد أفــراد الفرقــة القابضــة مــع‬\n     ‫املصــدر وكلــم املتهــم وطلــب إرجــاع احلبــوب للمتهــم فرفــض املتهــم ثــم‬\n\n‫‪49‬‬\n\f‫بعــد ذلــك مت القبــض علــى املتهــم أمــام منــزل والــده وعثــر معــه علــى‬\n‫اجلــوال املســتخدم يف اجلرميــة وصــادق املدعــى عليــه علــى الدعــوى‪ ،‬بنــاء‬\n‫علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه باجللد والســجن‬\n‫والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال وإلغــاء الشــريحة ‪ ،‬صــدق‬\n                                        ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬قاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33422254‬وتاريــخ ‪ 1433/06/23‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331184146‬وتاريــخ ‪ 1433/06/23‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1433/07/01‬ه ـ افتتحــت اجللســة الســاعة ‪12 : 15‬‬\n‫وفيهــا قــدم املدعــي العــام ‪ .......‬دعــواه علــى ‪ ،................/‬البالــغ مــن‬\n‫العمر (‪ )38‬عام ًا ـ ســعودي اجلنســية مبوجب الســجل املدني رقم ‪...........‬‬\n‫متســبب ‪ ،‬اعــزب ‪ ،‬متعلــم ـ يقيــم يف مدينــة الريــاض ‪ ،‬أوقــف بتاريــخ‬\n‫‪1433/4/24‬ه ـ وأحيــل إلــى شــعبة ســجن امللــز مبوجــب أمــر اإلحالــة‬\n‫والتمديــد رقــم (ه ـ ر‪ )51488/5/1‬وتاريــخ ‪1433/5/3‬ه ـ اســتناد ًا‬\n‫للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة‬\n‫(‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪ .‬حيــث إنــه بتاريــخ ‪1433/4/24‬ه ـ‬\n‫قبــض علــى املذكــور مــن قبــل إحــدى فــرق شــعبة املكافحــة والبحــث‬\n‫والتحــري التابعــة لــإدارة العامــة ملكافحــة املخــدرات مبنطقــة الريــاض‬\n‫بناء على املعلومات املتوفرة من احد املصادر الســرية عن قيام املذكور‬               ‫ً‬\n‫بترويــج احلبــوب احملظــورة وأبــدى املصــدر اســتعداده بالتعــاون لإلطاحــة‬\n\n                                                                                        ‫‪50‬‬\n\f     ‫بــه ‪ ،‬فتــم اإليعــاز لــه باألتصــال علــى جوالــه رقــم‪ .....‬وطلــب كميــة مــن‬\n     ‫احلبــوب احملظــورة مبلــغ وقــدره (‪ )100‬مائــة ريــال وكان ذالــك علــى‬\n     ‫مســمع مــن احــد افــراد الفرقــة ‪ ،‬فوافــق علــى ذالــك ‪ ،‬وطلــب املذكــور‬\n     ‫مــن املصــدر احلظــور لوحــده ومقابلتــه يف شــارع أبــو حنيفــة ‪ ،‬وعليــه مت‬\n     ‫تفتيــش املصــدر تفتيشــا دقيقــا وتزويــده باملبلــغ املرقــم قــدره(‪ )100‬مائــة‬\n     ‫ومت تأمــن ســيارة للمصــدر وتوجــه للمذكــور يف مكانــه الــذي حــدده‬\n     ‫ثــم عــاد املصــدر بعــد مايقــارب (‪ )10‬عشــر دقائــق ومعــه (حبتــان يشــتبه‬\n     ‫أن تكونــا مــن حبــوب الكبتاجــون احملظــورة وأفــاد بأنهــا احلبــوب‬\n     ‫املشــتراة مــن املذكــور علــى ذالــك جــرى اإليعــاز للمصــدر باإلتصــال‬\n     ‫علــى املذكــور ومقابلتــه يف نفــس املوقــع ومت تكليــف أحــد افــراد‬\n     ‫الفرقــة مبرافقــة املصــدر ليشــهد علــى ذالــك وبالفعــل توجــه املصــدر‬\n     ‫والفــرد املكلــف إلــى املذكــور ومبقابلــة املذكــور طلــب املصــدر منــه‬\n     ‫إرجــاع احلبــوب احملظــورة املشــتراة فرفــض املذكــور ذالــك وقــال بــأن‬\n     ‫نــوع احلبــوب جيــدة وكان ذالــك علــى مســمع مــن الفــرد املكلــف ثــم‬\n     ‫تــوارى املذكــور عــن األنظــار وعــاد املصــدر والفــرد املكلــف للفرقــة‬\n     ‫بــدون القبــض عليــه ‪ ،‬بعدهــا مت التحــري والبحــث عنــه ‪ ،‬ويف عصــر‬\n     ‫يــوم الســبت املوافــق ‪1433/4/24‬ه ـ وردت معلومــات مفادهــا وجــود‬\n     ‫املذكــور يف الشــارع أمــام منــزل والــده فتــم االنتقــال للموقــع احملــدد‬\n     ‫وبالوصــل إليــه شــوهد املذكــور ومت التعــرف عليــه مــن قبــل الفرقــة‬\n     ‫عندهــا متــت مداهمتــه وضبطــه وبتفتيشــه لــم يعثــر معــه علــى أي مــن‬\n     ‫املمنوعــات ولــم يعثــر معــه علــى املبلــغ املرقــم ‪ ،‬وعثــر معــه الهاتــف‬\n     ‫اجلــوال املســتخدم يف اجلرميــة ويحمــل الرقــم املصنعــي (‪( )............‬مت‬\n     ‫طلــب حجــزه مــع شــريحته مبوجــب اخلطــاب رقــم (ه ـ ر ا ‪)63387/5/‬‬\n\n\n‫‪51‬‬\n\f‫وتاريــخ ‪1433/6/8‬هــ) ‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي‬\n‫الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية‬\n‫املرفــق رقــم (‪/4477‬س) لعام‪1433‬ه ـ احتــواء عينــة احلبتــن املبيعتــن‬\n‫ملــادة االمفيتامــن وهــو مــن املــواد املنبهــة واملدرجــة باجلــدول رقــم (‪ )2‬فئــة‬\n‫(ب) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وبســماع‬\n‫أقوالــه األوليــة و اســتجوابه اعتــرف بتعاطيــه احلبــوب احملظــورة‪ .‬وقــد‬\n‫أســفرت إجــراءات التحقيــق عــن اتهــام ‪ ........ /‬ببيــع (‪ )2‬حبتــن مــن‬\n‫حبــوب األمفيتامــن املنبهــة احملظــورة بقصــد االجتــار الترويــج والتعاطــي‬\n‫وتعاطيــه احلبــوب احملظــورة املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n‫رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر مــا مت بيعــه‬\n‫املعاقــب علــى ذالــك شــرعا‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪-1 :‬مــا‬\n‫تضمنــه اعترافــه حتقيقــا مبحضــر اســتجوابه املنــوه عنــه املــدون علــى‬\n    ‫الصفحتــن رقــم (‪ )2-1‬مــن دفتــر التحقيــق املرفــق علــى اللفــة ( )‪.‬‬\n‫‪ -2‬مــا تضمنــه اعترافــه بالتعاطــي مبحضــر ســماع أقوالــه األوليــة املنــوه‬\n                                                ‫عنــه املرفــق علــى اللفتــن (‪.)4-3‬‬\n‫‪ -3‬مــا جــاء يف محضــر ي البــاغ املنــوه عنهمــا املدونــان علــى الصفحــات‬\n     ‫رقــم (‪ )13-12-2‬يف ملــف إجــراءات االســتدالل املرفــق لفــه رقــم (‪)1‬‬\n‫‪-4‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة رقــم‬\n                                                                              ‫(‪.)........‬‬\n‫وبالبحــث عــن ســوابقه عثــر علــى ســابقة (حيــازة املخــدرات) مســجله‬\n                                                                ‫عليــه حتــى تاريخــه‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n\n\n                                                                                            ‫‪52‬‬\n\f           ‫ونظام ـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم باآلتــي‪:‬‬\n     ‫‪-1‬بعقوبــة الســجن واجللــد والغرامــة املاليــة بحقــه وفقـ ًا للفقــرة (األولــى)‬\n     ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء‬\n     ‫مــا أســند إليــه وإعمــال الفقــرة (األولــى) مــن املــادة (‪ )62‬من نفــس النظام‬\n     ‫بحقــه وتشــديد العقوبــة عليــه وفقــا للفقــرة (ج) مــن البنــد ثانيــا مــن نفــس‬\n                                                                       ‫املــادة املشــار إليهــا‪.‬‬\n     ‫‪ -2‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبتــه‬\n            ‫وفق ـ ًا للفقــرة (األولــى) مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه ‪.‬‬\n     ‫‪ -3‬مصــادرة الهاتــف اجلــوال نــوع (سامســوجن) ذو الرقــم املصنعــي‬\n     ‫(‪ )............‬املســتخدم يف اجلرميــة اســتناد ًا للفقــرة (األولــى) مــن املــادة‬\n                                                      ‫(‪ )53‬مــن النظــام املشــار إليــه‪.‬‬\n     ‫‪ -4‬إلغــاء الشــريحة الهاتفيــة ذات الرقــم (‪ )........‬املســتخدمة يف اجلرميــة‬\n     ‫وعــدم صرفهــا لنفــس املشــترك يف حالــة صــدور احلكــم باإللغــاء وإبــاغ‬\n     ‫الشــركة مصــدرة الشــريحة بذلــك اســتناد ًا لتعميــم صاحــب الســمو‬\n           ‫امللكــي وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ‪.‬‬\n                        ‫‪ -5‬بعقوبة تعزيرية بحقه لقاء تستره على مصدر ما باعه‪.‬‬\n     ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائــا مــا جــاء‬\n     ‫بدعــوى املدعــي العــام غيــر صحيــح هكــذا أجــاب‪ .‬بعــد ذلــك قــررت‬\n     ‫رفــع اجللســة لإلطــاع علــى أوراق املعاملــة والبينــات التــي قدمهــا املدعــي‬\n     ‫العــام وففــي هــذا اليــوم الثالثــاء ‪ 1433/7/8‬افتتحــت اجللســة الســاعة‬\n     ‫الواحــدة وفيهــا حضــر املدعــى عليــه وقــد جــرى ســؤاله مــرة اخــرى عــن‬\n     ‫الدعــوى فأجــاب قائــا ماذكرتــه بجوابــي يف اجللســة املاضيــة غيــر‬\n     ‫صحيــح والصحيــح هــو صحــة ماجــاء يف دعــوى املدعــي العــام وانــا تائــب‬\n\n\n‫‪53‬‬\n\f‫إلــى اهلل عــز وجــل ماعــدا التســتر فلــم اتســتر على املصدر وقد اشــتريتها‬\n‫مــن شــخص ال اعرفــه هكــذا اجــاب بعــد ذلــك جــرى منــا االطــاع علــى‬\n‫اوراق املعاملــة فوجــدت التقريــر الكيميائــي رقمــم‪ /244/4477‬ك‬\n‫وتاريــخ ‪ 1433/5/5‬واملتوافــق مــع ماجــاء يف الئحــة الدعــوى فبنــاء علــى‬\n‫ماتقــدم والقــرار املدعــى عليــه مبــا نســب اليــه مــن قيامــه ببيــع حبتــن‬\n‫مــن حبــوب االمفيتامــن بقصــد االجتــار والتعاطــي وملاجــاء بالتقريــر‬\n‫الكيميائــي املرفــق ومبــا ان ترويــج املخــدرات مــن اكبــر املنكــرات‬\n‫واعظــم اجلرائــم النــه يــؤدي الــى محاربــة الضروريــات اخلمــس التــي‬\n‫حفظهــا االســام وهــي الديــن والنفــس والعقــل والعــرض واملــال ويقضــي‬\n‫علــى املجتمعــات واالفــراد وملاجــاء باملــادة الثامنــة والثالثــن والسادســة‬\n‫واخلمســن والثالثــة واخلمســن والثانيــة والســتني يف فقراتهــا االولــى مــن‬\n‫نظــام مكافحــة املخــدرات ومبــا انــه يتوجــه تعزيــر املدعــى عليــه علــى‬\n‫التســتر اذ انــه يف الغالــب ان مــن يــروج يعــرف املصــدر الــذي اخــذه منــه‬\n‫لذلــك كلــه فقــد صــدر منــا مايلي‪-‬اوال‪:‬ثبــت لــدي ادانــة املدعــى عليــه‬\n‫ببيــع حبتــن مــن حبــوب االمفيتامــن املنبهــة احملظــورة بقصــد الترويــج‬\n‫وتعاطيــه اياهــا وحكمــت بســجنه علــى ذلــك ملــدة خمــس ســنوات تبــدا‬\n‫مــن تاريــخ ايقافــه ثانيــا‪ :‬حكمــت علــى املدعــى عليــه بدفــع غرامــة‬\n                                                             ‫قدرهــا الــف ريــال‬\n‫ثالثــا ‪:‬حكمــت بجلــد املدعــى عليــه مائــة وعشــرين جلــدة مفرقــة علــى‬\n‫ثــاث دفعــات كل دفعــة اربعــون جلــدة بــن كل دفعــة واالخــرى مااليقل‬\n‫عــن عشــرة ايــام رابعــا‪ :‬حكمــت مبنــع املدعــى عليــه مــن الســفر خــارج‬\n‫اململكــة ملــدة خمــس ســنوات بعــد تنفيــذ عقوبــة الســجن عليــه خامســا‪:‬‬\n‫حكمت مبصادرة اجلوال املستخدم يف اجلرمية والغاء الشريحة الهاتفية‬\n\n\n                                                                                    ‫‪54‬‬\n\f     ‫املســتخدمة يف اجلرميــة وعــدم صرفهــا لنفــس املشــترك املشــار اليــه اعــاه‬\n     ‫سادســا‪ :‬حكمــت بتعزيــر املدعــى عليــه علــى التســتر علــى مصــدر مــامت‬\n     ‫بيعــه لتوجــه ذلــك وذلــك بجلــده ثالثــن جلــدة دفعــة واحــدة وبعــرض‬\n     ‫احلكــم علــى املدعــى عليــه قــرر اعتراضــه علــى احلكــم مســتعدا بتقــدمي‬\n     ‫الئحــة اعتراضيــة علــى احلكــم فأفهمتــه مبهلــة االعتــراض وانــه ســوف‬\n     ‫يتــم احضــاره مــن الســجن وتســليمه نســخة مــن احلكــم لتقــدمي اعتراضــه‬\n     ‫ولــه بعــد ذلــك مهلــة شــهر اذا مضــى ولــم يقــدم اعتراضــه ســقط حقــه‬\n     ‫يف تقــدمي االعتــراض ورفــع احلكــم حملكمــة االســتئناف امــا املدعــي‬\n     ‫العــام فقــرر القناعــة باحلكــم واختتمــت اجللســة الســاعة الثانيــة وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                          ‫حــرر يف ‪ 1433/07/08‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق‪ 1433/08/26‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 09: 00‬وفيهــا حضــر املدعــى عليــه وقــدم‬\n     ‫الئحتــه االعتراضيــه املكونــة مــن ورقــة واحــدة وبــاهلل التوفيــق ‪،‬‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                       ‫‪1433/08/26‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األحــد املوافــق ‪1434/1/11‬ه ـ‬\n     ‫فتحــت اجللســة الســاعة الواحــدة وقــد عــادت املعاملــة مــن محكمــة‬\n     ‫االســتئناف بخطــاب فضيلــة رئيســها رقــم ‪ 331885433‬وتاريــخ‬\n     ‫‪1433/11/28‬ه ـ مرفقـ ًا بــه القــرار الصــادر مــن الدائــرة اجلزائيــة األولــى‬\n     ‫برقــم ‪ 33455687‬وتاريــخ ‪1433/11/15‬ه ـ ونصــه ‪ [ :‬وبدراســة القــرار‬\n     ‫وصــورة ضبطــه وأوراق املعاملــة لوحــظ توافــر عــدة موجبــات لتخفيــف‬\n     ‫احلكــم علــى املدعــى عليــه منهــا قلــة الكميــة املضبوطــة ومــا قــرره مــن‬\n\n\n‫‪55‬‬\n\f‫توبــة وعلــى فضيلتــه التأمــل وتقريــر مــا يظهــر لــه حســب املــادة (‪)60‬‬\n‫وبــاهلل التوفيــق ] ‪ .‬أ‪.‬هــ‪ .‬وعليــه أجيــب أصحــاب الفضيلــة حفظهــم اهلل أن‬\n‫املدعــى عليــه قــد ثبــت قيامــه بالترويــج وقــد حكــم عليــه باحلــد األدنــى‬\n‫لعقوبــة الترويــج وكــون الكميــة قليلــة ال يؤثــر يف وصــف الترويــج إذ‬\n‫ال يخفــى أن املــروج يقــوم بالترويــج حســب الكميــة املطلوبــة منــه ومــن‬\n‫روج القليــل روج الكثيــر وجميعــه داخــل يف وصــف الترويــج كمــا‬\n‫أن التوبــة هــي مجــرد دعــوى وجميــع املدعــى عليهــم يدعونهــا ومجــرد‬\n‫دعواهــا غيــر مؤثــر ولــم يظهــر لــي انطبــاق املــادة الســتني علــى املدعــى‬\n‫عليــه واهلل املوفــق واختتمــت اجللســة يف متــام الســاعة الواحــدة والنصــف‪،‬‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                               ‫‪1434/1/11‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫األولــى لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n‫‪ 332218652‬وتاريــخ ‪1434/1/26‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ .......‬املســجل برقــم ‪33341688‬‬\n‫وتاريــخ ‪1433/7/14‬ه ـ اخلــاص بدعــوى املدعــي العــام ض ــد‪ ...........‬يف‬\n‫قضيــة مخــدرات علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل بــه وحيــث ســبق دراســة القــرار وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه‬\n‫فضيلــة القاضــي وإحلاقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا رقــم‬\n‫‪ 33455687‬وتاريــخ ‪1433 /11/15‬ه ـ لــم يظهــر لألكثريــه مــا يوجــب‬\n                            ‫املالحظــة بعــد اإلجــراء األخيــر وبــاهلل التوفيــق‪.‬‬\n\n\n                                                                                      ‫‪56‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":49,"source_page_end":56,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"858c2a6b4db10a7d6ad09b7555c7485d6df0c84a952c58d26aec8fe769009596","normalized_text_hash":"8ebe9ebc3d4132c0f0dd6f40d11ad0cfcd3fbec96c80a17cd224e2c792ab2033","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p49-33341688"},{"id":"2fee1666-18d3-5b24-83fa-4ee894a8b9e3","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إقرار- إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واجللد واملنع من السفر .","document_number":"33321801","case_number":"33422610","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/06/30","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إقرار- إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واجللد واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33321801:‬تاريخه‪1433/06/30 :‬هـ‬\n                         ‫رقم الدعوى‪33422610 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3455396‬تاريخه‪1434/03/04:‬هـ‬\n\n\n       ‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتعاطيهــا‪ -‬إقــرار‪-‬‬\n       ‫إدانــة‪ -‬نــزول عــن احلــد األدنــى للعقوبــة‪ -‬التعزيــر بالســجن واجللــد‬\n                                                            ‫واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n       ‫املــواد (‪ )41‬و (‪ )56‬و (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                  ‫العقليــة‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة حبــة مــن احلبــوب‬\n       ‫احملظــورة احملتويــة علــى اإلمفيتامــن بقصــد التعاطــي وتعاطيــه مــن‬\n       ‫نوعهــا‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام‬\n       ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬حيــث إنــه مت تفتيــش ســيارته‬\n       ‫بعــد اســتيقافها فعثــر حتــت أقدامــه علــى حبــة واحــدة يشــتبه أن تكــون‬\n       ‫مــن احلبــوب احملظــورة‪ ،‬وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة‬\n       ‫العينــة املرســلة ملــادة اإلمفيتامــن‪ ،‬كمــا أقــر املدعــى عليــه أمــام‬\n       ‫احملكمــة مبــا أســنده إليــه املدعــي العــام‪ ،‬بنــاء علــى مــا تقــدم حكمــت‬\n       ‫احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب إليــه وقــررت ســجنه‬\n       ‫ملــدة أربعــة أشــهر وجلــده خمســة وســبعني جلــدة دفعــة واحــدة ومنعــه‬\n\n‫‪57‬‬\n\f‫مــن الســفر خــارج اململكــة مــدة ســنتني‪ ،‬وعــارض واملدعــي العــام علــى‬\n                 ‫احلكــم‪ -‬وصدقــت محكمــة االســتئناف علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعنيــزة برقــم ‪ 33422610‬وتاريــخ ‪1433/06/23‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331183129‬وتاريــخ ‪1433/06/23‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق ‪1433/06/28‬ه ـ افتتحــت اجللســة الســاعة ‪09 :15‬‬\n‫وفيهــا حضــر املدعــي العــام وحضــر حلضــوره ‪ ........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ........‬وادعــى املدعــي العــام قائــا‪ :‬بصفتــي‬\n‫مدعيـ ًا عامـ ًا يف دائــرة التحقيــق واالدعــاء العــام مبحافظــة عنيــزة أدعــي‬\n‫علــى‪ ،.....:‬البالــغ مــن العمــر (‪ )32‬عامـاً‪ ،‬هويــة وطنية رقــم (‪،)...............‬‬\n‫أعــزب ‪ ،‬متعلــم ‪ ،‬متســبب ‪ ،‬يقيــم مبحافظــة عنيــزة ‪ ،‬وأوقــف بتاريــخ‬\n‫ـاء علــى املــادة‬\n                 ‫‪1433/5/11‬ه ـ وأفــرج عنــه بتاريــخ ‪1433/5/15‬ه ـ بنـ ً‬\n‫(‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‪ .‬إنــه بتاريــخ ‪1433/5/11‬ه ـ وأثناء‬\n‫عمــل دوريــات امــن الطــرق علــى طريــق املدينــة ‪ -‬القصيــم الســريع مت‬\n‫اســتيقاف ســيارة مــن نــوع (‪ )......‬بقيــادة املدعــى عليــه ولوحــظ عليــه‬\n‫االرتبــاك‪ ،‬وبتفتيــش الســيارة عثــر حتــت أقدامــه علــى (‪ )1‬حبــة واحــدة‬\n‫حتمــل عالمــة الكبتاجــون يشــتبه أن تكــون محظورة‪.‬وقــد أثبــت‬\n‫التقريــر الكيميائــي الشــرعي املرفــق الصــادر مــن املركــز اإلقليمــي‬\n‫ملراقبــة الســموم بالقصيــم رقــم (‪ )641‬لعــام ‪1433‬ه ـ إيجابيــة مــا أرســل‬\n‫للتحليــل لإلمفيتامــن املنبــه احملظــور املــدرج بجــدول املؤثــرات العقليــة‬\n\n                                                                                        ‫‪58‬‬\n\f     ‫رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة‪ .‬وبســماع أقوالــه أقــر بحيــازة احلبــة املضبوطة بقصد االســتعمال‪.‬‬\n     ‫وباســتجوابه أقــر بحيــازة (‪ )1‬حبــة محظــورة بقصــد االســتعمال وانــه‬\n     ‫يســتعمل احلبــوب احملظــورة منــذ حوالــي ســنة‪.‬وانتهى التحقيــق معــه إلــى‬\n     ‫اتهامــه بحيــازة (‪ )1‬حبــة إمفيتامــن محظــورة وذلــك بقصــد التعاطــي‬\n     ‫وتعاطيــه لنوعها‪.‬وذلــك لألدلــة والقرائــن التالية‪1:‬ـ ـ إقــراره املــدون علــى‬\n     ‫الصفحــة رقــم (‪ )1‬مــن دفتــر التحقيــق املرفــق لفــه (‪ )11‬ومــا جــاء بســماع‬\n     ‫أقوالــه املدونــة علــى الصفحــة رقــم (‪ )7‬مــن اللفــة رقــم (‪2.)1‬ـ محضــر‬\n     ‫القبــض املرفــق لفــة رقــم (‪3.)2‬ـ ـ التقريــر الكيميائــي الشــرعي لفــة‬\n     ‫رقــم (‪ .)13‬وباالطــاع علــى ســوابقه تبــن خلــوه مــن الســوابق‪ .‬وحيــث‬\n     ‫إن مــا أقــدم عليــه املذكــور عليــه فعــل محــرم شــرع ًا ومجــرم نظام ـ ًا‬\n     ‫مبوجــب املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n     ‫الصــادر باملرســوم امللكــي رقــم (م‪ ) 39/‬وتاريــخ ‪1426/7/8‬ه ـ ومعاقب‬\n     ‫عليــه شــرع ًا ونظامـ ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n     ‫بالعقوبــات التاليــة‪ :‬أوالً‪ :‬الســجن وفق ـ ًا للفقــرة األولــى مــن املــادة (‪)41‬‬\n     ‫احلاديــة واألربعــن مــن النظــام املشــار إليــه‪ .‬ثاني ـاً‪ :‬باملنــع مــن الســفر‬\n     ‫خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة الســجن وفق ـ ًا للفقــرة األولــى‬\n     ‫مــن املــادة (‪ )56‬السادســة واخلمســن مــن النظــام املشــار إليــه‪ .‬وبعــرض‬\n     ‫دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n     ‫العــام يف دعــواه صحيــح حيــث قبــض علــي ومعــي احلبــة وقصــدي منهــا‬\n     ‫التعاطــي وأنــا أتعاطــى احلبــوب احملظــورة منــذ ســنة هكــذا أجــاب فبنــاء‬\n     ‫علــى مــا تقــدم وحيــث طلــب املدعــي العــام إثبــات إدانــة املدعــى عليــه‬\n     ‫مبــا أســند إليــه وحيــث أقــر املدعــى عليــه بدعــوى املدعــي العــام لــذا‬\n\n\n‫‪59‬‬\n\f‫فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة حبــة واحــدة مــن احلبــوب‬\n‫احملظــورة وثبــت لــدي إدانتــه بتعاطــي احلبــوب احملظــورة وحكمــت‬\n‫بســجنه ملــدة ســتة أشــهر ويحســب منهــا مــدة إيقافــه الســابقة وذلــك بنــاء‬\n‫علــى املــادة رقــم (‪ )41‬مــن نظــام املخــدرات وجلــده خمســة وســبعني جلــدة‬\n‫دفعــة واحــدة لقــاء تعاطيــه احلبــوب احملظــورة ومنعــه مــن الســفر مــدة‬\n‫ســنتني بنــاء علــى املــادة رقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات هــذا‬\n‫مــا ظهــر لــي وبعرضــه عليهمــا قــرر املدعــي العــام عــدم قناعتــه باحلكــم‬\n‫وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة وقــرر املدعــى عليــه عــدم‬\n‫قناعتــه باحلكــم وطلــب رفعهــا حملكمــة االســتئناف بالئحــة اعتراضيــة‬\n‫وافهــم ان لــه ثالثــون يومــا مــن تاريــخ صــدور الصــك يف يــوم األحــد‬\n‫املوافــق ‪1433/06/29‬ه ـ فــاذا قــدم الئحــة خــال املــدة واال اكتســب‬\n‫احلكــم القطعيــة ففهــم ذلــك وعليــه جــرى التوقيــع وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/06/28‬ه ـ ويف يــوم‬\n‫األحــد املوافــق ‪1433/08/04‬ه ـ افتتحــت اجللســة الســاعة ‪ 30:10‬وفيهــا‬\n‫لــم يقــدم املدعــي عليــه الئحــة اعتراضيــة وقــد تســلم صــورة مــن صــك‬\n‫احلكــم الصــادر برقــم ‪ 33321801‬يف ‪1433/6/30‬ه ـ وقــد مضــت املدة‬\n‫النظاميــة ولــم يقــدم الئحــة اعتراضيــة لــذا اكتســب احلكــم القطعيــة‬\n‫بحــق املدعــي عليــه وســوف ترفــع كامــل املعاملــة إلــى االســتئناف حيــث‬\n‫أن املدعــي العــام لــم يقــرر القناعــة باحلكــم وبــاهلل التوفيــق ‪ ،‬وصلى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1433/08/04‬ه ـ‬\n‫ويف يــوم الثالثــاء املوافــق ‪1433/11/16‬ه ـ ويف متــام الســاعة التاســعة‬\n‫صباحــا عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم‬\n‫‪ 33393945‬وتاريــخ ‪1433/08/26‬ه ـ الصــادر مــن الدائــرة اجلزائيــة‬\n\n\n                                                                                    ‫‪60‬‬\n\f     ‫األولــى مبنطقــة القصيــم واملتضمــن املالحظــة علــى حكمــي مبــا يلــي‪:‬‬\n     ‫(لوحــظ أن ماحكــم بــه فضيلتــه مــن ســجن كثيــر ولعــدم وجــود ســوابق‬\n     ‫فعلــى فضيلتــه إعــادة النظــر والتأمــل) وعليــه فقــد حضــر املدعــي العــام‬\n     ‫وحضــر حلضــوره املدعــى عليــه وملــا ذكــره أصحــاب الفضيلــة مــن‬\n     ‫ـاء علــى املــادة‬\n                    ‫مالحظــة وهــي عــدم وجــود ســوابق علــى املدعــى عليــه وبنـ ً‬\n     ‫الســتني مــن نظــام مكافحــة املخــدرات فقــد رجعــت عــن حكمــي‬\n     ‫الســابق بالنســبة للســجن وحكمــت بســجن املدعــى عليــه ملــدة أربعــة‬\n     ‫أشــهر يحســب منهــا مــدة إيقافــه وأمــا اجللــد واملنــع مــن الســفر فإننــي مــا‬\n     ‫زلــت علــى حكمــي الســابق فيهــا هــذا مــا ظهــر لــي وبعرضــه عليهمــا‬\n     ‫قــرر املدعــى عليــه عــدم قناعتــه باحلكــم وطلــب رفعهــا حملكمــة‬\n     ‫االســتئناف بالئحــة اعتراضيــة وأفهــم بــأن لــه ثالثــون يومــا مــن تاريــخ‬\n     ‫صــدور اإلحلــاق علــى القــرار وافهــم ان يحضــر يــوم غــد األربعــاء املوافــق‬\n     ‫‪1433/11/17‬ه ـ الســتالم صــورة مــن القــرار وبعرضــه علــى املدعــي‬\n     ‫العــام قــرر عــدم قناعتــه باحلكــم مكتفيــا بالئحــة الدعــوى املقدمــة‬\n     ‫معتبــرا إياهــا الئحــة اعتراضيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n     ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/11/16‬ه ـ ويف يــوم‬\n     ‫االثنــن املوافــق ‪ 1434/02/04‬ه ـ افتتحــت اجللســة الســاعة ‪ 10.15‬ولــم‬\n     ‫يحضــر املدعــى عليــه لتقــدمي الئحتــه االعتراضيــة لــذا ســقط حقــه يف‬\n     ‫االعتــراض علــى احلكــم وســوف ترفــع كامــل أوراق املعاملــة حملكمــة‬\n     ‫االســتئناف بالقصيــم لتدقيــق احلكــم لكــون املدعــي العــام معتــرض‬\n     ‫علــى احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n     ‫حــرر يف ‪1434/02/04‬ه ـ ويف يــوم األحــد املوافــق ‪1434/03/15‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 09.45‬وفيهــا عــادت املعاملــة إلينــا مــن‬\n\n\n‫‪61‬‬\n\f‫محكمــة االســتئناف بالقصيــم وبرفقهــا القــرار رقــم ‪ 3455396‬وتاريــخ‬\n‫‪1434/03/04‬ه ـ الصــادر مــن الدائــرة اجلزائيــة األولــى وقــد صــدق‬\n‫احلكــم قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه قاضــي اســتئناف ‪........‬‬\n‫ختمــه وتوقيعــه رئيــس الدائــرة ‪ ........‬ختمــه وتوقيعــه وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/03/15‬هــ‪.‬‬\n\n\n\n\n                                                                                ‫‪62‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":57,"source_page_end":62,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cdcf2c5f655ceae38515834f4fcac2bb8549c1f946ff0b2388501f025782066b","normalized_text_hash":"752ff305f7658474cd40699e1c4f7a70ffef604f9e35cc9d7613bf017d43efab","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p57-33321801"},{"id":"571e77b9-bfcc-5838-b58c-1653abf9fc35","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلبوب احملظورة بقصد التعاطي -تعاطي احلبوب احملظورة -التعزير بالسجن واجللد واملنع من السفر.","document_number":"33447648","case_number":"33423920","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/8","year":"1434","subject":"مخدرات -حيازة احلبوب احملظورة بقصد التعاطي -تعاطي احلبوب احملظورة -التعزير بالسجن واجللد واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33447648:‬تاريخه ‪1433/11/8:‬هـ‬\n                      ‫رقم الدعوى ‪33423920:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 347567‬تاريخه‪1434/01/10:‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬حيــازة احلبــوب احملظــورة بقصــد التعاطــي ‪ -‬تعاطــي‬\n     ‫احلبــوب احملظــورة ‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر‪.‬‬\n\n\n\n\n                 ‫‪ -1‬قوله تعالى (وال تقتلوا النفس التي حرم اهلل إال باحلق)‬\n                      ‫‪ -2‬قوله تعالى ( وال تفسدوا يف األرض بعد إصالحها)‬\n                  ‫‪ -3‬واملادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n                   ‫‪ -4‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n     ‫الئحــة الدعــوى ضــد املدعــى عليــه بحيــازة احلبــوب احملظــورة بقصــد‬\n     ‫التعاطــي (تعاطــي احلبــوب احملظــورة) وطلــب املدعــي العــام إثبــات مــا‬\n     ‫أســند إليــه واحلكــم عليــه بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة‬\n     ‫(‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ومنعــه مــن‬\n     ‫الســفر خــارج البــاد‪ ،‬مت القبــض علــى املدعــى عليــه بعــد اســتيقافه‬\n     ‫واالشــتباه بــه وبتفتيشــه ضبــط معــه علــى كميــة مــن احلبــوب احملظــورة‪،‬‬\n     ‫إقــرار املدعــى عليــه بالدعــوى‪ ،‬تعزيــر املدعــى عليــه بالســجن واجللــد‬\n              ‫واملنــع مــن الســفر‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n‫‪63‬‬\n\f‫ـدي أنــا‬\n      ‫احلمــدهلل وحــده والصــاة والســام علــى َمــنْ النبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى املعاملــة الــواردة‬\n                           ‫‪ ......‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء برقــم هـ ف‬\n‫‪ ......‬وتاريخ‪......‬واملقيــدة بهــذه احملكمــة برقم‪.......‬وتاريخ‪........‬واحملالــة‬\n‫إلينــا مــن فضيلــة الرئيــس برقم‪......‬وتاريخ‪......‬فتحــت اجللســة األولــى يــوم‬\n‫االثنــن ‪......‬الســاعة الثانيــة عشــرة والنصــف وفيهــا حضــر املدعــي العــام‬\n‫‪ .....‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب ســعادة‬\n‫رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء ذي الرقــم ه ـ‬\n‫ال ‪ :‬بصفتي مدعي ًا‬   ‫وقرر دعواه قائ ً‬‫ق‪ 137/2/2‬والتاريخ ‪1431/1/5‬هـ ّ‬\n‫عامـ ًا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى ‪،.....:‬البالــغ‬\n‫مــن العمــر (‪ )25‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪).....‬موظــف حكومي‪،‬محصــن‪ ،‬قبــض عليــه بتاريــخ‪ ......‬وأفــرج‬\n‫عنــه بالكفالــة بتاريــخ ‪.......‬يســكن محافظــه اإلحســاء‪ .‬انــه بتاريــخ‬\n‫‪........‬قبــض عليــه مــن قبــل أمــن الطــرق أثنــاء مــروره بنقطــة التفتيــش‬\n‫وبقيادتــه ســيارة مــن نــوع ( فــورد ) صنــع عــام (‪ )2000‬حتمــل لوحــة رقــم‬\n‫(‪ )......‬وباســتيقافه وتفتيشــه عثــر بداخــل علبــة مشــروب( بايســن) علــى‬\n‫حبــة بيضــاء مرســوم عليهــا العالمــة املميــزة للكبتاجون‪،‬كمــا عثــر‬\n‫علــى كيــس نايلــون يحتــوي علــى عشــر حبــات بيضــاء اللــون مرســوم‬\n‫عليهــا العالمــة املميــزة للكبتاجــون ‪،‬وقــد أثبــت التقريــر الكيمــاوي‬\n‫الشــرعي رقــم (‪2092‬ك ش) لعــام ‪1433‬ه ـ إيجابيــة العينــة املرســلة‬\n‫ملــادة األمفيتامــن واملدرجــة يف اجلــدول رقــم (‪ )2‬فئــة (ب) مــن نظــام‬\n\n                                                                                      ‫‪64‬‬\n\f     ‫مكافحــة املخــدرات واملؤثــرات العقليــة املوافــق عليــه باملرســوم امللكــي‬\n     ‫رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هـ‪.‬وبضبــط أقوالة‪/‬اعتــرف بحيــازة‬\n     ‫(‪ )11‬إحــدى عشــرة حبــة مــن احلبــوب املنبهــة احملظــورة بقصــد التعاطــي‬\n     ‫‪ ،‬كمــا اعتــرف بتعاطيــه لنوعهــا علــى مــدى خمــس ســنوات ‪.‬وقــد أســفر‬\n     ‫التحقيــق عــن توجيــه االتهــام لــه بحيــازة (‪ )11‬إحــدى عشــرة حبــة مــن‬\n     ‫احلبــوب املنبهــة احملظــورة بقصــد التعاطــي وتعاطيــه لنوعهــا يف ضــوء مــا‬\n     ‫جــاء يف الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة الصــادر باملرســوم امللكــي الكــرمي رقــم (م‪)39/‬‬\n                          ‫وتاريــخ ‪1426/7/8‬ه ـ وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n     ‫‪ -1‬اعترافــه املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )2‬مــن دفتــر ســماع‬\n                                               ‫األقــوال املرفــق علــى اللفــة رقــم (‪. )12‬‬\n                                      ‫‪ -2‬محضر القبض املرفق على اللفة رقم (‪. )4‬‬\n                               ‫‪ -3‬التقرير الكيماوي املرفق على اللفة رقم (‪. )31‬‬\n     ‫وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق مســجلة‬\n     ‫‪.‬وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n     ‫فعــل محــرم ومجــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا اطلــب إثبــات مــا‬\n                                                ‫أســند إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n     ‫‪ -1‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء مــا اســند إليــه اتهــام‪.‬‬\n     ‫‪ -3‬منعــة مــن الســفر خــارج البــاد وفق ـ ًا للفقــرة األولــى مــن املــادة (‪)56‬‬\n     ‫مــن النظــام املشــار إليــه ‪ .‬عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد‬\n     ‫مــن هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب قائ ـاً‪:‬‬\n     ‫صحيــح مــا نســبه لــي املدعــي العــام مــن واقعــة القبــض ومــن حيازتــي‬\n\n‫‪65‬‬\n\f‫لعــدد إحــدى عشــرة مــن حبــوب االمفيتامــن املخــدر بقصــد التعاطــي‬\n‫‪.‬ومــن اســتعمالي للحب ــوب احملظــورة وصحيــح اعتــرايف هكــذا أجــاب‬\n‫هــذا وقــد جــرى االطــاع علــى التقريــر الكيمــاوي الشــرعي الصــادر‬\n‫مــن قســم الكيميــاء الشــرعيـ ــة باملركـ ــز اإلقليمـ ــي ملراقبــة السمـ ــوم‬\n‫التــابـ ــع للمـ ــديرية العامـ ــة للش ــؤون الصحية باملنطق ـ ــة الشــرقيـ ــة برقـ ــم‬\n‫(‪ 2092‬ك ش) لعــام ‪1433‬ه ـ املتضمــن إيجابيــة عي ــنة مــا ضبــط‬\n‫للحبــوب احملظــورة كمــا جــرى االطــاع علــى كــرت ســوابق املدعــى‬\n‫عليــه املتضمــن خلــوه مــن الســوابق فبنــاء علــى مــا ورد مــن الدعــوى‬\n‫واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن أهليتــه وملــا‬\n‫ورد يف محضــر القبــض واعتــراف املدعــي عليــه ومبــا أنــه صــادق علــى‬\n‫صحــة مــا نســب إليــه مــن حيــازة احلبــوب احملظــورة علــى صفــة مــا ورد‬\n‫يف الدعــوى ومبــا أن مــا صــدر منــه حــرام يف الشــريعة ملــا يف احلبــوب‬\n‫احملظــورة مــن اخلطــر و الضــرر علــى البــاد والعبــاد وعلــى مــن صــدر‬\n‫منــه ذلــك قــال تعالــى (وال تقتلــوا النفــس التــي حــرم اهلل إال باحلــق) وقــال‬\n‫(وال تفســدوا يف األرض بعــد إصالحهــا) ممــا يســتوجب معاقبــة املدعــى‬\n‫عليــه و تعزيــزه بالعقوبــة الــواردة يف املــادة الواحــدة واألربعــن مــن نظــام‬\n‫مكافحــة املخــدرات ويتوجــه أن يكــون أقــل عقوبــة ملــا ظهــر مــن حالــه‬\n‫مــن النــدم وألنــه ال ســوابق لــه ولصغــر ســنه كمــا يتوجــه تخفيــف تلــك‬\n‫العقوبــة أيضــا حســب مقتضــى املــادة الســتني مــن النظــام نفســه ملــا‬\n‫ظهــر مــن حالــه مــن النــدم ولصغــر ســنه ولظروفــه االجتماعيــة التــي‬\n‫اقتنعــت بهــا احملكمــة وألنــه ال ســوابق لــه كمــا يتوجــه اســتحقاقه‬\n‫للعقوبــة الــواردة يف املــادة السادســة واخلمســن الفقــرة األولــى منهــا‬\n‫ومبــا أ َّنــه أقــر باســتعمال احلبــوب احملظــورة واســتعمالها ال يأخــذ‬\n\n\n                                                                                             ‫‪66‬‬\n\f     ‫حكــم املســكر لعــدم التوافــق بينهمــا يف منــاط احلكــم ممــا يتوجــه‬\n     ‫معــه تعزيــر املدعــى عليــه باجللــد دون حــد املســكر لــذا كلــه وألجــل‬\n     ‫ـدي إدانــة‬\n               ‫احلــق العــام حكمــت علــى املدعــى عليــه باآلتــي‪ :‬أوالً‪ /‬ثبــت لـ َّ‬\n     ‫املدعــى عليــه باســتعمال احلبــوب احملظــورة ويجلــد تعزيــز ًا لقــاء ذلــك‬\n     ‫بجلــده خمســة وســبعون جلــد ًة دفعــة واحــدة علنـ ًا ثانيــا‪ /‬ثبــت لــدي إدانــة‬\n     ‫املدعــى عليــه بحيــازة احلبــوب احملظــورة املوصوفــة يف الدعــوى البالــغ‬\n     ‫عددهــا إحــدى عشــرة حبــة بقصــد التعاطــي وأن يعــزر بســجنه أربعــة‬\n     ‫أشــهر حتتســب منهــا املــدة التــي أوقــف فيهــا علــي ذمــة القضيــة وذلــك‬\n     ‫مبوجــب املــادة الواحــدة و األربعــن مــن نظــام مكافحــة املخــدرات‬\n     ‫واملــادة الســتني‪ .‬ثالثــا‪ /‬وأن مينــع مــن الســفر مــدة عامــن حســب مقتضــى‬\n     ‫مــا ورد يف املــادة السادســة واخلمســن مــن النظــام نفســه علــى أن يكــون‬\n     ‫املنــع ابتــداء مــن انتهــاء محكومتيــه وبتــاوة احلكــم علــى الطرفــن‬\n     ‫وإفهــام املدعــى عليــه بحقــه يف التمييــز قــرر قناعتــه باحلكــم وطلــب‬\n     ‫املدعــي العــام رفــع احلكــم للتمييــز وأن الئحتــه االعتراضيــة هــي الئحــة‬\n     ‫الدعــوى هــذا وجــرى توجيــه املدعــى عليــه مبــا يلــزم ومــن ذلــك حرمــة‬\n     ‫اســتعمال احلبــوب احملظــورة وأثــره الســيئ علــى العقــل واملــال وأقفلــت‬\n     ‫اجللســة الســاعة الواحــدة وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                            ‫وصحبــه أجمعــن حــرر احلكــم يف ‪.......‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء برقــم ‪.......‬‬\n     ‫وتاريــخ ‪.......‬املقيــدة لــدى احملكمــة برقــم ‪ ........‬وتاريــخ ‪......‬املرفــق بهــا‬\n     ‫القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ .........‬املســجل‬\n\n\n‫‪67‬‬\n\f‫برقــم ‪ ..........‬وتاريــخ ‪......‬اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ......../‬يف‬\n‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                            ‫وصحبــه وســلم حــرر يف ‪............‬‬\n\n\n\n\n                                                                                   ‫‪68‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":63,"source_page_end":68,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9badecfc4c93996ff55250e8674248f7b0c6f683f312bf79908cb28b11d43e23","normalized_text_hash":"99901d62b48e68b1bb05473ee1b704b78167a7dffc7b66d982f5302d34a47f9b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p63-33447648"}]$archive_payload$::jsonb) AS x LIMIT 25
